/* manual-i18n.js — Manual completo em espanhol, francês, alemão, japonês, chinês e coreano (30/10/2026).
   Carregado depois de manualupd.js; inglês e português continuam em app.js + manualupd.js. */
(function(){if(typeof MANUAL==="undefined")return;
MANUAL.es={fvUpdated:true,toc:[["m-ciclo","Cómo funciona"],["m-inicio","Primeros pasos"],["m-perfil","Perfil del piloto"],["m-escala","Escala"],["m-livre","Vuelo libre (freelancer)"],["m-reservar","Programación"],["m-antes","Antes del vuelo"],["m-rastreio","Vuelo rastreado"],["m-reporte","Tras el aterrizaje"],["m-frota","Flota"],["m-manut","Mantenimiento automático"],["m-oper","Operación realista"],["m-mapa","Mapa y detalles del vuelo"],["m-brief","Briefing, ADC y NOTAMs"],["m-redes","IVAO y VATSIM"],["m-diario","Diario, salario y catálogo"],["m-apoie","Apoya"],["m-faq","Preguntas frecuentes"]],body:"\n<p class=\"muted manual-updated\">Actualizado el 30 de octubre de 2026.</p>\n<section id=\"m-ciclo\"><h3>Cómo funciona Virtual Flight Report</h3>\n<p><b>Cada vuelo deja su huella.</b> Virtual Flight Report es un libro técnico compartido: cada aeronave se identifica por su matrícula y todo piloto que la vuela, en MSFS o X-Plane, registra lo que le ocurrió. El siguiente piloto encuentra la aeronave exactamente como la dejó el anterior.</p>\n<div class=\"cycle\"><span class=\"cy-step\">Generar la escala</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">Revisar el libro técnico</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">Volar en el simulador</span><span class=\"cy-arrow\">→</span><span class=\"cy-step strong\">Reportar el vuelo</span></div>\n<div class=\"cycle out\"><span class=\"chip ok\">Falla corregida: sigue disponible</span><span class=\"chip warn\">Diferida (MEL): vuela con restricción</span><span class=\"chip bad\">En tierra: liberada tras la reparación</span></div>\n<p class=\"muted\">Cada falla trae su propia consecuencia: según la falla elegida, la app decide sola si la aeronave sigue disponible, vuela con restricción o queda en tierra, y por cuánto tiempo.</p></section>\n\n<section id=\"m-inicio\"><h3>Primeros pasos</h3>\n<p>Necesitas una cuenta de piloto, creada una sola vez; vale en todos tus dispositivos.</p>\n<ol><li>Abre <b>flyvfr.com.br</b> y toca <b>Entrar</b>.</li><li>Toca <b>¿Piloto nuevo? Crea una cuenta</b>.</li><li>Indica tu <b>nombre de piloto</b> (nombre o indicativo que verán los demás), tu <b>correo</b>, los <b>simuladores que usas</b> y una <b>contraseña</b> de al menos 6 caracteres. Para cambiar los simuladores después, toca <b>Perfil</b>, junto a tu nombre.</li><li>Toca <b>Crear cuenta</b>. Las próximas veces, usa <b>Entrar</b>.</li></ol>\n<p>Al entrar, la app abre en <b>Programación</b> si ya tienes una escala aceptada; si no, abre en <b>Escala</b>. El menú sigue el día del piloto: Escala, Sala de briefing (habilitada con escala aceptada), Reservas, Flota, Mapa, Eventos, Diario de a bordo, Catálogo, Manual y Apoya.</p>\n<div class=\"scroll\"><table><thead><tr><th>Dispositivo</th><th>Cómo instalar</th></tr></thead><tbody>\n<tr><td>PC (Chrome o Edge)</td><td><b>Instalar app</b> en la parte superior de la página o el icono de instalación de la barra de direcciones</td></tr>\n<tr><td>Android</td><td>En Chrome: menú ⋮ → <b>Instalar app</b> (o el archivo <b>VirtualFlightReport.apk</b>, si el administrador lo comparte)</td></tr>\n<tr><td>iPhone o iPad (Safari)</td><td><b>Compartir</b> → <b>Añadir a pantalla de inicio</b></td></tr></tbody></table></div>\n<p>En <b>Ajustes</b> (en el menú) eliges el idioma por su bandera (inglés, portugués, español, francés, alemán, japonés, chino o coreano), el tema de colores y la posición del menú. El botón <b>DAY MODE / NIGHT MODE</b> alterna entre página clara y oscura. Tus elecciones quedan guardadas en el dispositivo. Las mejoras de la app llegan solas al PC y al móvil, sin reinstalar. Para salir, toca <b>Salir</b>, junto a tu nombre.</p><p><b>Perfil del piloto.</b> En el registro eliges cómo vas a volar: <b>Piloto de aerolínea</b> o <b>Freelancer</b>. Quien ya tenía cuenta elige en su próximo acceso. Consulta <a href=\"#m-perfil\" data-action=\"man-jump\" data-to=\"m-perfil\">Perfil del piloto</a>.</p></section>\n<section id=\"m-perfil\"><h3>Perfil del piloto: aerolínea o freelancer</h3>\n<div class=\"scroll\"><table><thead><tr><th></th><th>✈ Piloto de aerolínea</th><th>🛩 Freelancer</th></tr></thead><tbody>\n<tr><td>Flota que vuela</td><td>Solo la flota de las aerolíneas</td><td>Solo la flota de freelancers: la aeronave que registró y las registradas por otros freelancers</td></tr>\n<tr><td>Cómo reserva</td><td><b>Escala</b>: vuelos RPL o escala libre, generados por la app</td><td><b>Vuelo libre</b>: un tramo o una secuencia de tramos que arma el propio piloto</td></tr>\n<tr><td>Aerolínea</td><td>Cualquier aerolínea, pero solo después de cumplir la última escala</td><td>—</td></tr>\n<tr><td>Ranking</td><td>Pestaña <b>Pilotos de aerolínea</b></td><td>Pestaña <b>Freelancers</b></td></tr></tbody></table></div>\n<ul><li><b>Cambiar de perfil:</b> toca <b>Cambiar perfil</b> arriba en la Escala (o en el Vuelo libre). Se puede cambiar <b>una vez cada 30 días</b> y solo <b>sin vuelos reservados</b> pendientes. La pantalla muestra la fecha del próximo cambio posible.</li>\n<li><b>Flota compartida de los freelancers:</b> al registrar una aeronave, el freelancer confirma que otros freelancers podrán volarla y que él puede volar las de ellos. La posición y el libro técnico son los mismos para todos: el próximo vuelo sale de donde aterrizó el último.</li>\n<li><b>Matrícula única:</b> no se puede registrar una matrícula que ya existe en la flota.</li>\n<li>El ranking del Diario de a bordo tiene dos pestañas; cada vuelo cuenta en la pestaña de la flota de la aeronave usada.</li></ul></section>\n\n<section id=\"m-escala\"><h3>Escala de vuelos</h3>\n<p>El menú <b>Escala</b> ofrece dos modos:</p>\n<ul><li><b>Vuelo libre:</b> elige el aeródromo de origen, la aerolínea y la aeronave, sin depender de una salida RPL.</li><li><b>Vuelos RPL:</b> consulta las salidas entre <b>30 y 90 minutos a partir de ahora</b>. El RPL cubre vuelos domésticos dentro de Brasil e internacionales que salen de Brasil o llegan a él. Al elegir un vuelo, selecciona una aeronave elegible de la aerolínea y del modelo compatible con el RPL.</li><li><b>Sin opción RPL elegible:</b> si no hay vuelo con aeronave elegible, o no hay RPL registrado para el aeródromo, la elección de aerolínea y aeronave queda libre.</li><li><b>Favoritas:</b> las aeronaves favoritas tienen prioridad en la elección de aerolínea y aeronave, en ambos modos.</li></ul>\n<p>Define la primera salida, la duración de 1 a 4 días y la cantidad de vuelos por día. Cada tramo empieza donde termina el anterior. El generador considera tiempos en tierra, jornada y descanso; revisa la secuencia antes de aceptar.</p>\n<p>Puedes generar nuevas opciones antes de aceptar. Al tocar <b>Aceptar escala</b>, confirma los vuelos: <b>la escala aceptada no se puede modificar</b>. La aceptación habilita el briefing y los botones SimBrief y SkyVector de cada vuelo.</p>\n<p><b>ADS-B es solo consulta.</b> La información de aeronaves en tierra indica su fuente y su actualización. No cambia la disponibilidad, la elección de la aeronave, la posición operativa en la app ni la escala; la presencia de un avión real no determina el vuelo generado.</p>\n<p>Consulta las tarjetas y avisos de cada vuelo en <b>Programación</b>. Los vuelos concluidos o cancelados no reabren la tabla operativa de la escala.</p><p><b>Demora (DLA) y no presentación:</b> la EOBT (hora estimada de fuera de calzos) aparece en la tarjeta del vuelo en Tu programación. Si vas a retrasarte, toca <b>Demora (DLA)</b> y elige la nueva EOBT: <b>una DLA por vuelo</b>, presentada hasta <b>35 min después de la EOBT prevista</b>, con la nueva EOBT a <b>no más de 45 min desde el momento en que se presenta la DLA</b>. Los vuelos siguientes de la misma jornada se retrasan lo mismo. La propagación se detiene en el pernocte, conservando los horarios de la jornada siguiente. Si el vuelo rastreado no se inicia en <b>45 min desde la EOBT vigente</b>, el vuelo se cancela y aparece un aviso en Reservas. Pasada la EOBT, la tarjeta muestra en rojo la hora límite.</p></section>\n<section id=\"m-livre\"><h3>Vuelo libre (freelancer)</h3>\n<p>Para el freelancer, el menú <b>Escala</b> se convierte en <b>Vuelo libre</b>. No hay generación de escala: tú armas los vuelos.</p>\n<ol><li>Elige una <b>aeronave</b> de la flota freelancer (la lista indica “mía” o quién la registró, y dónde está).</li>\n<li>El <b>origen del primer tramo</b> es donde estará la aeronave; si nunca voló, eliges el origen.</li>\n<li>Indica el <b>destino</b> y la <b>hora de salida</b> (al menos 30 min desde ahora). La app calcula distancia, tiempo de calzos y llegada, y comprueba el alcance de la aeronave.</li>\n<li>Para seguir el viaje, toca <b>＋ Añadir tramo</b>: el siguiente sale de donde aterriza el anterior, con salida sugerida 1 h después de la llegada (mínimo 45 min entre llegada y nueva salida). Quita un tramo con ✕. Hasta 24 tramos.</li>\n<li>Los números de vuelo se sugieren en secuencia y se pueden editar. Toca <b>Reservar vuelo libre</b> (o <b>Reservar N vuelos libres</b>).</li></ol>\n<p>Tras la reserva, todo sigue como en una escala: Programación, Sala de briefing, vuelo rastreado y reporte tras el aterrizaje.</p></section>\n\n<section id=\"m-reservar\"><h3>Programación de los vuelos</h3>\n<p>La pestaña <b>Programación</b> empieza con <b>Tu programación</b>: una tarjeta por cada vuelo tuyo, con la foto de la aeronave, la matrícula en los colores de la aerolínea, número de vuelo y ruta, fecha y hora (local y UTC) y la aerolínea.</p>\n<div class=\"scroll\"><table><thead><tr><th>En la tarjeta</th><th>Qué significa</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">✓ Ningún ítem abierto en el diario</span></td><td>Parpadea una vez como aviso. Nada que firmar: <b>Vuelo rastreado</b> y <b>Reportar vuelo</b> ya están habilitados</td></tr>\n<tr><td><span class=\"chip warn\">⚠ Revisar libro técnico</span></td><td>Sigue parpadeando: la aeronave tiene un ítem abierto. Tócalo, lee los ítems y firma (ver <b>Antes del vuelo</b>)</td></tr>\n<tr><td><span class=\"chip ok\">✓ Libro técnico revisado</span></td><td>Ya firmaste; puedes volar</td></tr></tbody></table></div>\n<ul><li><b>SimBrief</b> y <b>SkyVector</b>: botones con el icono de cada sitio, a la derecha, abren la planificación del vuelo respectivo. SimBrief también recibe la identificación de la aeronave y la EOBT; SkyVector recibe la ruta y las estimaciones de crucero.</li><li><b>METAR y TAF:</b> pasa el ratón sobre el código de un aeropuerto (tócalo en el móvil). Toca <b>Decodificado</b> para leer el informe en lenguaje claro (viento, visibilidad, nubes, temperatura, presión y cada período del TAF); <b>Original</b> vuelve a mostrar el texto bruto. La app recuerda tu elección.</li></ul>\n<p>Las reservas de la escala se crean al aceptarla. Usa las tarjetas de los vuelos para revisar el libro técnico, rastrear y reportar el vuelo. Las acciones administrativas y de eventos dependen de las opciones disponibles para la cuenta.</p></section>\n\n<section id=\"m-antes\"><h3>Antes del vuelo</h3>\n<p>Antes de volar, mira el botón del libro técnico en la tarjeta del vuelo:</p>\n<ul><li><b>Ningún ítem abierto</b> (verde): no hace falta firmar. Solo toca <b>Vuelo rastreado</b> o <b>Reportar vuelo</b>.</li><li><b>Ítem abierto</b> (amarillo parpadeante): toca <b>Revisar libro técnico</b>, lee los ítems abiertos y los últimos reportes, marca la confirmación y toca <b>Firmar libro técnico</b>. El botón se vuelve verde y muestra <b>Libro técnico revisado</b>. Sin esa firma no se aceptan el rastreo ni el reporte.</li><li>Si otro piloto reporta una falla en esa matrícula después de tu firma, el botón amarillo vuelve y tienes que firmar de nuevo.</li></ul>\n<p>Una falla no pasa de un simulador a otro, por eso cada ítem diferido trae un <b>procedimiento para la próxima tripulación</b> que sigues en tu vuelo. Ejemplo: <i>la APU no arranca</i> → pedir GPU y aire externo en tierra.</p></section>\n\n<section id=\"m-rastreio\"><h3>Vuelo rastreado</h3>\n<p>El <b>rastreo validado</b> es la forma normal de registrar un vuelo y contar horas, rango, salario y ranking. La app lee la telemetría del simulador y el servidor verifica la trayectoria. Sin rastreo validado, solicita revisión cuando esté disponible: un administrador decide, sin conclusión del vuelo ni recompensas antes de la aprobación.</p>\n<ol><li>En la tarjeta del vuelo en <b>Tu programación</b>, toca <b>✈ Vuelo rastreado</b> (disponible desde 1 h antes del horario reservado; si hay un ítem abierto, firma antes el libro técnico).</li>\n<li>Con la aeronave detenida en la puerta de salida, toca <b>Conectar al simulador</b>.<ul>\n<li><b>MSFS 2020/2024:</b> instala <a href=\"https://fsuipc.com\" target=\"_blank\" rel=\"noopener\">FSUIPC7</a> (basta la versión gratuita) y el <a href=\"http://fsuipcwebsockets.paulhenty.com/\" target=\"_blank\" rel=\"noopener\">FSUIPC WebSocket Server</a>, y mantén ambos abiertos con el simulador.</li>\n\n<li><b>X-Plane 12</b> (12.1.4 o más reciente): nada que instalar.</li>\n<li><b>X-Plane 11:</b> plugin XPUIPC + FSUIPC WebSocket Server.</li>\n<li>Usa Chrome o Edge en el mismo ordenador del simulador. Si el navegador pide acceso a la red local, permítelo.</li></ul></li>\n<li>Vuela con normalidad y mantén la pestaña abierta. La pantalla <b>Vuelo en vivo</b> muestra fase, altitud, velocidad, velocidad vertical y distancia al destino; mientras tanto puedes usar otras pantallas.</li>\n<li>Tras aterrizar, estaciona y detén la aeronave. Toca <b>Terminar vuelo</b>: el servidor verifica la trayectoria y muestra el resultado. Luego completa el reporte (fallas y observaciones); el tiempo de calzos y el aeropuerto de llegada vienen del rastreo.</li></ol>\n<p>El servidor rechaza el vuelo si no empieza en tierra en el aeropuerto de salida · no termina detenido en un aeropuerto · usa aceleración de tiempo o slew · la aeronave salta de posición (teletransporte o movimiento por el mapa) · el rastreo se interrumpe más de 10 min en el aire · la trayectoria no llega al servidor en tiempo real · el vuelo dura menos de 5 min en el aire. Pausar está permitido: el tiempo en pausa se descuenta. Se aceptan desvíos: la aeronave queda donde aterrizó.</p></section>\n\n<section id=\"m-reporte\"><h3>Tras el aterrizaje: reportar el vuelo</h3>\n<ol><li>Toca <b>Reportar vuelo</b>.</li><li>Elige el <b>simulador</b> (solo aparecen los tuyos; para otro, elige <b>Otro simulador…</b>) e indica el <b>tiempo de calzos</b> (h:mm, p. ej. <code>1:45</code>).</li><li>Para cada falla, toca <b>Añadir falla</b>; si no pasó nada, no añadas ninguna.</li><li>Toca <b>Enviar reporte y cerrar la reserva</b>.</li></ol>\n<p>El campo de falla muestra las <b>más reportadas por tripulaciones de aerolínea</b>. Empieza a escribir y la lista se reduce: entiende varios idiomas, ignora acentos y conoce términos como <code>brake</code>, <code>door</code>, <code>APU</code>, <code>ata 32</code> o <code>ECAM</code>. Si no está en el catálogo, elige <b>No está en la lista: descríbela</b>.</p>\n<p>El piloto no elige la acción ni el tiempo: vienen de la falla elegida en el catálogo. Para fallas fuera del catálogo, la app usa el valor predeterminado más común del capítulo ATA indicado.</p><div class=\"scroll\"><table><thead><tr><th>Consecuencia</th><th>Efecto en la aeronave</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">Corregida por la tripulación</span></td><td>Ninguno; queda solo en el historial</td></tr>\n<tr><td><span class=\"chip warn\">Diferida (MEL)</span></td><td>Vuela con restricción hasta el plazo (Cat B 3 días, Cat C 10 días, Cat D 120 días); después, en tierra durante el tiempo de reparación</td></tr>\n<tr><td><span class=\"chip bad\">Aeronave en tierra</span></td><td>No disponible durante el tiempo medio de reparación, contado desde el reporte</td></tr></tbody></table></div></section>\n\n<section id=\"m-frota\"><h3>Flota</h3>\n<p>La pestaña <b>Flota</b> muestra la situación de cada matrícula. Arriba, los <b>totales siguen los filtros</b>: aeronaves de la selección, disponibles ahora, en vuelo ahora, reservadas en las próximas 24 h y con restricción o en tierra.</p>\n<ul><li><b>Filtros en una sola fila:</b> región, aerolínea, tipo, situación y <b>Ordenar</b> (voladas recientemente, más voladas, disponibles primero o matrícula), además de la búsqueda por matrícula, tipo o aeropuerto (p. ej. <code>SBGR</code>) y el botón <b>Favoritas</b>.</li>\n<li><b>Agrupada por modelo:</b> cada grupo muestra cuántas aeronaves tiene y cuántas están disponibles.</li>\n<li><b>Una fila por aeronave:</b> matrícula, tipo, <b>dónde está</b>, <b>último vuelo</b> (p. ej. “SBGR → SBSV · hace 2 d”) o el próximo evento, <b>historial</b> (vuelos y horas en VFR) y situación. Las disponibles muestran solo un punto verde; las insignias de color señalan las excepciones.</li>\n<li><b>Ventana estrecha</b> (medio monitor): la fila se reorganiza en dos líneas para que nada quede cortado. En el móvil, la flota aparece en tarjetas.</li>\n<li><b>Más aeronaves:</b> toca <b>Mostrar más</b> al final. <b>Registrar:</b> <b>Añadir aeronave</b>.</li></ul>\n<div class=\"scroll\"><table><thead><tr><th>Situación</th><th>Qué significa</th><th>¿Se puede volar?</th></tr></thead><tbody>\n<tr><td><span class=\"fv-ok\">Disponible</span></td><td>Ningún ítem abierto y sin uso en las próximas 24 h</td><td>Sí</td></tr>\n<tr><td><span class=\"pill fv-fly\">En vuelo</span></td><td>Un piloto tiene la aeronave ahora; la fila muestra la hora de llegada</td><td>Tras la llegada, desde el destino</td></tr>\n<tr><td><span class=\"pill fv-res\">Reservada</span></td><td>Tiene una reserva en las próximas 24 h (la hora aparece en la insignia)</td><td>Fuera del horario reservado</td></tr>\n<tr><td><span class=\"pill warn\">Con restricción</span></td><td>Ítem diferido (MEL); vuela siguiendo el procedimiento</td><td>Sí, simulando la restricción</td></tr>\n<tr><td><span class=\"pill bad\">AOG</span></td><td>En tierra por mantenimiento; la fila muestra cuándo vuelve</td><td>Solo tras la liberación</td></tr>\n<tr><td><span class=\"pill fv-new\">Sin historial</span></td><td>Nunca volada en VFR; el primer vuelo elige el origen</td><td>Sí</td></tr></tbody></table></div>\n<p>Toca una fila para abrir el <b>libro técnico</b>: foto, resumen (dónde está, cuándo queda disponible, próxima reserva y último piloto), ítems abiertos y procedimientos, mantenimientos programados, libreas para simulador, horas de célula, ciclos y todas las páginas de vuelo. Los freelancers ven solo la flota freelancer; los pilotos de aerolínea, solo la flota de las aerolíneas.</p></section>\n\n<section id=\"m-manut\"><h3>Mantenimiento automático</h3>\n<ul><li>Cuando termina el tiempo de reparación, la aeronave vuelve sola a <b>Disponible</b>.</li><li>El tiempo corre en horas reales desde el reporte; los períodos en tierra superpuestos se suman.</li><li>Un ítem MEL vencido deja la aeronave en tierra durante el tiempo de reparación de ese ítem.</li><li>Las reservas dentro de un nuevo período en tierra se cancelan, con un aviso arriba en la app; las posteriores se mantienen. Al piloto afectado se le ofrecen aeronaves del <b>mismo modelo o familia</b> (p. ej. familia A320, 737 NG/MAX, E-Jets) libres en el mismo horario; un toque abre una reserva ya completada con la misma ruta, hora y duración.</li></ul></section>\n\n<section id=\"m-oper\"><h3>Operación realista</h3>\n<p><b>Ubicación de la aeronave en la app.</b> El historial de vuelos y las reservas del sistema son independientes de las observaciones ADS-B. Consulta los avisos del vuelo y el libro técnico; los datos ADS-B no reposicionan la aeronave ni exigen un traslado.</p>\n\n<p><b>Desvíos.</b> La llegada real debe reflejar el vuelo realizado y los datos de rastreo/reporte. Revisa los avisos de las reservas afectadas; no confundas un desvío simulado con una observación ADS-B.</p>\n<p><b>Inspecciones programadas.</b> Cada 120 horas de vuelo o 100 ciclos la aeronave pasa por un check A (8 horas en tierra); cada 1.200 horas, por un check C (48 horas). La inspección se crea sola al cerrar el vuelo que alcanza el límite, y las reservas de ese período se cancelan con oferta de otra aeronave. El libro técnico muestra cuánto falta.</p>\n<p><b>SimBrief.</b> En <b>Perfil</b> (junto a tu nombre), indica tu usuario o Pilot ID de SimBrief. Así, \"Importar de SimBrief\" en la reserva trae aeronave, ruta, hora, duración y número de vuelo de tu último plan. En el reporte, el tiempo de calzos se completa solo cuando el rastreo está verificado.</p>\n\n\n\n<p><b>Eventos.</b> La pestaña Eventos lista los vuelos en grupo publicados por el administrador. Toca \"Reservar una aeronave para este evento\": primero aparecen las aeronaves que estarán en el aeropuerto de salida.</p>\n<p><b>Notificaciones.</b> La campana de arriba avisa cuando se acerca tu reserva, cuando la aeronave reservada recibió un nuevo reporte, cuando una reserva fue cancelada por mantenimiento, cuando falta cerrar un vuelo, además de eventos e insignias. En \"Notificaciones en este dispositivo\" puedes activar las notificaciones del sistema, mostradas con la app abierta o en segundo plano.</p>\n<p><b>Carrera.</b> El Diario de a bordo muestra tu rango (de Cadete a Comandante Máster, por horas de vuelo) y tus insignias. Los rangos son solo reconocimiento: cualquier piloto puede volar cualquier aeronave.</p></section>\n\n<section id=\"m-mapa\"><h3>Mapa y detalles del vuelo</h3>\n<p>El mapa prioriza <b>tu vuelo activo</b>. Si no hay ninguno, usa el último despacho de SimBrief disponible cuando tu usuario/Pilot ID está en el Perfil. Esto no cambia una escala aceptada. Un despacho distinto no reemplaza un vuelo activo. Sin datos detallados del navlog, la línea directa de salida a destino es una referencia, no una ruta de navegación validada.</p>\n<p>La barra lateral contiene <b>solo vuelos rastreados</b>, no estadísticas ni exploración de aeropuertos ni salidas RPL. El control de capas arriba a la derecha ofrece mapas base, tráfico, controladores y superposiciones. Las cartas DECEA de Brasil tienen controles de tipo/hoja y opacidad; consulta la edición oficial.</p>\n<p><b>Pasa el ratón y haz clic en una aeronave</b> (tócala en el móvil) para abrir sus detalles. El encabezado destaca el indicativo y el icono de la aerolínea cuando se puede identificar; los colores de la matrícula siguen a la aerolínea identificada. Altitud, velocidad sobre el suelo (GS), rumbo (HDG), posición, fuente y demás datos disponibles se agrupan para facilitar la lectura. Las ventanas largas tienen desplazamiento; no se inventan datos que faltan.</p>\n<p>Los datos de <b>FlyVFR rastreado</b> vienen del simulador, los de <b>IVAO/VATSIM</b> de sus redes y los de <b>ADS-B</b> de observaciones de aviones reales. Las estimaciones por horario de reserva se marcan como estimaciones, no telemetría. ADS-B es solo referencia y no cambia la disponibilidad, la elección de la aeronave ni la escala.</p></section>\n<section id=\"m-brief\"><h3>Sala de briefing, ADC y NOTAMs</h3>\n<p>Elige un vuelo reservado de la escala para ver METAR/TAF, NOTAMs y la meteorología de la ruta. Indica la <b>alternativa</b> y su <b>ETA</b> cuando haga falta. Sin ETA específica de la alternativa, se usa la ETA del destino y se indica. La alternativa y su ETA se guardan en el dispositivo por piloto/vuelo, sin cambiar la reserva.</p>\n<p>En la ADC solo se evalúan <b>salida, destino y alternativa</b> del vuelo elegido. La salida usa la EOBT; destino y alternativa usan sus ETAs. Si un aeródromo cumple más de un papel, se consideran los horarios correspondientes. Los NOTAMs vencidos, futuros, cancelados o sustituidos no se destacan como activos; los horarios no interpretados requieren confirmación.</p>\n<p><b>La capa ADC solo se habilita con un NOTAM activo confirmado para la hora del vuelo y datos recientes.</b> De lo contrario, la carta se retira del mapa y de las capas. Esto no declara el aeródromo libre de restricciones. No hay un botón “Ver carta” aparte: usa el selector de aeródromo y las capas del mapa.</p>\n<ul><li><b>Cierre total de pista:</b> solo se destaca con texto explícito, el par completo de cabeceras y geometría verificada.</li><li><b>Coordenadas en el texto:</b> aparecen como puntos, incluso fuera de la imagen de la ADC. Un perímetro explícito, válido y sin ambigüedades puede mostrarse como área discontinua; las listas de obstáculos no se unen automáticamente.</li><li><b>Referencias verificadas:</b> los marcadores de calle de rodaje o equipo indican una referencia de la carta, no necesariamente la posición exacta. Una barra de parada no disponible no significa calle de rodaje cerrada.</li><li><b>Avisos generales:</b> los avisos activos sin posición precisa se agrupan en un marcador de referencia del aeródromo identificado como tal; no representa el área afectada.</li><li><b>Línea Q:</b> centro y radio son referencia, no la ubicación exacta de una pista, calle de rodaje o equipo, ni un perímetro de restricción presunto.</li></ul>\n<p>La ADC georreferenciada depende de una carta oficial validada. Las cartas que faltan se indican; los avisos siguen disponibles sin inventar alineación. Los catálogos de cartas son referencias estáticas de esta versión, sin actualización automática. Consulta siempre los originales oficiales. <b>Solo para simulación.</b></p><p><b>Submenú de la Sala de briefing:</b> Vuelo, Aeronave, Vuelo rastreado, Mapa, Meteorología, NOTAMs, Redes en línea, Cartas, Plan de vuelo y Lista del briefing, cada uno con su icono en la barra lateral del briefing.</p>\n<ul><li><b>Aeronave:</b> matrícula y modelo, <b>libreas para simulador</b> (enlaces de descarga en flightsim.to o x-plane.org, filtrados por los simuladores de tu Perfil) y el libro técnico.</li>\n<li><b>Vuelo rastreado:</b> “Cómo conectar tu simulador” se abre en la misma página, debajo de los datos del vuelo.</li>\n<li><b>Cartas:</b> en “Preseleccionadas para el vuelo”, cada carta conserva el color de su tipo (ADC azul, SID verde, STAR violeta, IAC magenta…), igual que en “Otras cartas disponibles”. Marca las que quieras y usa <b>Descargar en un PDF</b>.</li></ul></section>\n<section id=\"m-redes\"><h3>IVAO y VATSIM</h3>\n<ol><li>Abre el <b>Perfil</b> e indica, si quieres, tu <b>CID de VATSIM</b>, tu <b>VID de IVAO</b> y la red preferida. Guarda tus preferencias.</li><li>El panel <b>Redes en línea</b> del briefing muestra los indicativos, frecuencias y ATIS disponibles de salida, destino y alternativa. Despliega una estación para leer su texto, filtra por red o actualiza.</li><li>Las capas del mapa muestran los controladores de cada red y los <b>ID declarados que coinciden</b>. Las estaciones en un mismo punto se agrupan; haz clic para leerlas. La coincidencia de ID destaca el indicativo observado.</li></ol>\n<p>La preferencia define la selección inicial; las capas del mapa se pueden cambiar por separado. Las horas UTC de las fuentes describen el <b>estado actual</b>, no la disponibilidad futura de ATC. Fuentes ausentes o desactualizadas no se confirman, y la falta de coincidencia de ID no prueba una desconexión. No se deducen coberturas extendidas de APP/Centro ni límites de sector a partir de indicativos o marcadores.</p>\n<p><b>Los ID son autodeclarados, no identidades verificadas.</b> Estos campos no inician sesión en las redes: usa el cliente de red del simulador. La detección en red no valida reportes, no concede horas ni sustituye el rastreo exigido por la app.</p></section>\n\n<section id=\"m-diario\"><h3>Diario de a bordo, salario y catálogo</h3>\n<p><b>Diario de a bordo → Mi diario</b> muestra tus horas: total, últimos 30 días, este año, horas por tipo de aeronave, aerolínea y simulador, matrículas más voladas (con los colores de la aerolínea y el modelo al lado) y la lista de vuelos, con <b>Exportar CSV</b> para hojas de cálculo. Las horas vienen del tiempo de calzos de cada reporte. <b>Salario</b> es una nómina ficticia: por hora de vuelo según rango y categoría de aeronave, más viáticos de pernocte. Los valores se fijan en dólares y se convierten a la moneda elegida al <b>tipo de cambio de la fecha de cada vuelo</b> (columna Cambio). El <b>Ranking de pilotos</b> compara el grupo (todo el período, este año o 30 días) y tiene dos pestañas: pilotos de aerolínea y freelancers; toca un piloto para ver su diario. <b>Todos los registros</b> lista cada vuelo reportado con una página secuencial por aeronave (TL 0001…), ruta, piloto, simulador, tiempo de calzos y fallas. El <b>Catálogo de fallas</b> reúne las 123 fallas estándar por capítulo ATA, con acción predeterminada, tiempo medio de reparación, plazo MEL y procedimiento.</p></section>\n\n<section id=\"m-apoie\"><h3>Apoya el proyecto</h3>\n<p>La app es gratuita. En la pestaña <b>Apoya</b> puedes donar por código QR de Pix, código Pix copia y pega u otras opciones indicadas (tarjeta, PayPal y más), cualquier importe.</p></section>\n\n<section id=\"m-faq\"><h3>Preguntas frecuentes</h3>\n<div class=\"scroll\"><table><thead><tr><th>Situación</th><th>Qué hacer</th></tr></thead><tbody>\n<tr><td>No consigo entrar</td><td>Revisa correo y contraseña. Si la olvidaste, toca <b>¿Olvidaste tu contraseña?</b> en la pantalla de entrada: recibirás un enlace por correo para crear una nueva</td></tr>\n<tr><td>Mi reserva fue rechazada</td><td>Lee el mensaje en rojo: superposición, mantenimiento, duración fuera de rango o límite semanal de esa matrícula</td></tr>\n<tr><td>No aparece la duración que quiero</td><td>Solo aparecen duraciones de vuelo + 45 min a vuelo + 2 h; revisa salida y llegada</td></tr>\n<tr><td>No aparece el botón Reportar vuelo</td><td>La aeronave tiene un ítem abierto: toca el botón amarillo <b>Revisar libro técnico</b> y firma</td></tr>\n<tr><td>Quiero cancelar mi escala</td><td>Una escala aceptada no se puede cancelar; los vuelos no realizados se liberan solos en la fecha 🔒</td></tr>\n<tr><td>Mi reserva desapareció</td><td>Puede haber sido cancelada por mantenimiento; mira el aviso arriba</td></tr>\n<tr><td>No aparece el METAR</td><td>Los aeropuertos pequeños pueden no emitir METAR o TAF; usa el enlace de aviationweather.gov</td></tr>\n<tr><td>Una novedad de la app no aparece</td><td>En el PC pulsa <b>Ctrl+Shift+R</b>; en el móvil cierra y vuelve a abrir la app</td></tr>\n<tr><td>Estoy sin conexión</td><td>La app abre con los últimos datos, solo lectura; reservas y reportes necesitan conexión</td></tr><tr><td>Quiero pasar de piloto de aerolínea a freelancer (o al revés)</td><td>Usa <b>Cambiar perfil</b> en la Escala/Vuelo libre: una vez cada 30 días y sin vuelos reservados</td></tr>\n<tr><td>Soy freelancer y la flota está vacía</td><td>Registra la aeronave que vuelas en <b>Añadir aeronave</b> (con la matrícula real) o vuela una ya registrada por otro freelancer</td></tr></tbody></table></div></section>\n"};
MANUAL.fr={fvUpdated:true,toc:[["m-ciclo","Fonctionnement"],["m-inicio","Premiers pas"],["m-perfil","Profil du pilote"],["m-escala","Rotation"],["m-livre","Vol libre (freelance)"],["m-reservar","Programme"],["m-antes","Avant le vol"],["m-rastreio","Vol suivi"],["m-reporte","Après l’atterrissage"],["m-frota","Flotte"],["m-manut","Maintenance automatique"],["m-oper","Exploitation réaliste"],["m-mapa","Carte et détails du vol"],["m-brief","Briefing, ADC et NOTAM"],["m-redes","IVAO et VATSIM"],["m-diario","Carnet, salaire et catalogue"],["m-apoie","Soutenir"],["m-faq","Questions fréquentes"]],body:"\n<p class=\"muted manual-updated\">Mis à jour le 30 octobre 2026.</p>\n<section id=\"m-ciclo\"><h3>Comment fonctionne Virtual Flight Report</h3>\n<p><b>Chaque vol laisse sa trace.</b> Virtual Flight Report est un carnet technique partagé : chaque avion est identifié par son immatriculation, et chaque pilote qui le fait voler, dans MSFS ou X-Plane, consigne ce qui lui est arrivé. Le pilote suivant retrouve l’avion exactement tel que le précédent l’a laissé.</p>\n<div class=\"cycle\"><span class=\"cy-step\">Générer la rotation</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">Consulter le carnet technique</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">Voler dans le simulateur</span><span class=\"cy-arrow\">→</span><span class=\"cy-step strong\">Déclarer le vol</span></div>\n<div class=\"cycle out\"><span class=\"chip ok\">Panne corrigée : reste disponible</span><span class=\"chip warn\">Différée (MEL) : vole avec restriction</span><span class=\"chip bad\">Au sol : libéré après réparation</span></div>\n<p class=\"muted\">Chaque panne porte sa propre conséquence : selon la panne choisie, l’application décide seule si l’avion reste disponible, vole avec restriction ou reste au sol, et pour combien de temps.</p></section>\n\n<section id=\"m-inicio\"><h3>Premiers pas</h3>\n<p>Il vous faut un compte pilote, créé une seule fois ; il fonctionne sur tous vos appareils.</p>\n<ol><li>Ouvrez <b>flyvfr.com.br</b> et touchez <b>Se connecter</b>.</li><li>Touchez <b>Nouveau pilote ? Créer un compte</b>.</li><li>Indiquez votre <b>nom de pilote</b> (nom ou indicatif visible par les autres), votre <b>e-mail</b>, les <b>simulateurs que vous utilisez</b> et un <b>mot de passe</b> d’au moins 6 caractères. Pour changer de simulateurs plus tard, touchez <b>Profil</b>, à côté de votre nom.</li><li>Touchez <b>Créer le compte</b>. Les fois suivantes, utilisez <b>Se connecter</b>.</li></ol>\n<p>À la connexion, l’application s’ouvre sur <b>Programme</b> si vous avez déjà une rotation acceptée ; sinon, sur <b>Rotation</b>. Le menu suit la journée du pilote : Rotation, Salle de briefing (activée avec une rotation acceptée), Réservations, Flotte, Carte, Événements, Carnet de vol, Catalogue, Manuel et Soutenir.</p>\n<div class=\"scroll\"><table><thead><tr><th>Appareil</th><th>Installation</th></tr></thead><tbody>\n<tr><td>PC (Chrome ou Edge)</td><td><b>Installer l’app</b> en haut de la page, ou l’icône d’installation de la barre d’adresse</td></tr>\n<tr><td>Android</td><td>Dans Chrome : menu ⋮ → <b>Installer l’app</b> (ou le fichier <b>VirtualFlightReport.apk</b>, si l’administrateur le partage)</td></tr>\n<tr><td>iPhone ou iPad (Safari)</td><td><b>Partager</b> → <b>Sur l’écran d’accueil</b></td></tr></tbody></table></div>\n<p>Dans <b>Réglages</b> (dans le menu), choisissez la langue par son drapeau (anglais, portugais, espagnol, français, allemand, japonais, chinois ou coréen), le thème de couleurs et la position du menu. Le bouton <b>DAY MODE / NIGHT MODE</b> bascule entre page claire et sombre. Vos choix sont enregistrés sur l’appareil. Les améliorations de l’application arrivent seules sur le PC et le téléphone, sans réinstallation. Pour vous déconnecter, touchez <b>Se déconnecter</b>, à côté de votre nom.</p><p><b>Profil du pilote.</b> À l’inscription, vous choisissez comment voler : <b>Pilote de ligne</b> ou <b>Freelance</b>. Les pilotes déjà inscrits choisissent à leur prochaine connexion. Voir <a href=\"#m-perfil\" data-action=\"man-jump\" data-to=\"m-perfil\">Profil du pilote</a>.</p></section>\n<section id=\"m-perfil\"><h3>Profil du pilote : compagnie ou freelance</h3>\n<div class=\"scroll\"><table><thead><tr><th></th><th>✈ Pilote de ligne</th><th>🛩 Freelance</th></tr></thead><tbody>\n<tr><td>Flotte pilotée</td><td>Uniquement les flottes des compagnies</td><td>Uniquement la flotte freelance : l’avion qu’il a enregistré et ceux enregistrés par d’autres freelances</td></tr>\n<tr><td>Réservation</td><td><b>Rotation</b> : vols RPL ou rotation libre, générés par l’application</td><td><b>Vol libre</b> : une étape ou une suite d’étapes construite par le pilote</td></tr>\n<tr><td>Compagnie</td><td>N’importe quelle compagnie, mais seulement après avoir terminé la dernière rotation</td><td>—</td></tr>\n<tr><td>Classement</td><td>Onglet <b>Pilotes de ligne</b></td><td>Onglet <b>Freelances</b></td></tr></tbody></table></div>\n<ul><li><b>Changer de profil :</b> touchez <b>Changer de profil</b> en haut de la Rotation (ou du Vol libre). Possible <b>une fois tous les 30 jours</b> et uniquement <b>sans vol réservé</b> en cours. L’écran indique la date du prochain changement possible.</li>\n<li><b>Flotte freelance partagée :</b> en enregistrant un avion, le freelance confirme que d’autres freelances pourront le piloter et qu’il peut piloter les leurs. La position et le carnet technique sont communs : le vol suivant part de là où le dernier a atterri.</li>\n<li><b>Immatriculation unique :</b> une immatriculation déjà présente dans la flotte ne peut pas être ajoutée.</li>\n<li>Le classement du Carnet de vol a deux onglets ; chaque vol compte dans l’onglet de la flotte de l’avion utilisé.</li></ul></section>\n\n<section id=\"m-escala\"><h3>Rotation de vols</h3>\n<p>Le menu <b>Rotation</b> propose deux modes :</p>\n<ul><li><b>Vol libre :</b> choisissez l’aérodrome de départ, la compagnie et l’avion, sans dépendre d’un départ RPL.</li><li><b>Vols RPL :</b> consultez les départs entre <b>30 et 90 minutes à partir de maintenant</b>. Le RPL couvre les vols intérieurs au Brésil et les vols internationaux au départ ou à destination du Brésil. Après avoir choisi un vol, sélectionnez un avion éligible de la compagnie et d’un modèle compatible avec le RPL.</li><li><b>Aucune option RPL éligible :</b> s’il n’y a pas de vol avec un avion éligible, ou pas de RPL pour l’aérodrome, le choix de la compagnie et de l’avion reste libre.</li><li><b>Favoris :</b> les avions favoris sont prioritaires dans le choix de la compagnie et de l’avion, dans les deux modes.</li></ul>\n<p>Définissez le premier départ, la durée de 1 à 4 jours et le nombre de vols par jour. Chaque étape commence là où la précédente se termine. Le générateur tient compte des temps au sol, de service et de repos ; vérifiez la séquence avant d’accepter.</p>\n<p>Vous pouvez générer de nouvelles options avant d’accepter. En touchant <b>Accepter la rotation</b>, confirmez les vols : <b>une rotation acceptée ne peut pas être modifiée</b>. L’acceptation active le briefing et les boutons SimBrief et SkyVector de chaque vol.</p>\n<p><b>L’ADS-B est uniquement informatif.</b> Les informations sur les avions au sol indiquent leur source et leur mise à jour. Elles ne modifient ni la disponibilité, ni le choix de l’avion, ni sa position opérationnelle dans l’application, ni la rotation ; la présence d’un avion réel ne détermine pas le vol généré.</p>\n<p>Consultez les cartes et avis de chaque vol dans <b>Programme</b>. Les vols terminés ou annulés ne rouvrent pas le tableau opérationnel de la rotation.</p><p><b>Retard (DLA) et non-présentation :</b> l’EOBT (heure estimée de départ du poste) figure sur la carte du vol dans Votre programme. Si vous allez être en retard, touchez <b>Retard (DLA)</b> et choisissez la nouvelle EOBT : <b>un DLA par vol</b>, déposé jusqu’à <b>35 min après l’EOBT prévue</b>, avec une nouvelle EOBT à <b>45 min au plus du moment où le DLA est déposé</b>. Les vols suivants du même service sont décalés d’autant. La propagation s’arrête à la nuit de repos, en préservant les horaires du service suivant. Si le vol suivi n’est pas démarré dans les <b>45 min suivant l’EOBT en vigueur</b>, le vol est annulé et un avis apparaît dans Réservations. Une fois l’EOBT passée, la carte affiche l’heure limite en rouge.</p></section>\n<section id=\"m-livre\"><h3>Vol libre (freelance)</h3>\n<p>Pour le freelance, le menu <b>Rotation</b> devient <b>Vol libre</b>. Il n’y a pas de génération de rotation : vous construisez les vols.</p>\n<ol><li>Choisissez un <b>avion</b> de la flotte freelance (la liste indique « le mien » ou qui l’a enregistré, et où il se trouve).</li>\n<li>L’<b>origine de la première étape</b> est l’endroit où sera l’avion ; s’il n’a jamais volé, vous choisissez l’origine.</li>\n<li>Indiquez la <b>destination</b> et l’<b>heure de départ</b> (au moins 30 min à partir de maintenant). L’application calcule la distance, le temps bloc et l’arrivée, et vérifie le rayon d’action de l’avion.</li>\n<li>Pour poursuivre le voyage, touchez <b>＋ Ajouter une étape</b> : la suivante part de là où la précédente atterrit, avec un départ suggéré 1 h après l’arrivée (minimum 45 min entre l’arrivée et le départ suivant). Supprimez une étape avec ✕. Jusqu’à 24 étapes.</li>\n<li>Les numéros de vol sont proposés à la suite et peuvent être modifiés. Touchez <b>Réserver le vol libre</b> (ou <b>Réserver N vols libres</b>).</li></ol>\n<p>Après la réservation, tout se passe comme pour une rotation : Programme, Salle de briefing, vol suivi et déclaration après l’atterrissage.</p></section>\n\n<section id=\"m-reservar\"><h3>Programme des vols</h3>\n<p>L’onglet <b>Programme</b> commence par <b>Votre programme</b> : une carte par vol, avec la photo de l’avion, l’immatriculation aux couleurs de la compagnie, numéro de vol et route, date et heure (locale et UTC) et la compagnie.</p>\n<div class=\"scroll\"><table><thead><tr><th>Sur la carte</th><th>Signification</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">✓ Aucun élément ouvert dans le carnet</span></td><td>Clignote une fois pour prévenir. Rien à signer : <b>Vol suivi</b> et <b>Déclarer le vol</b> sont déjà disponibles</td></tr>\n<tr><td><span class=\"chip warn\">⚠ Consulter le carnet technique</span></td><td>Continue de clignoter : l’avion a un élément ouvert. Touchez-le, lisez les éléments et signez (voir <b>Avant le vol</b>)</td></tr>\n<tr><td><span class=\"chip ok\">✓ Carnet technique consulté</span></td><td>Vous avez signé ; vous pouvez voler</td></tr></tbody></table></div>\n<ul><li><b>SimBrief</b> et <b>SkyVector</b> : les boutons avec l’icône de chaque site, à droite, ouvrent la préparation du vol correspondant. SimBrief reçoit aussi l’identification de l’avion et l’EOBT ; SkyVector reçoit la route et les estimations de croisière.</li><li><b>METAR et TAF :</b> survolez le code d’un aéroport (touchez-le sur téléphone). Touchez <b>Décodé</b> pour lire le message en clair (vent, visibilité, nuages, température, pression et chaque période du TAF) ; <b>Original</b> réaffiche le texte brut. L’application retient votre choix.</li></ul>\n<p>Les réservations de la rotation sont créées à l’acceptation. Utilisez les cartes de vol pour consulter le carnet technique, suivre et déclarer le vol. Les actions d’administration et d’événement dépendent des options disponibles pour le compte.</p></section>\n\n<section id=\"m-antes\"><h3>Avant le vol</h3>\n<p>Avant de voler, vérifiez le bouton du carnet technique sur la carte du vol :</p>\n<ul><li><b>Aucun élément ouvert</b> (vert) : pas de signature. Touchez simplement <b>Vol suivi</b> ou <b>Déclarer le vol</b>.</li><li><b>Élément ouvert</b> (jaune clignotant) : touchez <b>Consulter le carnet technique</b>, lisez les éléments ouverts et les derniers rapports, cochez la confirmation et touchez <b>Signer le carnet technique</b>. Le bouton passe au vert et affiche <b>Carnet technique consulté</b>. Sans cette signature, le suivi et la déclaration ne sont pas acceptés.</li><li>Si un autre pilote déclare une panne sur cette immatriculation après votre signature, le bouton jaune revient et vous devez signer à nouveau.</li></ul>\n<p>Une panne ne passe pas d’un simulateur à l’autre ; chaque élément différé est donc accompagné d’une <b>procédure pour l’équipage suivant</b>, à appliquer pendant votre vol. Exemple : <i>l’APU ne démarre pas</i> → demander un GPU et de l’air extérieur au sol.</p></section>\n\n<section id=\"m-rastreio\"><h3>Vol suivi</h3>\n<p>Le <b>suivi validé</b> est la manière normale d’enregistrer un vol et de compter heures, grade, salaire et classement. L’application lit la télémétrie du simulateur et le serveur vérifie la trajectoire. Sans suivi validé, demandez une revue lorsqu’elle est disponible : un administrateur décide, sans clôture du vol ni récompense avant approbation.</p>\n<ol><li>Sur la carte du vol dans <b>Votre programme</b>, touchez <b>✈ Vol suivi</b> (disponible 1 h avant l’heure réservée ; s’il y a un élément ouvert, signez d’abord le carnet technique).</li>\n<li>Avion arrêté à la porte de départ, touchez <b>Se connecter au simulateur</b>.<ul>\n<li><b>MSFS 2020/2024 :</b> installez <a href=\"https://fsuipc.com\" target=\"_blank\" rel=\"noopener\">FSUIPC7</a> (la version gratuite suffit) et le <a href=\"http://fsuipcwebsockets.paulhenty.com/\" target=\"_blank\" rel=\"noopener\">FSUIPC WebSocket Server</a>, et gardez-les ouverts avec le simulateur.</li>\n\n<li><b>X-Plane 12</b> (12.1.4 ou plus récent) : rien à installer.</li>\n<li><b>X-Plane 11 :</b> plugin XPUIPC + FSUIPC WebSocket Server.</li>\n<li>Utilisez Chrome ou Edge sur le même ordinateur que le simulateur. Si le navigateur demande l’accès au réseau local, autorisez-le.</li></ul></li>\n<li>Volez normalement et laissez l’onglet ouvert. L’écran <b>Vol en direct</b> affiche phase, altitude, vitesse, vitesse verticale et distance à destination ; vous pouvez utiliser d’autres écrans entre-temps.</li>\n<li>Après l’atterrissage, garez et arrêtez l’avion. Touchez <b>Terminer le vol</b> : le serveur vérifie la trajectoire et affiche le résultat. Remplissez ensuite la déclaration (pannes et remarques) ; le temps bloc et l’aéroport d’arrivée viennent du suivi.</li></ol>\n<p>Le serveur rejette le vol s’il ne commence pas au sol à l’aéroport de départ · ne se termine pas arrêté sur un aéroport · utilise l’accélération du temps ou le slew · l’avion saute de position (téléportation ou déplacement sur la carte) · le suivi s’interrompt plus de 10 min en vol · la trajectoire n’arrive pas au serveur en temps réel · le vol dure moins de 5 min en l’air. La pause est autorisée : le temps en pause est retiré. Les déroutements sont acceptés : l’avion reste là où il a atterri.</p></section>\n\n<section id=\"m-reporte\"><h3>Après l’atterrissage : déclarer le vol</h3>\n<ol><li>Touchez <b>Déclarer le vol</b>.</li><li>Choisissez le <b>simulateur</b> (seuls les vôtres apparaissent ; pour un autre, choisissez <b>Autre simulateur…</b>) et indiquez le <b>temps bloc</b> (h:mm, ex. <code>1:45</code>).</li><li>Pour chaque panne, touchez <b>Ajouter une panne</b> ; s’il ne s’est rien passé, n’en ajoutez aucune.</li><li>Touchez <b>Envoyer la déclaration et clore la réservation</b>.</li></ol>\n<p>Le champ de panne affiche les <b>plus déclarées par les équipages de ligne</b>. Commencez à taper et la liste se réduit : elle comprend plusieurs langues, ignore les accents et connaît des termes comme <code>brake</code>, <code>door</code>, <code>APU</code>, <code>ata 32</code> ou <code>ECAM</code>. Si la panne n’est pas au catalogue, choisissez <b>Absente de la liste : la décrire</b>.</p>\n<p>Le pilote ne choisit ni l’action ni la durée : elles découlent de la panne choisie dans le catalogue. Pour une panne hors catalogue, l’application applique le défaut le plus courant du chapitre ATA indiqué.</p><div class=\"scroll\"><table><thead><tr><th>Conséquence</th><th>Effet sur l’avion</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">Corrigée par l’équipage</span></td><td>Aucun ; reste seulement dans l’historique</td></tr>\n<tr><td><span class=\"chip warn\">Différée (MEL)</span></td><td>Vole avec restriction jusqu’à l’échéance (Cat B 3 jours, Cat C 10 jours, Cat D 120 jours) ; ensuite au sol le temps de la réparation</td></tr>\n<tr><td><span class=\"chip bad\">Avion au sol</span></td><td>Indisponible pendant la durée moyenne de réparation, comptée à partir de la déclaration</td></tr></tbody></table></div></section>\n\n<section id=\"m-frota\"><h3>Flotte</h3>\n<p>L’onglet <b>Flotte</b> affiche la situation de chaque immatriculation. En haut, les <b>totaux suivent les filtres</b> : avions de la sélection, disponibles maintenant, en vol maintenant, réservés dans les prochaines 24 h et avec restriction ou au sol.</p>\n<ul><li><b>Filtres sur une ligne :</b> région, compagnie, type, statut et <b>Trier</b> (volés récemment, les plus volés, disponibles d’abord ou immatriculation), plus la recherche par immatriculation, type ou aéroport (ex. <code>SBGR</code>) et le bouton <b>Favoris</b>.</li>\n<li><b>Groupée par modèle :</b> chaque groupe indique combien d’avions il compte et combien sont disponibles.</li>\n<li><b>Une ligne par avion :</b> immatriculation, type, <b>où il est</b>, <b>dernier vol</b> (ex. « SBGR → SBSV · il y a 2 j ») ou prochain événement, <b>historique</b> (vols et heures sur VFR) et statut. Les avions disponibles n’ont qu’un point vert ; les badges colorés signalent les exceptions.</li>\n<li><b>Fenêtre étroite</b> (demi-écran) : la ligne se réorganise sur deux lignes pour que rien ne soit coupé. Sur téléphone, la flotte s’affiche en cartes.</li>\n<li><b>Plus d’avions :</b> touchez <b>Afficher plus</b> en bas de la liste. <b>Enregistrer :</b> <b>Ajouter un avion</b>.</li></ul>\n<div class=\"scroll\"><table><thead><tr><th>Statut</th><th>Signification</th><th>Peut-il voler ?</th></tr></thead><tbody>\n<tr><td><span class=\"fv-ok\">Disponible</span></td><td>Aucun élément ouvert et pas d’utilisation dans les prochaines 24 h</td><td>Oui</td></tr>\n<tr><td><span class=\"pill fv-fly\">En vol</span></td><td>Un pilote a l’avion en ce moment ; la ligne indique l’heure d’arrivée</td><td>Après l’arrivée, depuis la destination</td></tr>\n<tr><td><span class=\"pill fv-res\">Réservé</span></td><td>Réservation dans les prochaines 24 h (heure indiquée sur le badge)</td><td>En dehors de l’horaire réservé</td></tr>\n<tr><td><span class=\"pill warn\">Avec restriction</span></td><td>Élément différé (MEL) ; vole en suivant la procédure</td><td>Oui, en simulant la restriction</td></tr>\n<tr><td><span class=\"pill bad\">AOG</span></td><td>Au sol pour maintenance ; la ligne indique le retour</td><td>Seulement après la remise en service</td></tr>\n<tr><td><span class=\"pill fv-new\">Sans historique</span></td><td>Jamais volé sur VFR ; le premier vol choisit l’origine</td><td>Oui</td></tr></tbody></table></div>\n<p>Touchez une ligne pour ouvrir le <b>carnet technique</b> : photo, résumé (où il est, quand il est disponible, prochaine réservation et dernier pilote), éléments ouverts et procédures, maintenances programmées, livrées pour simulateur, heures cellule, cycles et toutes les pages de vol. Les freelances ne voient que la flotte freelance ; les pilotes de ligne, que les flottes des compagnies.</p></section>\n\n<section id=\"m-manut\"><h3>Maintenance automatique</h3>\n<ul><li>À la fin du temps de réparation, l’avion redevient <b>Disponible</b> tout seul.</li><li>Le temps court en heures réelles à partir de la déclaration ; les immobilisations qui se chevauchent s’additionnent.</li><li>Un élément MEL échu immobilise l’avion pendant le temps de réparation de cet élément.</li><li>Les réservations comprises dans une nouvelle immobilisation sont annulées, avec un avis en haut de l’application ; les suivantes sont conservées. Le pilote concerné se voit proposer des avions du <b>même modèle ou de la même famille</b> (ex. famille A320, 737 NG/MAX, E-Jets) libres au même moment ; un toucher ouvre une réservation préremplie avec la même route, la même heure et la même durée.</li></ul></section>\n\n<section id=\"m-oper\"><h3>Exploitation réaliste</h3>\n<p><b>Position de l’avion dans l’application.</b> L’historique des vols et les réservations du système sont indépendants des observations ADS-B. Consultez les avis du vol et le carnet technique ; les données ADS-B ne repositionnent pas l’avion et n’exigent pas de convoyage.</p>\n\n<p><b>Déroutements.</b> L’arrivée réelle doit refléter le vol effectué et les données de suivi/déclaration. Consultez les avis des réservations concernées ; ne confondez pas un déroutement simulé avec une observation ADS-B.</p>\n<p><b>Visites programmées.</b> Toutes les 120 heures de vol ou 100 cycles, l’avion passe une visite A (8 heures au sol) ; toutes les 1 200 heures, une visite C (48 heures). La visite est créée automatiquement à la clôture du vol qui atteint la limite, et les réservations de cette période sont annulées avec proposition d’un autre avion. Le carnet technique indique ce qui reste.</p>\n<p><b>SimBrief.</b> Dans <b>Profil</b> (à côté de votre nom), indiquez votre identifiant ou Pilot ID SimBrief. « Importer depuis SimBrief » dans la réservation récupère alors avion, route, heure, durée et numéro de vol de votre dernier plan. Dans la déclaration, le temps bloc est rempli automatiquement lorsque le suivi est vérifié.</p>\n\n\n\n<p><b>Événements.</b> L’onglet Événements liste les vols de groupe publiés par l’administrateur. Touchez « Réserver un avion pour cet événement » : les avions qui seront à l’aéroport de départ apparaissent en premier.</p>\n<p><b>Notifications.</b> La cloche en haut vous prévient quand votre réservation approche, quand l’avion réservé a reçu une nouvelle déclaration, quand une réservation a été annulée pour maintenance, quand un vol reste à clore, ainsi que pour les événements et badges. Dans « Notifications sur cet appareil », vous pouvez activer les notifications système, affichées avec l’application ouverte ou en arrière-plan.</p>\n<p><b>Carrière.</b> Le Carnet de vol affiche votre grade (de Cadet à Commandant Master, selon les heures de vol) et vos badges. Les grades sont honorifiques : tout pilote peut piloter n’importe quel avion.</p></section>\n\n<section id=\"m-mapa\"><h3>Carte et détails du vol</h3>\n<p>La carte donne la priorité à <b>votre vol actif</b>. S’il n’y en a pas, elle utilise le dernier dispatch SimBrief disponible lorsque votre identifiant/Pilot ID est renseigné dans le Profil. Cela ne modifie pas une rotation acceptée. Un autre dispatch ne remplace pas un vol actif. Sans données détaillées de navlog, la ligne directe départ-destination est une référence, pas une route de navigation validée.</p>\n<p>La barre latérale ne contient que <b>les vols suivis</b>, sans statistiques ni exploration d’aéroports ni départs RPL. Le sélecteur de couches en haut à droite propose fonds de carte, trafic, contrôleurs et superpositions. Les cartes DECEA du Brésil ont des réglages de type/feuille et d’opacité ; consultez l’édition officielle.</p>\n<p><b>Survolez et cliquez sur un avion</b> (touchez-le sur mobile) pour ouvrir ses détails. L’en-tête met en évidence l’indicatif et l’icône de la compagnie lorsqu’elle est identifiée ; les couleurs de l’immatriculation suivent la compagnie reconnue. Altitude, vitesse sol (GS), cap (HDG), position, source et autres informations disponibles sont regroupées pour la lisibilité. Les fenêtres longues défilent ; les données manquantes ne sont pas inventées.</p>\n<p>Les données <b>FlyVFR suivies</b> viennent du simulateur, celles d’<b>IVAO/VATSIM</b> de leurs réseaux et l’<b>ADS-B</b> d’observations d’avions réels. Les estimations fondées sur l’horaire de réservation sont signalées comme estimations, pas comme télémétrie. L’ADS-B est uniquement informatif et ne modifie ni la disponibilité, ni le choix de l’avion, ni la rotation.</p></section>\n<section id=\"m-brief\"><h3>Salle de briefing, ADC et NOTAM</h3>\n<p>Choisissez un vol réservé de la rotation pour voir METAR/TAF, NOTAM et météo de route. Indiquez le <b>dégagement</b> et son <b>ETA</b> si nécessaire. Sans ETA spécifique du dégagement, l’ETA de destination est utilisée et signalée. Le dégagement et son ETA sont enregistrés sur l’appareil par pilote/vol, sans modifier la réservation.</p>\n<p>Sur l’ADC, seuls le <b>départ, la destination et le dégagement</b> du vol choisi sont évalués. Le départ utilise l’EOBT ; la destination et le dégagement, leurs ETA. Si un aérodrome joue plusieurs rôles, les horaires correspondants sont pris en compte. Les NOTAM expirés, futurs, annulés ou remplacés ne sont pas mis en avant comme actifs ; les horaires non interprétés demandent une vérification.</p>\n<p><b>La couche ADC n’est disponible qu’avec un NOTAM actif confirmé pour l’heure du vol et des données récentes.</b> Sinon, la carte est retirée de l’affichage et des couches. Cela ne signifie pas que l’aérodrome est sans restriction. Il n’y a pas de bouton « Voir la carte » séparé : utilisez le sélecteur d’aérodrome et les couches de la carte.</p>\n<ul><li><b>Fermeture totale de piste :</b> mise en évidence uniquement avec un texte explicite, la paire complète de seuils et une géométrie vérifiée.</li><li><b>Coordonnées dans le texte :</b> affichées en points, y compris hors de l’image ADC. Un périmètre explicite, valide et sans ambiguïté peut apparaître en zone pointillée ; les listes d’obstacles ne sont pas reliées automatiquement.</li><li><b>Références vérifiées :</b> les repères de voie de circulation ou d’équipement indiquent une référence de la carte, pas forcément la position exacte. Une barre d’arrêt indisponible ne signifie pas une voie de circulation fermée.</li><li><b>Avis généraux :</b> les avis actifs sans position précise sont regroupés sur un repère de référence de l’aérodrome clairement identifié, qui ne représente pas la zone concernée.</li><li><b>Ligne Q :</b> centre et rayon sont des références, pas l’emplacement exact d’une piste, d’une voie ou d’un équipement, ni un périmètre de restriction présumé.</li></ul>\n<p>L’ADC géoréférencée dépend d’une carte officielle validée. Les cartes manquantes sont signalées ; les avis restent disponibles sans alignement inventé. Les catalogues de cartes sont des références statiques de cette version, sans mise à jour automatique. Consultez toujours les originaux officiels. <b>Pour la simulation uniquement.</b></p><p><b>Sous-menu de la Salle de briefing :</b> Vol, Avion, Vol suivi, Carte, Météo, NOTAM, Réseaux en ligne, Cartes, Plan de vol et Checklist du briefing, chacun avec son icône dans la barre latérale du briefing.</p>\n<ul><li><b>Avion :</b> immatriculation et modèle, <b>livrées pour simulateur</b> (liens de téléchargement sur flightsim.to ou x-plane.org, filtrés selon les simulateurs de votre Profil) et le carnet technique.</li>\n<li><b>Vol suivi :</b> « Comment connecter votre simulateur » s’ouvre sur la même page, sous les données du vol.</li>\n<li><b>Cartes :</b> dans « Présélectionnées pour le vol », chaque carte garde la couleur de son type (ADC bleu, SID vert, STAR violet, IAC magenta…), comme dans « Autres cartes disponibles ». Cochez celles que vous voulez et utilisez <b>Télécharger un PDF unique</b>.</li></ul></section>\n<section id=\"m-redes\"><h3>IVAO et VATSIM</h3>\n<ol><li>Ouvrez le <b>Profil</b> et indiquez, si vous le souhaitez, votre <b>CID VATSIM</b>, votre <b>VID IVAO</b> et le réseau préféré. Enregistrez vos préférences.</li><li>Le panneau <b>Réseaux en ligne</b> du briefing affiche les indicatifs, fréquences et ATIS disponibles du départ, de la destination et du dégagement. Dépliez une station pour lire son texte, filtrez par réseau ou actualisez.</li><li>Les couches de la carte affichent les contrôleurs de chaque réseau et les <b>ID déclarés correspondants</b>. Les stations au même point sont regroupées ; cliquez pour les lire. La correspondance d’ID met en évidence l’indicatif observé.</li></ol>\n<p>La préférence définit la sélection initiale ; les couches de la carte se changent indépendamment. Les heures UTC des sources décrivent l’<b>état actuel</b>, pas la disponibilité future de l’ATC. Les sources absentes ou périmées ne sont pas confirmées, et l’absence de correspondance d’ID ne prouve pas une déconnexion. Aucune couverture APP/Centre étendue ni limite de secteur n’est déduite des indicatifs ou des repères.</p>\n<p><b>Les ID sont déclarés par le pilote, pas des identités vérifiées.</b> Ces champs ne vous connectent pas aux réseaux : utilisez le client réseau du simulateur. La détection réseau ne valide pas les déclarations, n’accorde pas d’heures et ne remplace pas le suivi exigé par l’application.</p></section>\n\n<section id=\"m-diario\"><h3>Carnet de vol, salaire et catalogue</h3>\n<p><b>Carnet de vol → Mon carnet</b> affiche vos heures : total, 30 derniers jours, cette année, heures par type d’avion, compagnie et simulateur, immatriculations les plus volées (aux couleurs de la compagnie, modèle à côté) et la liste des vols, avec <b>Exporter CSV</b> pour les tableurs. Les heures viennent du temps bloc de chaque déclaration. <b>Salaire</b> est une fiche de paie fictive : par heure de vol selon le grade et la catégorie d’avion, plus les indemnités de découcher. Les montants sont fixés en dollars et convertis dans la devise choisie au <b>taux de change de la date de chaque vol</b> (colonne Taux). Le <b>Classement des pilotes</b> compare le groupe (toute la période, cette année ou 30 jours) et a deux onglets : pilotes de ligne et freelances ; touchez un pilote pour voir son carnet. <b>Toutes les entrées</b> liste chaque vol déclaré avec une page séquentielle par avion (TL 0001…), route, pilote, simulateur, temps bloc et pannes. Le <b>Catalogue des pannes</b> réunit les 123 pannes standard par chapitre ATA, avec action par défaut, durée moyenne de réparation, délai MEL et procédure.</p></section>\n\n<section id=\"m-apoie\"><h3>Soutenir le projet</h3>\n<p>L’application est gratuite. Dans l’onglet <b>Soutenir</b>, vous pouvez faire un don par QR code Pix, code Pix copier-coller ou les autres options proposées (carte, PayPal et plus), du montant de votre choix.</p></section>\n\n<section id=\"m-faq\"><h3>Questions fréquentes</h3>\n<div class=\"scroll\"><table><thead><tr><th>Situation</th><th>Que faire</th></tr></thead><tbody>\n<tr><td>Je n’arrive pas à me connecter</td><td>Vérifiez l’e-mail et le mot de passe. En cas d’oubli, touchez <b>Mot de passe oublié ?</b> sur l’écran de connexion : vous recevrez un lien par e-mail pour en créer un nouveau</td></tr>\n<tr><td>Ma réservation a été refusée</td><td>Lisez le message en rouge : chevauchement, maintenance, durée hors limites ou limite hebdomadaire de cette immatriculation</td></tr>\n<tr><td>La durée voulue n’apparaît pas</td><td>Seules les durées de vol + 45 min à vol + 2 h apparaissent ; vérifiez départ et arrivée</td></tr>\n<tr><td>Pas de bouton Déclarer le vol</td><td>L’avion a un élément ouvert : touchez le bouton jaune <b>Consulter le carnet technique</b> et signez</td></tr>\n<tr><td>Je veux annuler ma rotation</td><td>Une rotation acceptée ne peut pas être annulée ; les vols non effectués sont libérés automatiquement à la date 🔒</td></tr>\n<tr><td>Ma réservation a disparu</td><td>Elle a peut-être été annulée pour maintenance ; voyez l’avis en haut</td></tr>\n<tr><td>Pas de METAR affiché</td><td>Les petits aéroports n’émettent pas toujours de METAR ou de TAF ; utilisez le lien aviationweather.gov</td></tr>\n<tr><td>Une nouveauté de l’application n’apparaît pas</td><td>Sur PC, appuyez sur <b>Ctrl+Maj+R</b> ; sur téléphone, fermez et rouvrez l’application</td></tr>\n<tr><td>Je suis hors ligne</td><td>L’application s’ouvre avec les dernières données, en lecture seule ; réservations et déclarations nécessitent une connexion</td></tr><tr><td>Je veux passer de pilote de ligne à freelance (ou l’inverse)</td><td>Utilisez <b>Changer de profil</b> dans Rotation/Vol libre : une fois tous les 30 jours et sans vol réservé</td></tr>\n<tr><td>Je suis freelance et la flotte est vide</td><td>Enregistrez l’avion que vous pilotez via <b>Ajouter un avion</b> (immatriculation réelle) ou pilotez-en un déjà enregistré par un autre freelance</td></tr></tbody></table></div></section>\n"};
MANUAL.de={fvUpdated:true,toc:[["m-ciclo","So funktioniert es"],["m-inicio","Erste Schritte"],["m-perfil","Pilotenprofil"],["m-escala","Umlauf"],["m-livre","Freier Flug (Freelancer)"],["m-reservar","Flugplan"],["m-antes","Vor dem Flug"],["m-rastreio","Verfolgter Flug"],["m-reporte","Nach der Landung"],["m-frota","Flotte"],["m-manut","Automatische Wartung"],["m-oper","Realistischer Betrieb"],["m-mapa","Karte und Flugdetails"],["m-brief","Briefing, ADC und NOTAMs"],["m-redes","IVAO und VATSIM"],["m-diario","Flugbuch, Gehalt und Katalog"],["m-apoie","Unterstützen"],["m-faq","Häufige Fragen"]],body:"\n<p class=\"muted manual-updated\">Aktualisiert am 30. Oktober 2026.</p>\n<section id=\"m-ciclo\"><h3>So funktioniert Virtual Flight Report</h3>\n<p><b>Jeder Flug hinterlässt seine Spuren.</b> Virtual Flight Report ist ein gemeinsames technisches Bordbuch: Jedes Flugzeug wird über sein Kennzeichen identifiziert, und jeder Pilot, der es in MSFS oder X-Plane fliegt, hält fest, was mit ihm passiert ist. Der nächste Pilot findet das Flugzeug genau so vor, wie der vorherige es verlassen hat.</p>\n<div class=\"cycle\"><span class=\"cy-step\">Umlauf erstellen</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">Technisches Bordbuch prüfen</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">Im Simulator fliegen</span><span class=\"cy-arrow\">→</span><span class=\"cy-step strong\">Flug melden</span></div>\n<div class=\"cycle out\"><span class=\"chip ok\">Behoben: bleibt verfügbar</span><span class=\"chip warn\">Zurückgestellt (MEL): fliegt mit Einschränkung</span><span class=\"chip bad\">Am Boden: nach Reparatur freigegeben</span></div>\n<p class=\"muted\">Jeder Defekt bringt seine eigene Folge mit: Anhand des gewählten Defekts entscheidet die App selbst, ob das Flugzeug verfügbar bleibt, mit Einschränkung fliegt oder am Boden bleibt, und wie lange.</p></section>\n\n<section id=\"m-inicio\"><h3>Erste Schritte</h3>\n<p>Sie brauchen ein Pilotenkonto, das einmal angelegt wird und auf allen Geräten gilt.</p>\n<ol><li>Öffnen Sie <b>flyvfr.com.br</b> und tippen Sie auf <b>Anmelden</b>.</li><li>Tippen Sie auf <b>Neuer Pilot? Konto erstellen</b>.</li><li>Geben Sie Ihren <b>Pilotennamen</b> (Name oder Rufzeichen, das andere sehen), Ihre <b>E-Mail</b>, die <b>Simulatoren, die Sie nutzen</b>, und ein <b>Passwort</b> mit mindestens 6 Zeichen ein. Um die Simulatoren später zu ändern, tippen Sie neben Ihrem Namen auf <b>Profil</b>.</li><li>Tippen Sie auf <b>Konto erstellen</b>. Beim nächsten Mal nutzen Sie <b>Anmelden</b>.</li></ol>\n<p>Nach der Anmeldung öffnet die App <b>Flugplan</b>, wenn Sie bereits einen angenommenen Umlauf haben, sonst <b>Umlauf</b>. Das Menü folgt dem Tagesablauf eines Piloten: Umlauf, Briefingraum (mit angenommenem Umlauf aktiv), Buchungen, Flotte, Karte, Events, Flugbuch, Katalog, Handbuch und Unterstützen.</p>\n<div class=\"scroll\"><table><thead><tr><th>Gerät</th><th>Installation</th></tr></thead><tbody>\n<tr><td>PC (Chrome oder Edge)</td><td><b>App installieren</b> oben auf der Seite oder das Installationssymbol in der Adressleiste</td></tr>\n<tr><td>Android</td><td>In Chrome: Menü ⋮ → <b>App installieren</b> (oder die Datei <b>VirtualFlightReport.apk</b>, falls der Administrator sie teilt)</td></tr>\n<tr><td>iPhone oder iPad (Safari)</td><td><b>Teilen</b> → <b>Zum Home-Bildschirm</b></td></tr></tbody></table></div>\n<p>Unter <b>Einstellungen</b> (im Menü) wählen Sie die Sprache über die Flagge (Englisch, Portugiesisch, Spanisch, Französisch, Deutsch, Japanisch, Chinesisch oder Koreanisch), das Farbschema und die Menüposition. Die Schaltfläche <b>DAY MODE / NIGHT MODE</b> wechselt zwischen heller und dunkler Seite. Ihre Auswahl wird auf dem Gerät gespeichert. Verbesserungen der App kommen automatisch auf PC und Handy, ohne Neuinstallation. Zum Abmelden tippen Sie neben Ihrem Namen auf <b>Abmelden</b>.</p><p><b>Pilotenprofil.</b> Bei der Registrierung wählen Sie, wie Sie fliegen: <b>Airline-Pilot</b> oder <b>Freelancer</b>. Bestehende Piloten wählen bei der nächsten Anmeldung. Siehe <a href=\"#m-perfil\" data-action=\"man-jump\" data-to=\"m-perfil\">Pilotenprofil</a>.</p></section>\n<section id=\"m-perfil\"><h3>Pilotenprofil: Airline oder Freelancer</h3>\n<div class=\"scroll\"><table><thead><tr><th></th><th>✈ Airline-Pilot</th><th>🛩 Freelancer</th></tr></thead><tbody>\n<tr><td>Geflogene Flotte</td><td>Nur die Airline-Flotten</td><td>Nur die Freelancer-Flotte: das selbst registrierte Flugzeug und die von anderen Freelancern registrierten</td></tr>\n<tr><td>Buchung</td><td><b>Umlauf</b>: RPL-Flüge oder freier Umlauf, von der App erstellt</td><td><b>Freier Flug</b>: eine Strecke oder eine Folge von Strecken, die der Pilot selbst zusammenstellt</td></tr>\n<tr><td>Airline</td><td>Jede Airline, aber erst nach Abschluss des letzten Umlaufs</td><td>—</td></tr>\n<tr><td>Ranking</td><td>Reiter <b>Airline-Piloten</b></td><td>Reiter <b>Freelancer</b></td></tr></tbody></table></div>\n<ul><li><b>Profil wechseln:</b> Tippen Sie oben im Umlauf (oder im Freien Flug) auf <b>Profil ändern</b>. Möglich <b>einmal alle 30 Tage</b> und nur <b>ohne offene gebuchte Flüge</b>. Der Bildschirm zeigt das Datum des nächsten möglichen Wechsels.</li>\n<li><b>Gemeinsame Freelancer-Flotte:</b> Beim Registrieren eines Flugzeugs bestätigt der Freelancer, dass andere Freelancer es fliegen dürfen und er deren Flugzeuge fliegen darf. Position und technisches Bordbuch sind für alle gleich: Der nächste Flug startet dort, wo der letzte gelandet ist.</li>\n<li><b>Eindeutiges Kennzeichen:</b> Ein Kennzeichen, das bereits in der Flotte existiert, kann nicht erneut registriert werden.</li>\n<li>Das Ranking im Flugbuch hat zwei Reiter; jeder Flug zählt im Reiter der Flotte des genutzten Flugzeugs.</li></ul></section>\n\n<section id=\"m-escala\"><h3>Flugumlauf</h3>\n<p>Das Menü <b>Umlauf</b> bietet zwei Modi:</p>\n<ul><li><b>Freier Flug:</b> Wählen Sie Abflugplatz, Airline und Flugzeug, unabhängig von einem RPL-Abflug.</li><li><b>RPL-Flüge:</b> Abflüge zwischen <b>30 und 90 Minuten ab jetzt</b>. RPL umfasst Inlandsflüge in Brasilien sowie internationale Flüge von oder nach Brasilien. Nach Wahl eines Flugs wählen Sie ein berechtigtes Flugzeug der Airline mit einem zum RPL passenden Modell.</li><li><b>Keine passende RPL-Option:</b> Gibt es keinen Flug mit berechtigtem Flugzeug oder kein RPL für den Flugplatz, bleibt die Wahl von Airline und Flugzeug frei.</li><li><b>Favoriten:</b> Favorisierte Flugzeuge haben in beiden Modi Vorrang bei der Wahl von Airline und Flugzeug.</li></ul>\n<p>Legen Sie den ersten Abflug, die Dauer von 1 bis 4 Tagen und die Anzahl der Flüge pro Tag fest. Jede Strecke beginnt dort, wo die vorige endet. Der Generator berücksichtigt Boden-, Dienst- und Ruhezeiten; prüfen Sie die Abfolge vor der Annahme.</p>\n<p>Vor der Annahme können Sie neue Optionen erzeugen. Mit <b>Umlauf annehmen</b> bestätigen Sie die Flüge: <b>Ein angenommener Umlauf kann nicht geändert werden</b>. Die Annahme schaltet das Briefing sowie die SimBrief- und SkyVector-Schaltflächen jedes Flugs frei.</p>\n<p><b>ADS-B dient nur zur Information.</b> Angaben zu Flugzeugen am Boden nennen Quelle und Aktualisierungszeit. Sie ändern weder Verfügbarkeit noch Flugzeugwahl, operative Position in der App oder den Umlauf; ein reales Flugzeug bestimmt nicht den erzeugten Flug.</p>\n<p>Karten und Hinweise zu jedem Flug finden Sie unter <b>Flugplan</b>. Abgeschlossene oder stornierte Flüge öffnen die operative Umlauftabelle nicht erneut.</p><p><b>Verspätung (DLA) und Nichterscheinen:</b> Die EOBT (geschätzte Off-Block-Zeit) steht auf der Flugkarte in Ihrem Flugplan. Wenn Sie sich verspäten, tippen Sie auf <b>Verspätung (DLA)</b> und wählen die neue EOBT: <b>eine DLA pro Flug</b>, aufgegeben bis <b>35 Min. nach der geplanten EOBT</b>, mit der neuen EOBT <b>höchstens 45 Min. nach Aufgabe der DLA</b>. Folgeflüge desselben Dienstes verschieben sich um dieselbe Zeit. Die Verschiebung endet an der Übernachtung, die Zeiten des nächsten Dienstes bleiben erhalten. Wird der verfolgte Flug nicht innerhalb von <b>45 Min. nach der gültigen EOBT</b> gestartet, wird der Flug storniert und unter Buchungen erscheint ein Hinweis. Nach Ablauf der EOBT zeigt die Karte die Frist in Rot.</p></section>\n<section id=\"m-livre\"><h3>Freier Flug (Freelancer)</h3>\n<p>Für Freelancer wird das Menü <b>Umlauf</b> zu <b>Freier Flug</b>. Es wird kein Umlauf erzeugt: Sie stellen die Flüge selbst zusammen.</p>\n<ol><li>Wählen Sie ein <b>Flugzeug</b> der Freelancer-Flotte (die Liste zeigt „meins“ bzw. wer es registriert hat und wo es steht).</li>\n<li>Der <b>Start der ersten Strecke</b> ist dort, wo das Flugzeug sein wird; ist es noch nie geflogen, wählen Sie den Start.</li>\n<li>Geben Sie <b>Ziel</b> und <b>Abflugzeit</b> an (mindestens 30 Min. ab jetzt). Die App berechnet Distanz, Blockzeit und Ankunft und prüft die Reichweite des Flugzeugs.</li>\n<li>Um die Reise fortzusetzen, tippen Sie auf <b>＋ Strecke hinzufügen</b>: Die nächste startet dort, wo die vorige landet, mit vorgeschlagenem Abflug 1 Std. nach der Ankunft (mindestens 45 Min. zwischen Ankunft und nächstem Abflug). Mit ✕ entfernen Sie eine Strecke. Bis zu 24 Strecken.</li>\n<li>Flugnummern werden fortlaufend vorgeschlagen und sind änderbar. Tippen Sie auf <b>Freien Flug buchen</b> (oder <b>N freie Flüge buchen</b>).</li></ol>\n<p>Nach der Buchung läuft alles wie bei einem Umlauf: Flugplan, Briefingraum, verfolgter Flug und Meldung nach der Landung.</p></section>\n\n<section id=\"m-reservar\"><h3>Ihr Flugplan</h3>\n<p>Der Reiter <b>Flugplan</b> beginnt mit <b>Ihr Flugplan</b>: eine Karte pro Flug mit Flugzeugfoto, Kennzeichen in den Airline-Farben, Flugnummer und Route, Datum und Uhrzeit (lokal und UTC) sowie der Airline.</p>\n<div class=\"scroll\"><table><thead><tr><th>Auf der Karte</th><th>Bedeutung</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">✓ Keine offenen Punkte im Bordbuch</span></td><td>Blinkt einmal als Hinweis. Nichts zu unterschreiben: <b>Verfolgter Flug</b> und <b>Flug melden</b> sind bereits freigeschaltet</td></tr>\n<tr><td><span class=\"chip warn\">⚠ Technisches Bordbuch prüfen</span></td><td>Blinkt weiter: Das Flugzeug hat einen offenen Punkt. Antippen, Punkte lesen und unterschreiben (siehe <b>Vor dem Flug</b>)</td></tr>\n<tr><td><span class=\"chip ok\">✓ Technisches Bordbuch geprüft</span></td><td>Sie haben unterschrieben; Sie können fliegen</td></tr></tbody></table></div>\n<ul><li><b>SimBrief</b> und <b>SkyVector</b>: Die Schaltflächen mit dem Symbol der jeweiligen Seite rechts öffnen die Planung des Flugs. SimBrief erhält zusätzlich die Flugzeugkennung und die EOBT; SkyVector erhält Route und Reiseflugschätzungen.</li><li><b>METAR und TAF:</b> Fahren Sie mit der Maus über einen Flughafencode (auf dem Handy antippen). <b>Dekodiert</b> zeigt die Meldung in Klartext (Wind, Sicht, Wolken, Temperatur, Luftdruck und jeden TAF-Zeitraum); <b>Original</b> zeigt wieder den Rohtext. Die App merkt sich Ihre Wahl.</li></ul>\n<p>Die Buchungen des Umlaufs entstehen bei der Annahme. Nutzen Sie die Flugkarten, um das Bordbuch zu prüfen, den Flug zu verfolgen und zu melden. Verwaltungs- und Event-Aktionen hängen von den für das Konto verfügbaren Optionen ab.</p></section>\n\n<section id=\"m-antes\"><h3>Vor dem Flug</h3>\n<p>Prüfen Sie vor dem Flug die Bordbuch-Schaltfläche auf der Flugkarte:</p>\n<ul><li><b>Keine offenen Punkte</b> (grün): keine Unterschrift nötig. Tippen Sie einfach auf <b>Verfolgter Flug</b> oder <b>Flug melden</b>.</li><li><b>Offener Punkt</b> (gelb blinkend): Tippen Sie auf <b>Technisches Bordbuch prüfen</b>, lesen Sie die offenen Punkte und letzten Meldungen, bestätigen Sie und tippen Sie auf <b>Technisches Bordbuch unterschreiben</b>. Die Schaltfläche wird grün und zeigt <b>Technisches Bordbuch geprüft</b>. Ohne diese Unterschrift werden Verfolgung und Meldung nicht akzeptiert.</li><li>Meldet ein anderer Pilot nach Ihrer Unterschrift einen Defekt an diesem Kennzeichen, erscheint die gelbe Schaltfläche wieder und Sie müssen erneut unterschreiben.</li></ul>\n<p>Ein Defekt wird nicht von einem Simulator in den anderen übertragen; daher hat jeder zurückgestellte Punkt ein <b>Verfahren für die nächste Crew</b>, das Sie auf Ihrem Flug befolgen. Beispiel: <i>APU startet nicht</i> → am Boden GPU und Fremdluft anfordern.</p></section>\n\n<section id=\"m-rastreio\"><h3>Verfolgter Flug</h3>\n<p>Die <b>validierte Verfolgung</b> ist der normale Weg, einen Flug zu erfassen und Stunden, Rang, Gehalt und Ranking zu zählen. Die App liest die Telemetrie des Simulators, der Server prüft die Flugspur. Ohne validierte Verfolgung beantragen Sie, sofern verfügbar, eine Prüfung: Ein Administrator entscheidet; vor der Genehmigung gibt es keinen Flugabschluss und keine Belohnungen.</p>\n<ol><li>Tippen Sie auf der Flugkarte in <b>Ihr Flugplan</b> auf <b>✈ Verfolgter Flug</b> (ab 1 Std. vor der gebuchten Zeit verfügbar; bei einem offenen Punkt zuerst das Bordbuch unterschreiben).</li>\n<li>Mit dem Flugzeug am Abflug-Gate stehend tippen Sie auf <b>Mit Simulator verbinden</b>.<ul>\n<li><b>MSFS 2020/2024:</b> Installieren Sie <a href=\"https://fsuipc.com\" target=\"_blank\" rel=\"noopener\">FSUIPC7</a> (die kostenlose Version genügt) und den <a href=\"http://fsuipcwebsockets.paulhenty.com/\" target=\"_blank\" rel=\"noopener\">FSUIPC WebSocket Server</a> und lassen Sie beide mit dem Simulator geöffnet.</li>\n\n<li><b>X-Plane 12</b> (12.1.4 oder neuer): nichts zu installieren.</li>\n<li><b>X-Plane 11:</b> Plugin XPUIPC + FSUIPC WebSocket Server.</li>\n<li>Verwenden Sie Chrome oder Edge auf demselben Computer wie den Simulator. Fragt der Browser nach Zugriff auf das lokale Netzwerk, erlauben Sie ihn.</li></ul></li>\n<li>Fliegen Sie normal und lassen Sie den Tab geöffnet. Der Bildschirm <b>Live-Flug</b> zeigt Phase, Höhe, Geschwindigkeit, Vertikalgeschwindigkeit und Distanz zum Ziel; andere Bildschirme können Sie währenddessen nutzen.</li>\n<li>Nach der Landung parken und das Flugzeug anhalten. Tippen Sie auf <b>Flug beenden</b>: Der Server prüft die Flugspur und zeigt das Ergebnis. Füllen Sie dann die Meldung aus (Defekte und Bemerkungen); Blockzeit und Ankunftsflughafen stammen aus der Verfolgung.</li></ol>\n<p>Der Server lehnt den Flug ab, wenn er nicht am Boden am Abflughafen beginnt · nicht stehend auf einem Flughafen endet · Zeitbeschleunigung oder Slew nutzt · das Flugzeug springt (Teleport oder Verschieben auf der Karte) · die Verfolgung in der Luft länger als 10 Min. unterbrochen ist · die Flugspur nicht in Echtzeit beim Server ankommt · der Flug weniger als 5 Min. in der Luft dauert. Pausieren ist erlaubt: Pausenzeit wird abgezogen. Ausweichlandungen werden akzeptiert: Das Flugzeug bleibt dort, wo es gelandet ist.</p></section>\n\n<section id=\"m-reporte\"><h3>Nach der Landung: Flug melden</h3>\n<ol><li>Tippen Sie auf <b>Flug melden</b>.</li><li>Wählen Sie den <b>Simulator</b> (nur Ihre werden angezeigt; für einen anderen wählen Sie <b>Anderer Simulator…</b>) und geben Sie die <b>Blockzeit</b> ein (h:mm, z. B. <code>1:45</code>).</li><li>Tippen Sie für jeden Defekt auf <b>Defekt hinzufügen</b>; ist nichts passiert, fügen Sie keinen hinzu.</li><li>Tippen Sie auf <b>Meldung senden und Buchung schließen</b>.</li></ol>\n<p>Das Defektfeld zeigt die <b>am häufigsten von Airline-Crews gemeldeten</b>. Beim Tippen wird die Liste kleiner: Sie versteht mehrere Sprachen, ignoriert Akzente und kennt Begriffe wie <code>brake</code>, <code>door</code>, <code>APU</code>, <code>ata 32</code> oder <code>ECAM</code>. Steht der Defekt nicht im Katalog, wählen Sie <b>Nicht in der Liste: beschreiben</b>.</p>\n<p>Der Pilot wählt weder Maßnahme noch Dauer: Beides ergibt sich aus dem im Katalog gewählten Defekt. Für Defekte außerhalb des Katalogs verwendet die App den häufigsten Standard des angegebenen ATA-Kapitels.</p><div class=\"scroll\"><table><thead><tr><th>Folge</th><th>Auswirkung auf das Flugzeug</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">Von der Crew behoben</span></td><td>Keine; bleibt nur in der Historie</td></tr>\n<tr><td><span class=\"chip warn\">Zurückgestellt (MEL)</span></td><td>Fliegt mit Einschränkung bis zur Frist (Kat. B 3 Tage, Kat. C 10 Tage, Kat. D 120 Tage); danach für die Reparaturdauer am Boden</td></tr>\n<tr><td><span class=\"chip bad\">Flugzeug am Boden</span></td><td>Für die durchschnittliche Reparaturdauer ab der Meldung nicht verfügbar</td></tr></tbody></table></div></section>\n\n<section id=\"m-frota\"><h3>Flotte</h3>\n<p>Der Reiter <b>Flotte</b> zeigt den Status jedes Kennzeichens. Oben <b>folgen die Summen den Filtern</b>: Flugzeuge der Auswahl, jetzt verfügbar, jetzt in der Luft, in den nächsten 24 Std. gebucht sowie eingeschränkt oder am Boden.</p>\n<ul><li><b>Filter in einer Zeile:</b> Region, Airline, Typ, Status und <b>Sortieren</b> (zuletzt geflogen, am meisten geflogen, verfügbare zuerst oder Kennzeichen), dazu die Suche nach Kennzeichen, Typ oder Flughafen (z. B. <code>SBGR</code>) und die Schaltfläche <b>Favoriten</b>.</li>\n<li><b>Nach Modell gruppiert:</b> Jede Gruppe zeigt, wie viele Flugzeuge sie hat und wie viele verfügbar sind.</li>\n<li><b>Eine Zeile pro Flugzeug:</b> Kennzeichen, Typ, <b>wo es steht</b>, <b>letzter Flug</b> (z. B. „SBGR → SBSV · vor 2 d“) oder nächstes Ereignis, <b>Verlauf</b> (Flüge und Stunden auf VFR) und Status. Verfügbare Flugzeuge haben nur einen grünen Punkt; farbige Abzeichen markieren Ausnahmen.</li>\n<li><b>Schmales Fenster</b> (halber Bildschirm): Die Zeile bricht in zwei Zeilen um, damit nichts abgeschnitten wird. Auf dem Handy erscheint die Flotte als Karten.</li>\n<li><b>Mehr Flugzeuge:</b> Tippen Sie unten auf <b>Mehr anzeigen</b>. <b>Registrieren:</b> <b>Flugzeug hinzufügen</b>.</li></ul>\n<div class=\"scroll\"><table><thead><tr><th>Status</th><th>Bedeutung</th><th>Fliegbar?</th></tr></thead><tbody>\n<tr><td><span class=\"fv-ok\">Verfügbar</span></td><td>Keine offenen Punkte und in den nächsten 24 Std. nicht in Gebrauch</td><td>Ja</td></tr>\n<tr><td><span class=\"pill fv-fly\">In der Luft</span></td><td>Ein Pilot hat das Flugzeug gerade; die Zeile zeigt die Ankunftszeit</td><td>Nach der Ankunft, ab dem Ziel</td></tr>\n<tr><td><span class=\"pill fv-res\">Gebucht</span></td><td>Buchung in den nächsten 24 Std. (Uhrzeit auf dem Abzeichen)</td><td>Außerhalb der gebuchten Zeit</td></tr>\n<tr><td><span class=\"pill warn\">Mit Einschränkung</span></td><td>Zurückgestellter Punkt (MEL); fliegt nach dem Verfahren</td><td>Ja, mit simulierter Einschränkung</td></tr>\n<tr><td><span class=\"pill bad\">AOG</span></td><td>Wegen Wartung am Boden; die Zeile zeigt die Rückkehr</td><td>Erst nach der Freigabe</td></tr>\n<tr><td><span class=\"pill fv-new\">Ohne Verlauf</span></td><td>Noch nie auf VFR geflogen; der erste Flug wählt den Start</td><td>Ja</td></tr></tbody></table></div>\n<p>Tippen Sie auf eine Zeile, um das <b>technische Bordbuch</b> zu öffnen: Foto, Übersicht (wo es steht, wann es verfügbar ist, nächste Buchung und letzter Pilot), offene Punkte und Verfahren, geplante Wartungen, Bemalungen für den Simulator, Zellenstunden, Zyklen und alle Flugseiten. Freelancer sehen nur die Freelancer-Flotte; Airline-Piloten nur die Airline-Flotten.</p></section>\n\n<section id=\"m-manut\"><h3>Automatische Wartung</h3>\n<ul><li>Nach Ablauf der Reparaturzeit wird das Flugzeug von selbst wieder <b>Verfügbar</b>.</li><li>Die Zeit läuft in echten Stunden ab der Meldung; überlappende Bodenzeiten addieren sich.</li><li>Ein abgelaufener MEL-Punkt setzt das Flugzeug für die Reparaturzeit dieses Punkts am Boden fest.</li><li>Buchungen innerhalb einer neuen Bodenzeit werden storniert, mit einem Hinweis oben in der App; spätere Buchungen bleiben bestehen. Dem betroffenen Piloten werden zur gleichen Zeit freie Flugzeuge <b>desselben Modells oder derselben Familie</b> angeboten (z. B. A320-Familie, 737 NG/MAX, E-Jets); ein Tippen öffnet eine vorausgefüllte Buchung mit gleicher Route, Zeit und Dauer.</li></ul></section>\n\n<section id=\"m-oper\"><h3>Realistischer Betrieb</h3>\n<p><b>Standort des Flugzeugs in der App.</b> Flughistorie und Systembuchungen sind von ADS-B-Beobachtungen getrennt. Prüfen Sie Flughinweise und Bordbuch; ADS-B-Daten versetzen das Flugzeug nicht und erfordern keinen Überführungsflug.</p>\n\n<p><b>Ausweichlandungen.</b> Die tatsächliche Ankunft muss den durchgeführten Flug und die Verfolgungs-/Meldedaten widerspiegeln. Prüfen Sie die Hinweise der betroffenen Buchungen; verwechseln Sie eine simulierte Ausweichlandung nicht mit einer ADS-B-Beobachtung.</p>\n<p><b>Planmäßige Checks.</b> Alle 120 Flugstunden oder 100 Zyklen erhält das Flugzeug einen A-Check (8 Stunden am Boden); alle 1.200 Stunden einen C-Check (48 Stunden). Der Check wird automatisch beim Abschluss des Flugs angelegt, der die Grenze erreicht, und Buchungen in diesem Zeitraum werden mit dem Angebot eines anderen Flugzeugs storniert. Das Bordbuch zeigt, wie viel noch übrig ist.</p>\n<p><b>SimBrief.</b> Geben Sie unter <b>Profil</b> (neben Ihrem Namen) Ihren SimBrief-Benutzernamen oder Ihre Pilot ID ein. „Aus SimBrief importieren“ in der Buchung übernimmt dann Flugzeug, Route, Zeit, Dauer und Flugnummer aus Ihrem letzten Plan. In der Meldung wird die Blockzeit automatisch ausgefüllt, wenn die Verfolgung verifiziert ist.</p>\n\n\n\n<p><b>Events.</b> Der Reiter Events listet vom Administrator veröffentlichte Gruppenflüge. Tippen Sie auf „Flugzeug für dieses Event buchen“: Flugzeuge, die am Abflughafen sein werden, erscheinen zuerst.</p>\n<p><b>Benachrichtigungen.</b> Die Glocke oben meldet, wenn Ihre Buchung naht, wenn das gebuchte Flugzeug eine neue Meldung erhalten hat, wenn eine Buchung wegen Wartung storniert wurde, wenn ein Flug noch abgeschlossen werden muss, sowie Events und Abzeichen. Unter „Benachrichtigungen auf diesem Gerät“ können Sie Systembenachrichtigungen aktivieren, die bei geöffneter App oder im Hintergrund erscheinen.</p>\n<p><b>Karriere.</b> Das Flugbuch zeigt Ihren Rang (vom Kadetten bis zum Master Captain, nach Flugstunden) und Ihre Abzeichen. Ränge sind reine Anerkennung: Jeder Pilot kann jedes Flugzeug fliegen.</p></section>\n\n<section id=\"m-mapa\"><h3>Karte und Flugdetails</h3>\n<p>Die Karte priorisiert <b>Ihren aktiven Flug</b>. Gibt es keinen, nutzt sie den letzten verfügbaren SimBrief-Dispatch, sofern Ihr Benutzername/Ihre Pilot ID im Profil eingetragen ist. Ein angenommener Umlauf wird dadurch nicht geändert. Ein anderer Dispatch ersetzt keinen aktiven Flug. Ohne detaillierte Navlog-Daten ist die direkte Linie vom Start zum Ziel eine Referenz, keine validierte Navigationsroute.</p>\n<p>Die Seitenleiste enthält <b>nur verfolgte Flüge</b>, keine Flughafenstatistiken, Flughafenerkundung oder RPL-Abflüge. Die Ebenensteuerung oben rechts bietet Grundkarten, Verkehr, Lotsen und Überlagerungen. Die brasilianischen DECEA-Karten haben Regler für Typ/Blatt und Deckkraft; prüfen Sie die offizielle Ausgabe.</p>\n<p><b>Fahren Sie über ein Flugzeug und klicken Sie es an</b> (auf dem Handy antippen), um Details zu öffnen. Die Kopfzeile hebt Rufzeichen und Airline-Symbol hervor, wenn die Airline erkannt wird; die Kennzeichenfarben folgen der erkannten Airline. Höhe, Geschwindigkeit über Grund (GS), Steuerkurs (HDG), Position, Quelle und weitere verfügbare Angaben sind übersichtlich gruppiert. Lange Fenster scrollen; fehlende Daten werden nicht erfunden.</p>\n<p>Daten von <b>verfolgten FlyVFR-Flügen</b> stammen aus dem Simulator, <b>IVAO/VATSIM</b> aus deren Netzwerken und <b>ADS-B</b> aus Beobachtungen echter Flugzeuge. Schätzungen anhand der Buchungszeit sind als Schätzungen gekennzeichnet, nicht als Telemetrie. ADS-B dient nur zur Information und ändert weder Verfügbarkeit, Flugzeugwahl noch Umlauf.</p></section>\n<section id=\"m-brief\"><h3>Briefingraum, ADC und NOTAMs</h3>\n<p>Wählen Sie einen gebuchten Flug des Umlaufs, um METAR/TAF, NOTAMs und Streckenwetter zu sehen. Geben Sie bei Bedarf den <b>Ausweichflughafen</b> und seine <b>ETA</b> an. Ohne eigene ETA des Ausweichflughafens wird die ETA des Ziels verwendet und gekennzeichnet. Ausweichflughafen und ETA werden pro Pilot/Flug auf dem Gerät gespeichert, ohne die Buchung zu ändern.</p>\n<p>Auf der ADC werden nur <b>Start, Ziel und Ausweichflughafen</b> des gewählten Flugs ausgewertet. Der Start nutzt die EOBT, Ziel und Ausweichflughafen ihre ETAs. Hat ein Flugplatz mehrere Rollen, werden die jeweiligen Zeiten berücksichtigt. Abgelaufene, künftige, aufgehobene oder ersetzte NOTAMs werden nicht als aktiv hervorgehoben; nicht interpretierbare Zeitpläne erfordern eine Prüfung.</p>\n<p><b>Die ADC-Ebene ist nur bei einem für die Flugzeit bestätigten aktiven NOTAM und aktuellen Quelldaten verfügbar.</b> Andernfalls wird die Karte aus Anzeige und Ebenen entfernt. Das bedeutet nicht, dass der Flugplatz ohne Einschränkungen ist. Es gibt keine eigene Schaltfläche „Karte anzeigen“: Nutzen Sie die Flugplatzauswahl und die Kartenebenen.</p>\n<ul><li><b>Vollständige Pistensperrung:</b> nur bei ausdrücklichem Text, vollständigem Schwellenpaar und verifizierter Geometrie hervorgehoben.</li><li><b>Koordinaten im Text:</b> erscheinen als Punkte, auch außerhalb des ADC-Bilds. Ein ausdrücklich begrenzter, gültiger und eindeutiger Bereich kann gestrichelt erscheinen; Hindernislisten werden nicht automatisch verbunden.</li><li><b>Verifizierte Referenzen:</b> Markierungen für Rollwege oder Ausrüstung zeigen eine Kartenreferenz, nicht unbedingt die genaue Position. Eine nicht verfügbare Haltebalkenbefeuerung bedeutet keinen gesperrten Rollweg.</li><li><b>Allgemeine Hinweise:</b> Aktive Hinweise ohne genaue Position werden an einer klar gekennzeichneten Referenzmarke des Flugplatzes gesammelt; sie stellt nicht den betroffenen Bereich dar.</li><li><b>Q-Zeile:</b> Mittelpunkt und Radius sind Referenzen, nicht die genaue Lage einer Piste, eines Rollwegs oder einer Ausrüstung und kein angenommener Sperrbereich.</li></ul>\n<p>Die georeferenzierte ADC hängt von einer validierten offiziellen Karte ab. Fehlende Karten werden angezeigt; die Hinweise bleiben verfügbar, ohne eine Ausrichtung zu erfinden. Die Kartenkataloge sind statische Referenzen dieser Version ohne automatische Aktualisierung. Prüfen Sie stets die offiziellen Originale. <b>Nur für die Simulation.</b></p><p><b>Untermenü des Briefingraums:</b> Flug, Flugzeug, Verfolgter Flug, Karte, Wetter, NOTAMs, Online-Netzwerke, Karten, Flugplan und Briefing-Checkliste, jeweils mit eigenem Symbol in der Seitenleiste des Briefings.</p>\n<ul><li><b>Flugzeug:</b> Kennzeichen und Modell, <b>Bemalungen für den Simulator</b> (Download-Links auf flightsim.to oder x-plane.org, gefiltert nach den Simulatoren in Ihrem Profil) und das technische Bordbuch.</li>\n<li><b>Verfolgter Flug:</b> „So verbinden Sie Ihren Simulator“ öffnet sich auf derselben Seite unter den Flugdaten.</li>\n<li><b>Karten:</b> Unter „Für diesen Flug vorausgewählt“ behält jede Karte die Farbe ihres Typs (ADC blau, SID grün, STAR violett, IAC magenta …), wie unter „Weitere verfügbare Karten“. Markieren Sie die gewünschten und nutzen Sie <b>Als eine PDF herunterladen</b>.</li></ul></section>\n<section id=\"m-redes\"><h3>IVAO und VATSIM</h3>\n<ol><li>Öffnen Sie das <b>Profil</b> und geben Sie optional Ihre <b>VATSIM-CID</b>, Ihre <b>IVAO-VID</b> und das bevorzugte Netzwerk ein. Speichern Sie Ihre Einstellungen.</li><li>Das Feld <b>Online-Netzwerke</b> im Briefing zeigt passende Rufzeichen, Frequenzen und verfügbare ATIS für Start, Ziel und Ausweichflughafen. Klappen Sie eine Station für ihren Text auf, filtern Sie nach Netzwerk oder aktualisieren Sie.</li><li>Die Kartenebenen zeigen Lotsen je Netzwerk und <b>übereinstimmende angegebene IDs</b>. Stationen am selben Punkt werden gruppiert; klicken Sie, um sie zu lesen. Die ID-Übereinstimmung hebt das beobachtete Rufzeichen hervor.</li></ol>\n<p>Die Einstellung legt die Anfangsauswahl fest; die Kartenebenen lassen sich unabhängig ändern. UTC-Zeiten der Quellen beschreiben den <b>aktuellen Stand</b>, nicht die künftige ATC-Verfügbarkeit. Fehlende oder veraltete Quellen gelten als unbestätigt, und eine fehlende ID-Übereinstimmung beweist keine Trennung. Erweiterte APP/Center-Abdeckung oder Sektorgrenzen werden nicht aus Rufzeichen oder Markerpositionen abgeleitet.</p>\n<p><b>IDs sind Selbstangaben, keine verifizierten Identitäten.</b> Diese Felder melden Sie nicht bei den Netzwerken an: Nutzen Sie dafür den Netzwerk-Client des Simulators. Die Netzwerkerkennung validiert keine Meldungen, vergibt keine Stunden und ersetzt nicht die von der App verlangte Verfolgung.</p></section>\n\n<section id=\"m-diario\"><h3>Flugbuch, Gehalt und Katalog</h3>\n<p><b>Flugbuch → Mein Flugbuch</b> zeigt Ihre Stunden: gesamt, letzte 30 Tage, dieses Jahr, Stunden nach Flugzeugtyp, Airline und Simulator, meistgeflogene Kennzeichen (in Airline-Farben, mit Modell daneben) und die Flugliste, mit <b>CSV exportieren</b> für Tabellen. Die Stunden stammen aus der Blockzeit jeder Meldung. <b>Gehalt</b> ist eine fiktive Abrechnung: pro Flugstunde nach Rang und Flugzeugkategorie plus Übernachtungsspesen. Beträge werden in US-Dollar festgelegt und zum <b>Wechselkurs des jeweiligen Flugdatums</b> in die gewählte Währung umgerechnet (Spalte Kurs). Das <b>Piloten-Ranking</b> vergleicht die Gruppe (gesamter Zeitraum, dieses Jahr oder 30 Tage) und hat zwei Reiter: Airline-Piloten und Freelancer; tippen Sie auf einen Piloten, um sein Flugbuch zu sehen. <b>Alle Einträge</b> listet jeden gemeldeten Flug mit fortlaufender Seite pro Flugzeug (TL 0001…), Route, Pilot, Simulator, Blockzeit und Defekten. Der <b>Defektkatalog</b> enthält die 123 Standarddefekte nach ATA-Kapitel, mit Standardmaßnahme, durchschnittlicher Reparaturdauer, MEL-Frist und Verfahren.</p></section>\n\n<section id=\"m-apoie\"><h3>Projekt unterstützen</h3>\n<p>Die App ist kostenlos. Im Reiter <b>Unterstützen</b> können Sie per Pix-QR-Code, Pix-Code zum Kopieren oder über die anderen angegebenen Optionen (Karte, PayPal und mehr) einen beliebigen Betrag spenden.</p></section>\n\n<section id=\"m-faq\"><h3>Häufige Fragen</h3>\n<div class=\"scroll\"><table><thead><tr><th>Situation</th><th>Was tun</th></tr></thead><tbody>\n<tr><td>Ich kann mich nicht anmelden</td><td>Prüfen Sie E-Mail und Passwort. Wenn Sie es vergessen haben, tippen Sie auf dem Anmeldebildschirm auf <b>Passwort vergessen?</b>: Sie erhalten einen Link per E-Mail, um ein neues zu erstellen</td></tr>\n<tr><td>Meine Buchung wurde abgelehnt</td><td>Lesen Sie die rote Meldung: Überschneidung, Wartung, Dauer außerhalb des Bereichs oder Wochenlimit für dieses Kennzeichen</td></tr>\n<tr><td>Die gewünschte Dauer fehlt</td><td>Es erscheinen nur Dauern von Flug + 45 Min. bis Flug + 2 Std.; prüfen Sie Start und Ankunft</td></tr>\n<tr><td>Keine Schaltfläche Flug melden</td><td>Das Flugzeug hat einen offenen Punkt: Tippen Sie auf die gelbe Schaltfläche <b>Technisches Bordbuch prüfen</b> und unterschreiben Sie</td></tr>\n<tr><td>Ich möchte meinen Umlauf stornieren</td><td>Ein angenommener Umlauf kann nicht storniert werden; nicht geflogene Flüge werden am 🔒-Datum automatisch freigegeben</td></tr>\n<tr><td>Meine Buchung ist verschwunden</td><td>Sie wurde möglicherweise wegen Wartung storniert; siehe Hinweis oben</td></tr>\n<tr><td>Kein METAR angezeigt</td><td>Kleine Flughäfen geben eventuell kein METAR oder TAF heraus; nutzen Sie den Link zu aviationweather.gov</td></tr>\n<tr><td>Eine neue Funktion erscheint nicht</td><td>Am PC <b>Strg+Umschalt+R</b> drücken; am Handy die App schließen und neu öffnen</td></tr>\n<tr><td>Ich bin offline</td><td>Die App öffnet mit den letzten Daten, nur lesend; Buchungen und Meldungen brauchen eine Verbindung</td></tr><tr><td>Ich möchte vom Airline-Piloten zum Freelancer wechseln (oder umgekehrt)</td><td>Nutzen Sie <b>Profil ändern</b> in Umlauf/Freier Flug: einmal alle 30 Tage und ohne gebuchte Flüge</td></tr>\n<tr><td>Ich bin Freelancer und die Flotte ist leer</td><td>Registrieren Sie Ihr Flugzeug über <b>Flugzeug hinzufügen</b> (echtes Kennzeichen) oder fliegen Sie eines, das ein anderer Freelancer registriert hat</td></tr></tbody></table></div></section>\n"};
MANUAL.ja={fvUpdated:true,toc:[["m-ciclo","しくみ"],["m-inicio","はじめに"],["m-perfil","パイロットのプロフィール"],["m-escala","ロスター"],["m-livre","フリーフライト(フリーランス)"],["m-reservar","スケジュール"],["m-antes","飛行前"],["m-rastreio","追跡フライト"],["m-reporte","着陸後"],["m-frota","フリート"],["m-manut","自動整備"],["m-oper","リアルな運航"],["m-mapa","地図とフライト詳細"],["m-brief","ブリーフィング、ADC、NOTAM"],["m-redes","IVAO と VATSIM"],["m-diario","ログブック、給与、カタログ"],["m-apoie","サポート"],["m-faq","よくある質問"]],body:"\n<p class=\"muted manual-updated\">2026年10月30日更新。</p>\n<section id=\"m-ciclo\"><h3>Virtual Flight Report のしくみ</h3>\n<p><b>すべてのフライトが記録に残ります。</b> Virtual Flight Report は共有のテクニカルログです。各機体は登録記号で識別され、MSFS や X-Plane でその機体を飛ばしたパイロット全員が、起きたことを記録します。次のパイロットは、前のパイロットが残したとおりの状態で機体を受け取ります。</p>\n<div class=\"cycle\"><span class=\"cy-step\">ロスターを作成</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">テクニカルログを確認</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">シミュレーターで飛行</span><span class=\"cy-arrow\">→</span><span class=\"cy-step strong\">フライトを報告</span></div>\n<div class=\"cycle out\"><span class=\"chip ok\">修理済み:引き続き利用可能</span><span class=\"chip warn\">保留(MEL):制限付きで飛行</span><span class=\"chip bad\">地上待機:修理後に解除</span></div>\n<p class=\"muted\">不具合ごとに結果が決まっています。選んだ不具合に応じて、機体が利用可能のままか、制限付きで飛ぶか、地上待機になるか、そしてその期間をアプリが自動で判断します。</p></section>\n\n<section id=\"m-inicio\"><h3>はじめに</h3>\n<p>パイロットアカウントは一度作成すれば、すべての端末で使えます。</p>\n<ol><li><b>flyvfr.com.br</b> を開き、<b>ログイン</b>をタップします。</li><li><b>新しいパイロット?アカウントを作成</b>をタップします。</li><li><b>パイロット名</b>(他の人に表示される名前やコールサイン)、<b>メールアドレス</b>、<b>使用するシミュレーター</b>、6文字以上の<b>パスワード</b>を入力します。後でシミュレーターを変更するには、名前の横の<b>プロフィール</b>をタップします。</li><li><b>アカウントを作成</b>をタップします。次回からは<b>ログイン</b>を使います。</li></ol>\n<p>ログイン後、承認済みのロスターがあれば<b>スケジュール</b>、なければ<b>ロスター</b>が開きます。メニューはパイロットの1日の流れに沿っています:ロスター、ブリーフィングルーム(承認済みロスターで有効)、予約、フリート、地図、イベント、ログブック、カタログ、マニュアル、サポート。</p>\n<div class=\"scroll\"><table><thead><tr><th>端末</th><th>インストール方法</th></tr></thead><tbody>\n<tr><td>PC(Chrome または Edge)</td><td>ページ上部の<b>アプリをインストール</b>、またはアドレスバーのインストールアイコン</td></tr>\n<tr><td>Android</td><td>Chrome のメニュー ⋮ → <b>アプリをインストール</b>(管理者が共有した場合は <b>VirtualFlightReport.apk</b> ファイル)</td></tr>\n<tr><td>iPhone / iPad(Safari)</td><td><b>共有</b> → <b>ホーム画面に追加</b></td></tr></tbody></table></div>\n<p>メニューの<b>設定</b>で、国旗から言語(英語、ポルトガル語、スペイン語、フランス語、ドイツ語、日本語、中国語、韓国語)、カラーテーマ、メニューの位置を選べます。<b>DAY MODE / NIGHT MODE</b> ボタンでライトとダークを切り替えます。選択は端末に保存されます。アプリの改善は再インストールなしで PC と携帯に自動で届きます。ログアウトするには、名前の横の<b>ログアウト</b>をタップします。</p><p><b>パイロットのプロフィール。</b> 登録時に飛び方を選びます:<b>エアライン・パイロット</b>または<b>フリーランス</b>。既存のパイロットは次回ログイン時に選びます。<a href=\"#m-perfil\" data-action=\"man-jump\" data-to=\"m-perfil\">パイロットのプロフィール</a>をご覧ください。</p></section>\n<section id=\"m-perfil\"><h3>パイロットのプロフィール:エアラインかフリーランスか</h3>\n<div class=\"scroll\"><table><thead><tr><th></th><th>✈ エアライン・パイロット</th><th>🛩 フリーランス</th></tr></thead><tbody>\n<tr><td>飛ばす機材</td><td>航空会社の機材のみ</td><td>フリーランス機材のみ:自分が登録した機体と、他のフリーランスが登録した機体</td></tr>\n<tr><td>予約方法</td><td><b>ロスター</b>:アプリが作成する RPL 便またはフリーロスター</td><td><b>フリーフライト</b>:パイロット自身が組む1区間または連続区間</td></tr>\n<tr><td>航空会社</td><td>どの航空会社でも可。ただし前回のロスター完了後</td><td>—</td></tr>\n<tr><td>ランキング</td><td><b>エアライン・パイロット</b>タブ</td><td><b>フリーランス</b>タブ</td></tr></tbody></table></div>\n<ul><li><b>プロフィールの変更:</b> ロスター(またはフリーフライト)上部の<b>プロフィールを変更</b>をタップします。<b>30日に1回</b>、かつ<b>予約中の便がない</b>場合のみ変更できます。画面に次に変更できる日付が表示されます。</li>\n<li><b>フリーランスの共有機材:</b> 機体を登録する際、フリーランスは他のフリーランスがその機体を飛ばせること、自分も他の人の機体を飛ばせることを確認します。位置とテクニカルログは全員共通で、次の便は前の便が着陸した空港から出発します。</li>\n<li><b>登録記号は一意:</b> すでにフリートにある登録記号は登録できません。</li>\n<li>ログブックのランキングには2つのタブがあり、各フライトは使用した機体の機材区分のタブに集計されます。</li></ul></section>\n\n<section id=\"m-escala\"><h3>フライトロスター</h3>\n<p><b>ロスター</b>メニューには2つのモードがあります:</p>\n<ul><li><b>フリー:</b> RPL の出発便に関係なく、出発空港、航空会社、機体を選びます。</li><li><b>RPL 便:</b> <b>今から30〜90分後</b>の出発便を表示します。RPL はブラジル国内線と、ブラジル発着の国際線を対象とします。便を選んだら、その航空会社で RPL に適合する機種の対象機体を選びます。</li><li><b>対象の RPL がない場合:</b> 対象機体のある便がない、または空港に RPL がない場合は、航空会社と機体を自由に選べます。</li><li><b>お気に入り:</b> どちらのモードでも、お気に入りの機体が航空会社と機体の選択で優先されます。</li></ul>\n<p>最初の出発、1〜4日の期間、1日の便数を設定します。各区間は前の区間の到着地から始まります。ジェネレーターは地上時間、勤務時間、休息時間を考慮します。承認前に順序を確認してください。</p>\n<p>承認前なら新しい案を作成できます。<b>ロスターを承認</b>をタップして便を確定します:<b>承認したロスターは変更できません</b>。承認するとブリーフィングと各便の SimBrief・SkyVector ボタンが使えるようになります。</p>\n<p><b>ADS-B は参考情報です。</b> 地上機の情報には出典と更新時刻が表示されます。機体の利用可否、選択、アプリ内の運用位置、ロスターは変わりません。実機の存在が作成される便を決めることはありません。</p>\n<p>各便のカードとお知らせは<b>スケジュール</b>で確認します。完了またはキャンセルされた便がロスターの運用表に再び開くことはありません。</p><p><b>遅延(DLA)と不出頭:</b> EOBT(推定オフブロック時刻)は「あなたのスケジュール」の便カードに表示されます。遅れる場合は<b>遅延(DLA)</b>をタップして新しい EOBT を選びます:<b>1便につき DLA は1回</b>、<b>予定 EOBT の35分後まで</b>提出でき、新しい EOBT は<b>DLA 提出時刻から45分以内</b>です。同じ勤務の後続便も同じだけ遅れます。遅延の伝播は夜間の休息で止まり、次の勤務の時刻は維持されます。<b>有効な EOBT から45分以内</b>に追跡フライトを開始しない場合、便はキャンセルされ、予約にお知らせが表示されます。EOBT を過ぎると、カードに期限が赤で表示されます。</p></section>\n<section id=\"m-livre\"><h3>フリーフライト(フリーランス)</h3>\n<p>フリーランスの場合、<b>ロスター</b>メニューは<b>フリーフライト</b>になります。ロスターの自動作成はなく、自分で便を組みます。</p>\n<ol><li>フリーランス機材から<b>機体</b>を選びます(一覧には「自分の機体」または登録者と、現在地が表示されます)。</li>\n<li><b>最初の区間の出発地</b>は機体がいる空港です。まだ一度も飛んでいない機体なら、出発地を選びます。</li>\n<li><b>目的地</b>と<b>出発時刻</b>(今から30分以上先)を入力します。アプリが距離、ブロックタイム、到着を計算し、機体の航続距離を確認します。</li>\n<li>旅を続けるには<b>＋ 区間を追加</b>をタップします。次の区間は前の区間の到着地から出発し、出発は到着の1時間後が提案されます(到着から次の出発まで最低45分)。✕ で区間を削除できます。最大24区間です。</li>\n<li>便名は連番で提案され、編集できます。<b>フリーフライトを予約</b>(または<b>フリーフライトN便を予約</b>)をタップします。</li></ol>\n<p>予約後はロスターと同じ流れです:スケジュール、ブリーフィングルーム、追跡フライト、着陸後の報告。</p></section>\n\n<section id=\"m-reservar\"><h3>フライトスケジュール</h3>\n<p><b>スケジュール</b>タブは<b>あなたのスケジュール</b>から始まります:自分の各便ごとに、機体写真、航空会社の色の登録記号、便名とルート、日時(現地時刻と UTC)、航空会社を表示するカードがあります。</p>\n<div class=\"scroll\"><table><thead><tr><th>カードの表示</th><th>意味</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">✓ ログに未解決項目なし</span></td><td>お知らせとして1回点滅します。署名は不要で、<b>追跡フライト</b>と<b>フライトを報告</b>がすでに使えます</td></tr>\n<tr><td><span class=\"chip warn\">⚠ テクニカルログを確認</span></td><td>点滅が続きます:機体に未解決の項目があります。タップして項目を読み、署名します(<b>飛行前</b>を参照)</td></tr>\n<tr><td><span class=\"chip ok\">✓ テクニカルログ確認済み</span></td><td>署名済みです。飛行できます</td></tr></tbody></table></div>\n<ul><li><b>SimBrief</b> と <b>SkyVector</b>:右側の各サイトのアイコン付きボタンで、その便の計画を開きます。SimBrief には機体の識別情報と EOBT も、SkyVector にはルートと巡航の見積もりも渡されます。</li><li><b>METAR と TAF:</b> 空港コードにマウスを合わせます(携帯ではタップ)。<b>解読</b>をタップすると平易な言葉で読めます(風、視程、雲、気温、気圧、TAF の各期間)。<b>原文</b>で元のテキストに戻ります。選択はアプリが記憶します。</li></ul>\n<p>ロスターの予約は承認時に作成されます。便カードからテクニカルログの確認、追跡、報告を行います。管理やイベントの操作は、アカウントで利用できるオプションによります。</p></section>\n\n<section id=\"m-antes\"><h3>飛行前</h3>\n<p>飛行前に、便カードのテクニカルログのボタンを確認します:</p>\n<ul><li><b>未解決項目なし</b>(緑):署名は不要です。<b>追跡フライト</b>または<b>フライトを報告</b>をタップするだけです。</li><li><b>未解決項目あり</b>(黄色の点滅):<b>テクニカルログを確認</b>をタップし、未解決項目と最近の報告を読み、確認にチェックして<b>テクニカルログに署名</b>をタップします。ボタンが緑になり<b>テクニカルログ確認済み</b>と表示されます。この署名がないと、追跡と報告は受け付けられません。</li><li>署名後に他のパイロットがその登録記号に不具合を報告すると、黄色のボタンが戻り、再度署名が必要です。</li></ul>\n<p>不具合はシミュレーター間で引き継がれないため、保留項目にはそれぞれ<b>次の乗員のための手順</b>があり、あなたの飛行でそれに従います。例:<i>APU が始動しない</i> → 地上で GPU と外部エアを要求。</p></section>\n\n<section id=\"m-rastreio\"><h3>追跡フライト</h3>\n<p><b>検証済みの追跡</b>が、フライトを記録して時間、ランク、給与、ランキングに数える通常の方法です。アプリがシミュレーターのテレメトリを読み取り、サーバーが航跡を確認します。検証済みの追跡がない場合は、利用可能であれば審査を申請します。管理者が判断し、承認前にフライトの完了や報酬はありません。</p>\n<ol><li><b>あなたのスケジュール</b>の便カードで <b>✈ 追跡フライト</b>をタップします(予約時刻の1時間前から利用可能。未解決項目がある場合は先にテクニカルログに署名)。</li>\n<li>機体を出発ゲートで停止させた状態で、<b>シミュレーターに接続</b>をタップします。<ul>\n<li><b>MSFS 2020/2024:</b> <a href=\"https://fsuipc.com\" target=\"_blank\" rel=\"noopener\">FSUIPC7</a>(無料版で十分)と <a href=\"http://fsuipcwebsockets.paulhenty.com/\" target=\"_blank\" rel=\"noopener\">FSUIPC WebSocket Server</a> をインストールし、シミュレーターと一緒に両方を開いておきます。</li>\n\n<li><b>X-Plane 12</b>(12.1.4 以降):インストール不要です。</li>\n<li><b>X-Plane 11:</b> XPUIPC プラグイン + FSUIPC WebSocket Server。</li>\n<li>シミュレーターと同じコンピューターで Chrome または Edge を使います。ブラウザーがローカルネットワークへのアクセスを求めたら許可します。</li></ul></li>\n<li>普段どおり飛び、タブは開いたままにします。<b>ライブフライト</b>画面にはフェーズ、高度、速度、昇降率、目的地までの距離が表示されます。その間、他の画面も使えます。</li>\n<li>着陸後、駐機して機体を停止します。<b>フライト終了</b>をタップすると、サーバーが航跡を確認して結果を表示します。続いて報告(不具合と備考)を記入します。ブロックタイムと到着空港は追跡から取得されます。</li></ol>\n<p>次の場合、サーバーはフライトを却下します:出発空港の地上で始まらない · 空港で停止して終わらない · 時間加速やスルーを使う · 機体の位置が飛ぶ(テレポートや地図上での移動)· 空中で追跡が10分以上途切れる · 航跡がリアルタイムでサーバーに届かない · 空中にいる時間が5分未満。一時停止は可能で、停止時間は差し引かれます。ダイバートは受け付けられ、機体は着陸した場所に残ります。</p></section>\n\n<section id=\"m-reporte\"><h3>着陸後:フライトを報告</h3>\n<ol><li><b>フライトを報告</b>をタップします。</li><li><b>シミュレーター</b>を選び(自分のものだけが表示されます。それ以外は<b>その他のシミュレーター…</b>)、<b>ブロックタイム</b>を入力します(h:mm、例:<code>1:45</code>)。</li><li>不具合ごとに<b>不具合を追加</b>をタップします。何もなければ追加しません。</li><li><b>報告を送信して予約を閉じる</b>をタップします。</li></ol>\n<p>不具合欄には<b>エアラインの乗員が最も多く報告するもの</b>が表示されます。入力すると一覧が絞り込まれます。複数の言語を理解し、アクセントを無視し、<code>brake</code>、<code>door</code>、<code>APU</code>、<code>ata 32</code>、<code>ECAM</code> などの用語を認識します。カタログにない場合は<b>一覧にない:説明する</b>を選びます。</p>\n<p>パイロットは処置や期間を選びません。カタログで選んだ不具合によって決まります。カタログ外の不具合には、指定した ATA 章で最も一般的な既定値が使われます。</p><div class=\"scroll\"><table><thead><tr><th>結果</th><th>機体への影響</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">乗員が修理</span></td><td>なし。履歴にのみ残ります</td></tr>\n<tr><td><span class=\"chip warn\">保留(MEL)</span></td><td>期限まで制限付きで飛行(Cat B 3日、Cat C 10日、Cat D 120日)。その後、修理時間のあいだ地上待機</td></tr>\n<tr><td><span class=\"chip bad\">地上待機</span></td><td>報告時点から平均修理時間のあいだ利用不可</td></tr></tbody></table></div></section>\n\n<section id=\"m-frota\"><h3>フリート</h3>\n<p><b>フリート</b>タブは登録記号ごとの状況を表示します。上部の<b>合計はフィルターに連動</b>します:選択中の機体数、現在利用可能、現在飛行中、24時間以内に予約済み、制限中または地上待機。</p>\n<ul><li><b>1行のフィルター:</b> 地域、航空会社、機種、状況、<b>並べ替え</b>(最近飛行、飛行回数順、利用可能を先に、登録記号)、登録記号・機種・空港(例:<code>SBGR</code>)での検索、<b>お気に入り</b>ボタン。</li>\n<li><b>機種ごとにグループ化:</b> 各グループに機体数と利用可能数が表示されます。</li>\n<li><b>1機につき1行:</b> 登録記号、機種、<b>現在地</b>、<b>前回の飛行</b>(例:「SBGR → SBSV · 2 d前」)または次の予定、<b>履歴</b>(VFR での便数と時間)、状況。利用可能な機体は緑の点だけで、色付きのバッジは例外を示します。</li>\n<li><b>狭いウィンドウ</b>(画面の半分):何も切れないよう、行が2行に折り返されます。携帯ではカード表示になります。</li>\n<li><b>さらに表示:</b> 一覧の最後の<b>さらに表示</b>をタップします。<b>登録:</b> <b>機体を追加</b>。</li></ul>\n<div class=\"scroll\"><table><thead><tr><th>状況</th><th>意味</th><th>飛べるか</th></tr></thead><tbody>\n<tr><td><span class=\"fv-ok\">利用可能</span></td><td>未解決項目がなく、24時間以内に使用予定なし</td><td>はい</td></tr>\n<tr><td><span class=\"pill fv-fly\">飛行中</span></td><td>現在パイロットが使用中。行に到着時刻を表示</td><td>到着後、目的地から</td></tr>\n<tr><td><span class=\"pill fv-res\">予約済み</span></td><td>24時間以内に予約あり(時刻はバッジに表示)</td><td>予約時間以外</td></tr>\n<tr><td><span class=\"pill warn\">制限付き</span></td><td>保留項目(MEL)。手順に従って飛行</td><td>はい、制限を再現して</td></tr>\n<tr><td><span class=\"pill bad\">AOG</span></td><td>整備のため地上待機。行に復帰時刻を表示</td><td>解除後のみ</td></tr>\n<tr><td><span class=\"pill fv-new\">履歴なし</span></td><td>VFR で未飛行。最初の便が出発地を選びます</td><td>はい</td></tr></tbody></table></div>\n<p>行をタップすると<b>テクニカルログ</b>が開きます:写真、概要(現在地、利用可能になる時刻、次の予約、前回のパイロット)、未解決項目と手順、定期整備、シミュレーター用塗装、機体時間、サイクル、すべてのフライトページ。フリーランスにはフリーランス機材だけが、エアライン・パイロットには航空会社の機材だけが表示されます。</p></section>\n\n<section id=\"m-manut\"><h3>自動整備</h3>\n<ul><li>修理時間が終わると、機体は自動的に<b>利用可能</b>に戻ります。</li><li>時間は報告時点から実時間で進み、重なった地上待機は合算されます。</li><li>期限切れの MEL 項目は、その項目の修理時間のあいだ機体を地上待機にします。</li><li>新たな地上待機期間内の予約はキャンセルされ、アプリ上部にお知らせが出ます。それ以降の予約は維持されます。影響を受けたパイロットには、同じ時間に空いている<b>同じ機種またはファミリー</b>の機体(例:A320 ファミリー、737 NG/MAX、E-Jets)が提案され、タップ1回で同じルート・時刻・時間が入力済みの予約が開きます。</li></ul></section>\n\n<section id=\"m-oper\"><h3>リアルな運航</h3>\n<p><b>アプリ内の機体位置。</b> 飛行履歴とシステムの予約は ADS-B の観測とは別です。便のお知らせとテクニカルログを確認してください。ADS-B のデータが機体の位置を変えたり、回航を求めたりすることはありません。</p>\n\n<p><b>ダイバート。</b> 実際の到着は、実施したフライトと追跡・報告のデータを反映する必要があります。影響を受けた予約のお知らせを確認し、シミュレーション上のダイバートと ADS-B の観測を混同しないでください。</p>\n<p><b>定期点検。</b> 飛行120時間または100サイクルごとに A チェック(地上8時間)、1,200時間ごとに C チェック(48時間)があります。点検は上限に達した便を閉じた時点で自動作成され、その期間の予約は別の機体の提案とともにキャンセルされます。残りはテクニカルログで確認できます。</p>\n<p><b>SimBrief。</b> <b>プロフィール</b>(名前の横)に SimBrief のユーザー名または Pilot ID を入力します。予約の「SimBrief から読み込む」で、最新プランの機体、ルート、時刻、時間、便名が取り込まれます。報告では、追跡が検証されるとブロックタイムが自動入力されます。</p>\n\n\n\n<p><b>イベント。</b> イベントタブには管理者が公開したグループフライトが並びます。「このイベントの機体を予約」をタップすると、出発空港にいる予定の機体が先に表示されます。</p>\n<p><b>通知。</b> 上部のベルは、予約が近づいたとき、予約した機体に新しい報告があったとき、整備で予約がキャンセルされたとき、閉じていない便があるとき、イベントやバッジについて知らせます。「この端末の通知」で、アプリを開いているときやバックグラウンドで表示されるシステム通知を有効にできます。</p>\n<p><b>キャリア。</b> ログブックにはランク(飛行時間に応じて訓練生からマスター機長まで)とバッジが表示されます。ランクは称号にすぎず、どのパイロットもどの機体でも飛ばせます。</p></section>\n\n<section id=\"m-mapa\"><h3>地図とフライトの詳細</h3>\n<p>地図は<b>進行中のあなたのフライト</b>を優先します。ない場合は、プロフィールにユーザー名/Pilot ID があれば最新の SimBrief ディスパッチを使います。承認済みのロスターは変わりません。別のディスパッチが進行中のフライトを置き換えることはありません。詳細なナブログがない場合、出発地から目的地への直線は参考であり、検証済みの航法ルートではありません。</p>\n<p>サイドバーには<b>追跡フライトのみ</b>が表示され、空港の統計や探索、RPL の出発便はありません。右上のレイヤー切り替えで、ベースマップ、トラフィック、管制官、オーバーレイを選べます。ブラジルの DECEA チャートには種類/シートと不透明度の調整があります。公式版を確認してください。</p>\n<p><b>機体にマウスを合わせてクリック</b>(携帯ではタップ)すると詳細が開きます。航空会社を特定できる場合、見出しにコールサインと航空会社アイコンが強調され、登録記号の色はその航空会社に合わせます。高度、対地速度(GS)、機首方位(HDG)、位置、出典などの情報は読みやすくまとめられます。長いポップアップはスクロールでき、欠けているデータが作られることはありません。</p>\n<p><b>追跡中の FlyVFR</b> のデータはシミュレーターから、<b>IVAO/VATSIM</b> は各ネットワークから、<b>ADS-B</b> は実機の観測から取得されます。予約時刻による推定は推定と明記され、テレメトリではありません。ADS-B は参考情報で、機体の利用可否、選択、ロスターは変わりません。</p></section>\n<section id=\"m-brief\"><h3>ブリーフィングルーム、ADC と NOTAM</h3>\n<p>ロスターの予約済みの便を選ぶと、METAR/TAF、NOTAM、航路の気象を確認できます。必要に応じて<b>代替空港</b>とその <b>ETA</b> を入力します。代替空港専用の ETA がない場合は目的地の ETA が使われ、その旨が表示されます。代替空港と ETA はパイロット/便ごとに端末に保存され、予約は変わりません。</p>\n<p>ADC では、選んだ便の<b>出発地、目的地、代替空港</b>だけが評価されます。出発地は EOBT、目的地と代替空港はそれぞれの ETA を使います。1つの空港が複数の役割を持つ場合は、それぞれの時刻が考慮されます。失効、将来、取消、差し替えの NOTAM は有効として強調されず、解釈できない時間帯は確認が必要です。</p>\n<p><b>ADC レイヤーは、飛行時刻に有効と確認された NOTAM と最新のデータがある場合にのみ利用できます。</b> そうでない場合、チャートは表示とレイヤーから外れます。これは空港に制限がないことを意味しません。「チャートを見る」ボタンは別にありません。空港の選択と地図のレイヤーを使ってください。</p>\n<ul><li><b>滑走路の全面閉鎖:</b> 明示的な文言、両端の滑走路番号の組、検証済みの形状がそろう場合のみ強調されます。</li><li><b>本文中の座標:</b> ADC 画像の外でも点として表示されます。明示的で有効かつ曖昧さのない直線の境界は破線の区域になることがあります。障害物の一覧は自動で結ばれません。</li><li><b>検証済みの参照:</b> 誘導路や設備のマーカーはチャート上の参照を示し、必ずしも正確な位置ではありません。停止線灯が使えなくても誘導路の閉鎖を意味しません。</li><li><b>一般的なお知らせ:</b> 正確な位置のない有効なお知らせは、明示された空港の参照マーカーにまとめられ、影響範囲を表すものではありません。</li><li><b>Q 行:</b> 中心と半径は参考情報で、滑走路・誘導路・設備の正確な位置でも、推定される制限範囲でもありません。</li></ul>\n<p>位置合わせされた ADC は、検証済みの公式チャートに依存します。チャートがない場合はその旨を表示し、位置合わせを作らずにお知らせを表示します。チャートのカタログはこのバージョンの静的な参考で、自動更新はありません。必ず公式の原本を確認してください。<b>シミュレーション専用です。</b></p><p><b>ブリーフィングルームのサブメニュー:</b> フライト、機体、追跡フライト、地図、気象、NOTAM、オンラインネットワーク、チャート、飛行計画、ブリーフィング・チェックリスト。それぞれブリーフィングのサイドバーに専用のアイコンがあります。</p>\n<ul><li><b>機体:</b> 登録記号と機種、<b>シミュレーター用塗装</b>(flightsim.to または x-plane.org のダウンロードリンク。プロフィールのシミュレーターで絞り込み)、テクニカルログ。</li>\n<li><b>追跡フライト:</b>「シミュレーターの接続方法」は同じページのフライト情報の下に開きます。</li>\n<li><b>チャート:</b>「この便の事前選択」でも、各チャートは種類ごとの色(ADC 青、SID 緑、STAR 紫、IAC マゼンタ…)を保ち、「その他の利用可能なチャート」と同じです。必要なものにチェックを入れ、<b>1つの PDF でダウンロード</b>を使います。</li></ul></section>\n<section id=\"m-redes\"><h3>IVAO と VATSIM</h3>\n<ol><li><b>プロフィール</b>を開き、必要に応じて <b>VATSIM CID</b>、<b>IVAO VID</b>、優先ネットワークを入力して保存します。</li><li>ブリーフィングの<b>オンラインネットワーク</b>パネルに、出発地・目的地・代替空港の該当するコールサイン、周波数、利用可能な ATIS が表示されます。局を展開して本文を読み、ネットワークで絞り込み、更新できます。</li><li>地図のレイヤーには、ネットワークごとの管制官と<b>一致した申告 ID</b> が表示されます。同じ地点の局はまとめられ、クリックで読めます。ID の一致は観測されたコールサインを強調します。</li></ol>\n<p>優先設定は初期選択を決めるもので、地図のレイヤーは別に変更できます。出典の UTC 時刻は<b>現在の状況</b>を示し、将来の管制の有無ではありません。欠けている、または古い出典は未確認とされ、ID が一致しないことは切断の証明になりません。拡張された APP/センターの範囲やセクター境界を、コールサインやマーカー位置から推定することはありません。</p>\n<p><b>ID は自己申告で、確認済みの本人情報ではありません。</b> これらの欄でネットワークにログインすることはありません。シミュレーターのネットワーククライアントを使ってください。ネットワークでの検出は報告の検証、時間の付与、アプリが求める追跡の代わりにはなりません。</p></section>\n\n<section id=\"m-diario\"><h3>ログブック、給与とカタログ</h3>\n<p><b>ログブック → マイログブック</b>には飛行時間が表示されます:合計、過去30日、今年、機種・航空会社・シミュレーター別の時間、よく飛ばした登録記号(航空会社の色、横に機種)、フライト一覧。表計算用に <b>CSV を書き出す</b>があります。時間は各報告のブロックタイムから計算されます。<b>給与</b>は架空の明細で、ランクと機体区分に応じた飛行時間あたりの金額に、宿泊の日当が加わります。金額は米ドルで設定され、選んだ通貨に<b>各フライト日の為替レート</b>で換算されます(レート欄)。<b>パイロットランキング</b>はグループを比較し(全期間、今年、30日)、エアライン・パイロットとフリーランスの2つのタブがあります。パイロットをタップするとそのログブックが見られます。<b>すべての記録</b>には、報告されたすべてのフライトが機体ごとの連番ページ(TL 0001…)、ルート、パイロット、シミュレーター、ブロックタイム、不具合とともに並びます。<b>不具合カタログ</b>には ATA 章別の標準不具合123件が、既定の処置、平均修理時間、MEL 期限、手順とともに収録されています。</p></section>\n\n<section id=\"m-apoie\"><h3>プロジェクトを支援</h3>\n<p>アプリは無料です。<b>サポート</b>タブから、Pix の QR コード、Pix のコピー&ペーストコード、その他の方法(カード、PayPal など)で、任意の金額を寄付できます。</p></section>\n\n<section id=\"m-faq\"><h3>よくある質問</h3>\n<div class=\"scroll\"><table><thead><tr><th>状況</th><th>対処</th></tr></thead><tbody>\n<tr><td>ログインできない</td><td>メールアドレスとパスワードを確認してください。忘れた場合は、ログイン画面の<b>パスワードをお忘れですか?</b>をタップすると、新しいパスワードを作成するリンクがメールで届きます</td></tr>\n<tr><td>予約が拒否された</td><td>赤いメッセージを読んでください:重複、整備、範囲外の時間、またはその登録記号の週間上限です</td></tr>\n<tr><td>希望の時間が表示されない</td><td>飛行時間+45分から飛行時間+2時間までだけが表示されます。出発と到着を確認してください</td></tr>\n<tr><td>「フライトを報告」ボタンがない</td><td>機体に未解決の項目があります。黄色の<b>テクニカルログを確認</b>ボタンをタップして署名してください</td></tr>\n<tr><td>ロスターをキャンセルしたい</td><td>承認したロスターはキャンセルできません。飛ばなかった便は 🔒 の日付に自動で解放されます</td></tr>\n<tr><td>予約が消えた</td><td>整備でキャンセルされた可能性があります。上部のお知らせを確認してください</td></tr>\n<tr><td>METAR が表示されない</td><td>小さな空港は METAR や TAF を発行しないことがあります。aviationweather.gov のリンクを使ってください</td></tr>\n<tr><td>新機能が表示されない</td><td>PC では <b>Ctrl+Shift+R</b> を押し、携帯ではアプリを閉じて開き直してください</td></tr>\n<tr><td>オフラインです</td><td>アプリは最後のデータで読み取り専用で開きます。予約と報告には接続が必要です</td></tr><tr><td>エアライン・パイロットからフリーランスに(またはその逆に)変えたい</td><td>ロスター/フリーフライトの<b>プロフィールを変更</b>を使います:30日に1回、予約中の便がない場合のみ</td></tr>\n<tr><td>フリーランスでフリートが空</td><td><b>機体を追加</b>で自分が飛ばす機体を(実際の登録記号で)登録するか、他のフリーランスが登録した機体を飛ばしてください</td></tr></tbody></table></div></section>\n"};
MANUAL.zh={fvUpdated:true,toc:[["m-ciclo","运作方式"],["m-inicio","入门"],["m-perfil","飞行员身份"],["m-escala","排班"],["m-livre","自由航班(自由飞行员)"],["m-reservar","航班计划"],["m-antes","飞行前"],["m-rastreio","追踪飞行"],["m-reporte","落地后"],["m-frota","机队"],["m-manut","自动维修"],["m-oper","真实运行"],["m-mapa","地图和航班详情"],["m-brief","简报、ADC 和 NOTAM"],["m-redes","IVAO 和 VATSIM"],["m-diario","日志、薪资和目录"],["m-apoie","支持"],["m-faq","常见问题"]],body:"\n<p class=\"muted manual-updated\">更新于 2026 年 10 月 30 日。</p>\n<section id=\"m-ciclo\"><h3>Virtual Flight Report 如何运作</h3>\n<p><b>每一次飞行都会留下记录。</b> Virtual Flight Report 是一本共享的技术记录本:每架飞机以注册号识别,每位在 MSFS 或 X-Plane 中驾驶它的飞行员都会记录它发生了什么。下一位飞行员拿到的飞机,正是上一位留下的状态。</p>\n<div class=\"cycle\"><span class=\"cy-step\">生成排班</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">查看技术记录本</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">在模拟器中飞行</span><span class=\"cy-arrow\">→</span><span class=\"cy-step strong\">报告航班</span></div>\n<div class=\"cycle out\"><span class=\"chip ok\">故障已排除:继续可用</span><span class=\"chip warn\">保留(MEL):带限制飞行</span><span class=\"chip bad\">停场:修复后放行</span></div>\n<p class=\"muted\">每个故障都带有其后果:根据所选故障,应用会自动决定飞机继续可用、带限制飞行还是停场,以及持续多久。</p></section>\n\n<section id=\"m-inicio\"><h3>入门</h3>\n<p>你需要一个飞行员账户,只需创建一次,所有设备通用。</p>\n<ol><li>打开 <b>flyvfr.com.br</b>,点击<b>登录</b>。</li><li>点击<b>新飞行员?创建账户</b>。</li><li>填写<b>飞行员名称</b>(他人可见的名字或呼号)、<b>电子邮箱</b>、<b>你使用的模拟器</b>以及至少 6 个字符的<b>密码</b>。以后要更改模拟器,点击名字旁的<b>个人资料</b>。</li><li>点击<b>创建账户</b>。以后使用<b>登录</b>。</li></ol>\n<p>登录后,如果你已有接受的排班,应用会打开<b>航班计划</b>;否则打开<b>排班</b>。菜单按飞行员一天的顺序排列:排班、简报室(接受排班后启用)、预订、机队、地图、活动、飞行日志、目录、手册和支持。</p>\n<div class=\"scroll\"><table><thead><tr><th>设备</th><th>安装方法</th></tr></thead><tbody>\n<tr><td>电脑(Chrome 或 Edge)</td><td>页面顶部的<b>安装应用</b>,或地址栏中的安装图标</td></tr>\n<tr><td>Android</td><td>在 Chrome 中:菜单 ⋮ → <b>安装应用</b>(或管理员分享的 <b>VirtualFlightReport.apk</b> 文件)</td></tr>\n<tr><td>iPhone 或 iPad(Safari)</td><td><b>分享</b> → <b>添加到主屏幕</b></td></tr></tbody></table></div>\n<p>在菜单的<b>设置</b>中,可以通过国旗选择语言(英语、葡萄牙语、西班牙语、法语、德语、日语、中文或韩语)、配色主题和菜单位置。<b>DAY MODE / NIGHT MODE</b> 按钮在浅色与深色页面间切换。你的选择保存在设备上。应用的改进会自动到达电脑和手机,无需重新安装。要退出,点击名字旁的<b>退出</b>。</p><p><b>飞行员身份。</b> 注册时选择你的飞行方式:<b>航空公司飞行员</b>或<b>自由飞行员</b>。已有账户的飞行员在下次登录时选择。参见<a href=\"#m-perfil\" data-action=\"man-jump\" data-to=\"m-perfil\">飞行员身份</a>。</p></section>\n<section id=\"m-perfil\"><h3>飞行员身份:航空公司还是自由飞行员</h3>\n<div class=\"scroll\"><table><thead><tr><th></th><th>✈ 航空公司飞行员</th><th>🛩 自由飞行员</th></tr></thead><tbody>\n<tr><td>驾驶的机队</td><td>仅航空公司机队</td><td>仅自由飞行员机队:自己登记的飞机及其他自由飞行员登记的飞机</td></tr>\n<tr><td>预订方式</td><td><b>排班</b>:由应用生成的 RPL 航班或自由排班</td><td><b>自由航班</b>:飞行员自行安排的一段或连续多段</td></tr>\n<tr><td>航空公司</td><td>任意航空公司,但需完成上一次排班之后</td><td>—</td></tr>\n<tr><td>排行榜</td><td><b>航空公司飞行员</b>标签</td><td><b>自由飞行员</b>标签</td></tr></tbody></table></div>\n<ul><li><b>更改身份:</b> 点击排班(或自由航班)顶部的<b>更改身份</b>。<b>每 30 天一次</b>,且仅在<b>没有已预订航班</b>时可更改。屏幕会显示下次可更改的日期。</li>\n<li><b>共享的自由飞行员机队:</b> 登记飞机时,自由飞行员需确认其他自由飞行员可以驾驶这架飞机,自己也可以驾驶他们的飞机。位置和技术记录本对所有人相同:下一班从上一班落地的机场出发。</li>\n<li><b>注册号唯一:</b> 机队中已存在的注册号不能再次登记。</li>\n<li>飞行日志的排行榜有两个标签;每次飞行计入所用飞机所属机队的标签。</li></ul></section>\n\n<section id=\"m-escala\"><h3>航班排班</h3>\n<p><b>排班</b>菜单提供两种模式:</p>\n<ul><li><b>自由:</b> 自行选择出发机场、航空公司和飞机,不依赖 RPL 出发航班。</li><li><b>RPL 航班:</b> 查看<b>从现在起 30 至 90 分钟</b>内的出发航班。RPL 涵盖巴西国内航班以及往返巴西的国际航班。选择航班后,选一架该航空公司、机型与 RPL 匹配的合格飞机。</li><li><b>没有合格的 RPL:</b> 如果没有带合格飞机的航班,或该机场没有 RPL,则可自由选择航空公司和飞机。</li><li><b>收藏:</b> 两种模式下,收藏的飞机在选择航空公司和飞机时优先。</li></ul>\n<p>设置首个出发时间、1 至 4 天的时长以及每天的航班数。每段从上一段结束的地方开始。生成器会考虑地面、值勤和休息时间;接受前请检查顺序。</p>\n<p>接受前可以生成新的方案。点击<b>接受排班</b>确认航班:<b>接受后的排班不能修改</b>。接受后,每个航班的简报以及 SimBrief 和 SkyVector 按钮即可使用。</p>\n<p><b>ADS-B 仅供参考。</b> 地面飞机信息会标明来源和更新时间。它不会改变飞机的可用性、选择、应用中的运行位置或排班;真实飞机的存在不会决定生成的航班。</p>\n<p>在<b>航班计划</b>中查看每个航班的卡片和通知。已完成或已取消的航班不会重新打开排班运行表。</p><p><b>延误(DLA)和未到场:</b> EOBT(预计撤轮挡时间)显示在“你的航班计划”的航班卡片上。如果要延误,点击<b>延误(DLA)</b>并选择新的 EOBT:<b>每个航班一次 DLA</b>,须在<b>计划 EOBT 后 35 分钟内</b>提交,新的 EOBT <b>不晚于提交 DLA 时刻后 45 分钟</b>。同一值勤期内的后续航班顺延相同时间。顺延在过夜休息处停止,下一值勤期的时间保持不变。如果在<b>有效 EOBT 后 45 分钟内</b>未开始追踪飞行,航班将被取消,并在预订中显示通知。EOBT 过后,卡片以红色显示截止时间。</p></section>\n<section id=\"m-livre\"><h3>自由航班(自由飞行员)</h3>\n<p>对自由飞行员,<b>排班</b>菜单变为<b>自由航班</b>。不生成排班:由你自己安排航班。</p>\n<ol><li>从自由飞行员机队中选择<b>飞机</b>(列表显示“我的”或登记人,以及所在位置)。</li>\n<li><b>第一段的出发地</b>是飞机届时所在的机场;如果它从未飞过,由你选择出发地。</li>\n<li>填写<b>目的地</b>和<b>起飞时间</b>(至少从现在起 30 分钟后)。应用会计算距离、轮挡时间和到达时间,并检查飞机航程。</li>\n<li>要继续行程,点击<b>＋ 添加航段</b>:下一段从上一段落地的机场出发,建议起飞时间为到达后 1 小时(到达与下次起飞之间至少 45 分钟)。点击 ✕ 删除航段。最多 24 段。</li>\n<li>航班号按顺序建议,可以修改。点击<b>预订自由航班</b>(或<b>预订 N 个自由航班</b>)。</li></ol>\n<p>预订后,一切与排班相同:航班计划、简报室、追踪飞行以及落地后的报告。</p></section>\n\n<section id=\"m-reservar\"><h3>你的航班计划</h3>\n<p><b>航班计划</b>标签以<b>你的航班计划</b>开始:你的每个航班一张卡片,显示飞机照片、航空公司配色的注册号、航班号和航路、日期和时间(当地和 UTC)以及航空公司。</p>\n<div class=\"scroll\"><table><thead><tr><th>卡片上</th><th>含义</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">✓ 记录本中没有未关闭项目</span></td><td>闪烁一次作为提示。无需签字:<b>追踪飞行</b>和<b>报告航班</b>已可使用</td></tr>\n<tr><td><span class=\"chip warn\">⚠ 查看技术记录本</span></td><td>持续闪烁:飞机有未关闭项目。点击它,阅读项目并签字(参见<b>飞行前</b>)</td></tr>\n<tr><td><span class=\"chip ok\">✓ 技术记录本已查看</span></td><td>你已签字,可以飞行</td></tr></tbody></table></div>\n<ul><li><b>SimBrief</b> 和 <b>SkyVector</b>:右侧带有各网站图标的按钮,打开对应航班的计划。SimBrief 还会收到飞机识别信息和 EOBT;SkyVector 会收到航路和巡航估算。</li><li><b>METAR 和 TAF:</b> 将鼠标移到机场代码上(手机上点击)。点击<b>解码</b>以通俗语言阅读报文(风、能见度、云、温度、气压以及 TAF 的每个时段);<b>原文</b>重新显示原始文本。应用会记住你的选择。</li></ul>\n<p>排班的预订在接受时创建。使用航班卡片查看技术记录本、追踪并报告航班。管理和活动操作取决于账户可用的选项。</p></section>\n\n<section id=\"m-antes\"><h3>飞行前</h3>\n<p>飞行前,查看航班卡片上的技术记录本按钮:</p>\n<ul><li><b>没有未关闭项目</b>(绿色):无需签字。直接点击<b>追踪飞行</b>或<b>报告航班</b>。</li><li><b>有未关闭项目</b>(黄色闪烁):点击<b>查看技术记录本</b>,阅读未关闭项目和最新报告,勾选确认并点击<b>签署技术记录本</b>。按钮变为绿色并显示<b>技术记录本已查看</b>。没有这个签字,追踪和报告都不会被接受。</li><li>如果在你签字后有其他飞行员报告了该注册号的故障,黄色按钮会再次出现,你需要重新签字。</li></ul>\n<p>故障不会在模拟器之间传递,因此每个保留项目都附有<b>给下一机组的程序</b>,你在飞行中遵照执行。例如:<i>APU 无法启动</i> → 在地面申请 GPU 和外部气源。</p></section>\n\n<section id=\"m-rastreio\"><h3>追踪飞行</h3>\n<p><b>经验证的追踪</b>是记录航班并计入飞行小时、等级、薪资和排行榜的正常方式。应用读取模拟器遥测数据,服务器检查航迹。没有经验证的追踪时,如可用请申请审核:由管理员决定,批准前不会完成航班,也没有奖励。</p>\n<ol><li>在<b>你的航班计划</b>的航班卡片上点击 <b>✈ 追踪飞行</b>(预订时间前 1 小时起可用;如有未关闭项目,请先签署技术记录本)。</li>\n<li>飞机停在出发登机口时,点击<b>连接模拟器</b>。<ul>\n<li><b>MSFS 2020/2024:</b> 安装 <a href=\"https://fsuipc.com\" target=\"_blank\" rel=\"noopener\">FSUIPC7</a>(免费版即可)和 <a href=\"http://fsuipcwebsockets.paulhenty.com/\" target=\"_blank\" rel=\"noopener\">FSUIPC WebSocket Server</a>,并与模拟器一起保持打开。</li>\n\n<li><b>X-Plane 12</b>(12.1.4 或更新):无需安装。</li>\n<li><b>X-Plane 11:</b> XPUIPC 插件 + FSUIPC WebSocket Server。</li>\n<li>在运行模拟器的同一台电脑上使用 Chrome 或 Edge。如果浏览器请求访问本地网络,请允许。</li></ul></li>\n<li>正常飞行并保持标签页打开。<b>实时飞行</b>屏幕显示阶段、高度、速度、垂直速度和到目的地的距离;期间你可以使用其他屏幕。</li>\n<li>落地后,停好并让飞机停止。点击<b>结束飞行</b>:服务器检查航迹并显示结果。然后填写报告(故障和备注);轮挡时间和到达机场来自追踪数据。</li></ol>\n<p>以下情况服务器会拒绝该航班:不在出发机场的地面上开始 · 未在机场停止结束 · 使用时间加速或 slew · 飞机位置跳变(瞬移或在地图上移动)· 空中追踪中断超过 10 分钟 · 航迹未实时到达服务器 · 空中飞行不足 5 分钟。允许暂停:暂停时间会被扣除。接受备降:飞机留在落地的地方。</p></section>\n\n<section id=\"m-reporte\"><h3>落地后:报告航班</h3>\n<ol><li>点击<b>报告航班</b>。</li><li>选择<b>模拟器</b>(只列出你的模拟器;其他的请选<b>其他模拟器…</b>)并填写<b>轮挡时间</b>(h:mm,例如 <code>1:45</code>)。</li><li>每个故障点击一次<b>添加故障</b>;如果没有发生任何事,就不要添加。</li><li>点击<b>提交报告并关闭预订</b>。</li></ol>\n<p>故障栏显示<b>航空公司机组最常报告的故障</b>。开始输入后列表会缩小:它能理解多种语言、忽略重音,并认识 <code>brake</code>、<code>door</code>、<code>APU</code>、<code>ata 32</code> 或 <code>ECAM</code> 等术语。如果目录中没有,选择<b>不在列表中:描述它</b>。</p>\n<p>飞行员不选择处理方式和时长:它们由目录中所选的故障决定。对于目录外的故障,应用使用所填 ATA 章节最常见的默认值。</p><div class=\"scroll\"><table><thead><tr><th>后果</th><th>对飞机的影响</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">机组已排除</span></td><td>无;仅保留在历史中</td></tr>\n<tr><td><span class=\"chip warn\">保留(MEL)</span></td><td>在期限内带限制飞行(B 类 3 天、C 类 10 天、D 类 120 天);之后停场,时长为修复时间</td></tr>\n<tr><td><span class=\"chip bad\">飞机停场</span></td><td>自报告起在平均修复时间内不可用</td></tr></tbody></table></div></section>\n\n<section id=\"m-frota\"><h3>机队</h3>\n<p><b>机队</b>标签显示每个注册号的状态。顶部的<b>合计随筛选变化</b>:所选飞机数、当前可用、正在飞行、未来 24 小时内已预订,以及受限或停场。</p>\n<ul><li><b>一行筛选:</b> 地区、航空公司、机型、状态和<b>排序</b>(最近飞行、飞行最多、可用优先或注册号),以及按注册号、机型或机场(例如 <code>SBGR</code>)搜索和<b>收藏</b>按钮。</li>\n<li><b>按机型分组:</b> 每组显示飞机数量和可用数量。</li>\n<li><b>每架飞机一行:</b> 注册号、机型、<b>所在位置</b>、<b>上次飞行</b>(例如“SBGR → SBSV · 2 d前”)或下一事件、<b>历史</b>(在 VFR 的航班数和小时数)以及状态。可用的飞机只显示一个绿点;彩色标签标示例外情况。</li>\n<li><b>窄窗口</b>(半屏):行会换成两行,确保内容不被截断。手机上机队以卡片显示。</li>\n<li><b>更多飞机:</b> 点击列表底部的<b>显示更多</b>。<b>登记:</b><b>添加飞机</b>。</li></ul>\n<div class=\"scroll\"><table><thead><tr><th>状态</th><th>含义</th><th>能否飞行?</th></tr></thead><tbody>\n<tr><td><span class=\"fv-ok\">可用</span></td><td>没有未关闭项目,且未来 24 小时内未被使用</td><td>能</td></tr>\n<tr><td><span class=\"pill fv-fly\">飞行中</span></td><td>目前有飞行员在使用;该行显示到达时间</td><td>到达后,从目的地出发</td></tr>\n<tr><td><span class=\"pill fv-res\">已预订</span></td><td>未来 24 小时内有预订(时间显示在标签上)</td><td>预订时间之外</td></tr>\n<tr><td><span class=\"pill warn\">受限</span></td><td>保留项目(MEL);按程序飞行</td><td>能,模拟该限制</td></tr>\n<tr><td><span class=\"pill bad\">AOG</span></td><td>因维修停场;该行显示恢复时间</td><td>放行后才能</td></tr>\n<tr><td><span class=\"pill fv-new\">无记录</span></td><td>从未在 VFR 飞行;首个航班选择出发地</td><td>能</td></tr></tbody></table></div>\n<p>点击一行打开<b>技术记录本</b>:照片、摘要(所在位置、何时可用、下次预订和上次飞行员)、未关闭项目和程序、计划维修、模拟器涂装、机体小时、循环以及所有飞行页。自由飞行员只看到自由飞行员机队;航空公司飞行员只看到航空公司机队。</p></section>\n\n<section id=\"m-manut\"><h3>自动维修</h3>\n<ul><li>修复时间结束后,飞机会自动恢复为<b>可用</b>。</li><li>时间从报告时起按真实小时计算;重叠的停场时间会累加。</li><li>过期的 MEL 项目会使飞机停场,时长为该项目的修复时间。</li><li>新停场期间内的预订会被取消,并在应用顶部显示通知;之后的预订保留。受影响的飞行员会获得同一时间空闲的<b>同型号或同系列</b>飞机(例如 A320 系列、737 NG/MAX、E-Jets);点一下即可打开预填相同航路、时间和时长的预订。</li></ul></section>\n\n<section id=\"m-oper\"><h3>真实运行</h3>\n<p><b>飞机在应用中的位置。</b> 飞行历史和系统预订与 ADS-B 观测相互独立。请查看航班通知和技术记录本;ADS-B 数据不会改变飞机位置,也不要求调机。</p>\n\n<p><b>备降。</b> 实际到达必须反映实际执行的飞行以及追踪/报告数据。请查看受影响预订的通知;不要把模拟中的备降与 ADS-B 观测混淆。</p>\n<p><b>定期检查。</b> 每 120 飞行小时或 100 个循环,飞机进行一次 A 检(地面 8 小时);每 1,200 小时进行一次 C 检(48 小时)。在达到上限的航班关闭时自动创建检查,该期间的预订会被取消并提供其他飞机。技术记录本显示剩余量。</p>\n<p><b>SimBrief。</b> 在<b>个人资料</b>(名字旁)填写你的 SimBrief 用户名或 Pilot ID。这样预订中的“从 SimBrief 导入”会带入你最新计划中的飞机、航路、时间、时长和航班号。在报告中,追踪经验证时轮挡时间会自动填写。</p>\n\n\n\n<p><b>活动。</b> 活动标签列出管理员发布的集体飞行。点击“为此活动预订飞机”:届时位于出发机场的飞机排在最前。</p>\n<p><b>通知。</b> 顶部的铃铛会在你的预订临近、所订飞机收到新报告、预订因维修被取消、航班仍需关闭时提醒你,也会提示活动和徽章。在“此设备上的通知”中可以开启系统通知,在应用打开或后台运行时显示。</p>\n<p><b>职业。</b> 飞行日志显示你的等级(按飞行小时从学员到资深机长)和徽章。等级仅为荣誉:任何飞行员都可以驾驶任何飞机。</p></section>\n\n<section id=\"m-mapa\"><h3>地图和航班详情</h3>\n<p>地图优先显示<b>你正在进行的航班</b>。如果没有,当个人资料中填写了用户名/Pilot ID 时,会使用最新可用的 SimBrief 签派。这不会改变已接受的排班。其他签派不会替代正在进行的航班。没有详细领航日志数据时,出发地到目的地的直线只是参考,不是经验证的导航航路。</p>\n<p>侧栏<b>只包含追踪航班</b>,不含机场统计、机场浏览或 RPL 出发航班。右上角的图层控件提供底图、交通、管制员和叠加层。巴西 DECEA 航图有类型/图幅和透明度控制;请查阅官方版本。</p>\n<p><b>将鼠标移到飞机上并点击</b>(手机上点击)即可打开详情。能识别航空公司时,标题会突出显示呼号和航空公司图标;注册号颜色跟随识别出的航空公司。高度、地速(GS)、航向(HDG)、位置、来源及其他可用信息分组显示,便于阅读。较长的弹窗可以滚动;缺失的数据不会被编造。</p>\n<p><b>追踪中的 FlyVFR</b> 数据来自模拟器,<b>IVAO/VATSIM</b> 来自其网络,<b>ADS-B</b> 来自真实飞机的观测。基于预订时间的估算会明确标注为估算,而非遥测。ADS-B 仅供参考,不会改变飞机的可用性、选择或排班。</p></section>\n<section id=\"m-brief\"><h3>简报室、ADC 和 NOTAM</h3>\n<p>选择排班中已预订的航班,查看 METAR/TAF、NOTAM 和航路天气。需要时填写<b>备降场</b>及其 <b>ETA</b>。没有备降场专用 ETA 时,会使用并标注目的地 ETA。备降场及其 ETA 按飞行员/航班保存在设备上,不会改变预订。</p>\n<p>在 ADC 上只评估所选航班的<b>出发地、目的地和备降场</b>。出发地使用 EOBT;目的地和备降场使用各自的 ETA。一个机场承担多个角色时,会考虑相应的时间。过期、未来、已取消或已替代的 NOTAM 不会作为有效项突出显示;无法解析的时间安排需要确认。</p>\n<p><b>只有在飞行时间有经确认的有效 NOTAM 且数据较新时,ADC 图层才可用。</b> 否则航图会从显示和图层中移除。这并不表示机场没有限制。没有单独的“查看航图”按钮:请使用机场选择器和地图图层。</p>\n<ul><li><b>跑道完全关闭:</b> 只有在文本明确、跑道两端编号完整且几何已验证时才会突出显示。</li><li><b>文本中的坐标:</b> 以点显示,包括 ADC 图像之外。明确、有效且无歧义的直线边界可显示为虚线区域;障碍物列表不会自动连接。</li><li><b>已验证的参考:</b> 滑行道或设备标记表示航图上的参考,不一定是确切位置。停止排灯不可用并不表示滑行道关闭。</li><li><b>一般通告:</b> 没有精确位置的有效通告集中在明确标示的机场参考标记处,它不代表受影响区域。</li><li><b>Q 行:</b> 中心和半径是参考信息,不是跑道、滑行道或设备的确切位置,也不是推定的限制范围。</li></ul>\n<p>地理配准的 ADC 依赖经验证的官方航图。缺少航图时会注明;通告仍然可用,不会编造配准。航图目录是本版本的静态参考,不会自动更新。请始终查阅官方原件。<b>仅供模拟使用。</b></p><p><b>简报室子菜单:</b> 航班、飞机、追踪飞行、地图、气象、NOTAM、在线网络、航图、飞行计划和简报检查单,每项在简报侧栏中都有各自的图标。</p>\n<ul><li><b>飞机:</b> 注册号和机型、<b>模拟器涂装</b>(flightsim.to 或 x-plane.org 的下载链接,按个人资料中的模拟器筛选)以及技术记录本。</li>\n<li><b>追踪飞行:</b>“如何连接你的模拟器”在同一页面、航班数据下方展开。</li>\n<li><b>航图:</b> 在“本航班预选”中,每张航图保留其类型的颜色(ADC 蓝、SID 绿、STAR 紫、IAC 品红…),与“其他可用航图”中一致。勾选需要的航图,然后使用<b>下载为一个 PDF</b>。</li></ul></section>\n<section id=\"m-redes\"><h3>IVAO 和 VATSIM</h3>\n<ol><li>打开<b>个人资料</b>,可选填你的 <b>VATSIM CID</b>、<b>IVAO VID</b> 和首选网络,然后保存。</li><li>简报中的<b>在线网络</b>面板显示出发地、目的地和备降场匹配的呼号、频率和可用的 ATIS。展开某个电台可阅读其文本,也可按网络筛选或刷新。</li><li>地图图层显示每个网络的管制员和<b>匹配的申报 ID</b>。同一位置的电台会被归组;点击即可阅读。ID 匹配会突出显示观测到的呼号。</li></ol>\n<p>首选项决定初始选择;地图图层可单独更改。来源的 UTC 时间描述的是<b>当前状态</b>,而不是未来的管制服务。缺失或过时的来源视为未确认,ID 不匹配也不能证明已断开。不会根据呼号或标记位置推断扩展的进近/区域管制范围或扇区边界。</p>\n<p><b>ID 为自行申报,并非经验证的身份。</b> 这些字段不会登录网络:请使用模拟器的网络客户端。网络检测不会验证报告、授予小时数,也不能替代应用要求的追踪。</p></section>\n\n<section id=\"m-diario\"><h3>飞行日志、薪资和目录</h3>\n<p><b>飞行日志 → 我的日志</b>显示你的飞行小时:总计、最近 30 天、今年,按机型、航空公司和模拟器统计的小时数,飞得最多的注册号(航空公司配色,旁边注明机型)以及航班列表,并可<b>导出 CSV</b> 用于电子表格。小时数来自每份报告的轮挡时间。<b>薪资</b>是一份虚构工资单:按等级和飞机类别计算每飞行小时薪酬,另加过夜津贴。金额以美元设定,并按<b>每个航班当日的汇率</b>换算为所选货币(汇率列)。<b>飞行员排行榜</b>比较群体(全部时间、今年或 30 天),有航空公司飞行员和自由飞行员两个标签;点击某位飞行员可查看其日志。<b>全部记录</b>列出每个已报告的航班,包括每架飞机的连续页码(TL 0001…)、航路、飞行员、模拟器、轮挡时间和故障。<b>故障目录</b>收录按 ATA 章节划分的 123 个标准故障,附默认处理、平均修复时间、MEL 期限和程序。</p></section>\n\n<section id=\"m-apoie\"><h3>支持本项目</h3>\n<p>本应用免费。在<b>支持</b>标签中,你可以通过 Pix 二维码、Pix 复制粘贴码或列出的其他方式(银行卡、PayPal 等)捐赠任意金额。</p></section>\n\n<section id=\"m-faq\"><h3>常见问题</h3>\n<div class=\"scroll\"><table><thead><tr><th>情况</th><th>怎么办</th></tr></thead><tbody>\n<tr><td>无法登录</td><td>检查邮箱和密码。如果忘记密码,在登录页点击<b>忘记密码?</b>:你会收到一封邮件链接来创建新密码</td></tr>\n<tr><td>预订被拒绝</td><td>阅读红色提示:时间重叠、维修、时长超出范围或该注册号的每周上限</td></tr>\n<tr><td>没有我想要的时长</td><td>只显示从航程 + 45 分钟到航程 + 2 小时的时长;请检查出发和到达</td></tr>\n<tr><td>没有“报告航班”按钮</td><td>飞机有未关闭项目:点击黄色的<b>查看技术记录本</b>按钮并签字</td></tr>\n<tr><td>我想取消排班</td><td>已接受的排班不能取消;未飞的航班会在 🔒 日期自动释放</td></tr>\n<tr><td>我的预订不见了</td><td>可能因维修被取消;请查看顶部的通知</td></tr>\n<tr><td>没有显示 METAR</td><td>小机场可能不发布 METAR 或 TAF;请使用 aviationweather.gov 链接</td></tr>\n<tr><td>看不到应用的新功能</td><td>电脑上按 <b>Ctrl+Shift+R</b>;手机上关闭并重新打开应用</td></tr>\n<tr><td>我处于离线状态</td><td>应用会以最后的数据只读打开;预订和报告需要联网</td></tr><tr><td>我想从航空公司飞行员改为自由飞行员(或反之)</td><td>在排班/自由航班中使用<b>更改身份</b>:每 30 天一次,且没有已预订航班</td></tr>\n<tr><td>我是自由飞行员,但机队是空的</td><td>通过<b>添加飞机</b>登记你驾驶的飞机(使用真实注册号),或驾驶其他自由飞行员已登记的飞机</td></tr></tbody></table></div></section>\n"};
MANUAL.ko={fvUpdated:true,toc:[["m-ciclo","작동 방식"],["m-inicio","시작하기"],["m-perfil","조종사 프로필"],["m-escala","스케줄"],["m-livre","자유 비행(프리랜서)"],["m-reservar","일정"],["m-antes","비행 전"],["m-rastreio","추적 비행"],["m-reporte","착륙 후"],["m-frota","기단"],["m-manut","자동 정비"],["m-oper","실감 나는 운항"],["m-mapa","지도와 비행 상세"],["m-brief","브리핑, ADC, NOTAM"],["m-redes","IVAO와 VATSIM"],["m-diario","일지, 급여, 카탈로그"],["m-apoie","후원"],["m-faq","자주 묻는 질문"]],body:"\n<p class=\"muted manual-updated\">2026년 10월 30일 업데이트.</p>\n<section id=\"m-ciclo\"><h3>Virtual Flight Report 작동 방식</h3>\n<p><b>모든 비행은 흔적을 남깁니다.</b> Virtual Flight Report는 공유 기술 일지입니다. 각 항공기는 등록 번호로 식별되며, MSFS나 X-Plane에서 그 항공기를 비행한 모든 조종사가 무슨 일이 있었는지 기록합니다. 다음 조종사는 이전 조종사가 남긴 그대로의 항공기를 받습니다.</p>\n<div class=\"cycle\"><span class=\"cy-step\">스케줄 생성</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">기술 일지 확인</span><span class=\"cy-arrow\">→</span><span class=\"cy-step\">시뮬레이터에서 비행</span><span class=\"cy-arrow\">→</span><span class=\"cy-step strong\">비행 보고</span></div>\n<div class=\"cycle out\"><span class=\"chip ok\">결함 해결: 계속 이용 가능</span><span class=\"chip warn\">이월(MEL): 제한 비행</span><span class=\"chip bad\">지상 대기: 수리 후 해제</span></div>\n<p class=\"muted\">결함마다 결과가 정해져 있습니다. 선택한 결함에 따라 항공기가 계속 이용 가능한지, 제한 비행인지, 지상 대기인지, 그리고 얼마 동안인지 앱이 스스로 결정합니다.</p></section>\n\n<section id=\"m-inicio\"><h3>시작하기</h3>\n<p>조종사 계정은 한 번만 만들면 모든 기기에서 사용할 수 있습니다.</p>\n<ol><li><b>flyvfr.com.br</b>을 열고 <b>로그인</b>을 누릅니다.</li><li><b>새 조종사인가요? 계정 만들기</b>를 누릅니다.</li><li><b>조종사 이름</b>(다른 사람에게 보이는 이름이나 호출부호), <b>이메일</b>, <b>사용하는 시뮬레이터</b>, 6자 이상의 <b>비밀번호</b>를 입력합니다. 나중에 시뮬레이터를 바꾸려면 이름 옆의 <b>프로필</b>을 누릅니다.</li><li><b>계정 만들기</b>를 누릅니다. 다음부터는 <b>로그인</b>을 사용합니다.</li></ol>\n<p>로그인하면 승인된 스케줄이 있을 때는 <b>일정</b>이, 없으면 <b>스케줄</b>이 열립니다. 메뉴는 조종사의 하루 흐름을 따릅니다: 스케줄, 브리핑룸(승인된 스케줄이 있을 때 활성화), 예약, 기단, 지도, 이벤트, 비행 일지, 카탈로그, 매뉴얼, 후원.</p>\n<div class=\"scroll\"><table><thead><tr><th>기기</th><th>설치 방법</th></tr></thead><tbody>\n<tr><td>PC(Chrome 또는 Edge)</td><td>페이지 상단의 <b>앱 설치</b> 또는 주소창의 설치 아이콘</td></tr>\n<tr><td>Android</td><td>Chrome 메뉴 ⋮ → <b>앱 설치</b>(관리자가 공유한 경우 <b>VirtualFlightReport.apk</b> 파일)</td></tr>\n<tr><td>iPhone 또는 iPad(Safari)</td><td><b>공유</b> → <b>홈 화면에 추가</b></td></tr></tbody></table></div>\n<p>메뉴의 <b>설정</b>에서 국기로 언어(영어, 포르투갈어, 스페인어, 프랑스어, 독일어, 일본어, 중국어, 한국어), 색상 테마, 메뉴 위치를 고릅니다. <b>DAY MODE / NIGHT MODE</b> 버튼으로 밝은 화면과 어두운 화면을 전환합니다. 선택은 기기에 저장됩니다. 앱 개선 사항은 재설치 없이 PC와 휴대폰에 자동으로 적용됩니다. 로그아웃하려면 이름 옆의 <b>로그아웃</b>을 누릅니다.</p><p><b>조종사 프로필.</b> 가입할 때 비행 방식을 고릅니다: <b>항공사 조종사</b> 또는 <b>프리랜서</b>. 기존 조종사는 다음 로그인 때 고릅니다. <a href=\"#m-perfil\" data-action=\"man-jump\" data-to=\"m-perfil\">조종사 프로필</a>을 참고하세요.</p></section>\n<section id=\"m-perfil\"><h3>조종사 프로필: 항공사 또는 프리랜서</h3>\n<div class=\"scroll\"><table><thead><tr><th></th><th>✈ 항공사 조종사</th><th>🛩 프리랜서</th></tr></thead><tbody>\n<tr><td>비행하는 기단</td><td>항공사 기단만</td><td>프리랜서 기단만: 본인이 등록한 항공기와 다른 프리랜서가 등록한 항공기</td></tr>\n<tr><td>예약 방법</td><td><b>스케줄</b>: 앱이 생성하는 RPL 편 또는 자유 스케줄</td><td><b>자유 비행</b>: 조종사가 직접 구성하는 한 구간 또는 연속 구간</td></tr>\n<tr><td>항공사</td><td>어느 항공사든 가능, 단 마지막 스케줄을 마친 후</td><td>—</td></tr>\n<tr><td>랭킹</td><td><b>항공사 조종사</b> 탭</td><td><b>프리랜서</b> 탭</td></tr></tbody></table></div>\n<ul><li><b>프로필 변경:</b> 스케줄(또는 자유 비행) 상단의 <b>프로필 변경</b>을 누릅니다. <b>30일에 한 번</b>, 그리고 <b>예약된 비행이 없을 때만</b> 바꿀 수 있습니다. 화면에 다음 변경 가능 날짜가 표시됩니다.</li>\n<li><b>공유되는 프리랜서 기단:</b> 항공기를 등록할 때 프리랜서는 다른 프리랜서가 그 항공기를 비행할 수 있고 자신도 그들의 항공기를 비행할 수 있음을 확인합니다. 위치와 기술 일지는 모두에게 같습니다. 다음 비행은 마지막 비행이 착륙한 곳에서 출발합니다.</li>\n<li><b>등록 번호는 하나뿐:</b> 이미 기단에 있는 등록 번호는 다시 등록할 수 없습니다.</li>\n<li>비행 일지의 랭킹에는 두 개의 탭이 있으며, 각 비행은 사용한 항공기의 기단 탭에 집계됩니다.</li></ul></section>\n\n<section id=\"m-escala\"><h3>비행 스케줄</h3>\n<p><b>스케줄</b> 메뉴에는 두 가지 모드가 있습니다:</p>\n<ul><li><b>자유:</b> RPL 출발편과 관계없이 출발 공항, 항공사, 항공기를 고릅니다.</li><li><b>RPL 편:</b> <b>지금부터 30~90분 사이</b>의 출발편을 봅니다. RPL은 브라질 국내선과 브라질 출발·도착 국제선을 포함합니다. 편을 고른 뒤 해당 항공사에서 RPL에 맞는 기종의 적격 항공기를 선택합니다.</li><li><b>적격 RPL이 없을 때:</b> 적격 항공기가 있는 편이 없거나 공항에 RPL이 없으면 항공사와 항공기를 자유롭게 고를 수 있습니다.</li><li><b>즐겨찾기:</b> 두 모드 모두에서 즐겨찾기한 항공기가 항공사와 항공기 선택에서 우선합니다.</li></ul>\n<p>첫 출발, 1~4일의 기간, 하루 비행 수를 정합니다. 각 구간은 이전 구간이 끝난 곳에서 시작합니다. 생성기는 지상·근무·휴식 시간을 고려합니다. 승인 전에 순서를 확인하세요.</p>\n<p>승인 전에는 새 안을 만들 수 있습니다. <b>스케줄 승인</b>을 눌러 비행을 확정합니다: <b>승인한 스케줄은 바꿀 수 없습니다</b>. 승인하면 각 비행의 브리핑과 SimBrief·SkyVector 버튼을 쓸 수 있습니다.</p>\n<p><b>ADS-B는 참고용입니다.</b> 지상 항공기 정보에는 출처와 업데이트 시각이 표시됩니다. 항공기 이용 가능 여부, 선택, 앱 내 운항 위치, 스케줄은 바뀌지 않습니다. 실제 항공기의 존재가 생성되는 비행을 정하지 않습니다.</p>\n<p>각 비행의 카드와 알림은 <b>일정</b>에서 확인합니다. 완료되거나 취소된 비행은 스케줄 운항표를 다시 열지 않습니다.</p><p><b>지연(DLA)과 미출석:</b> EOBT(예상 오프블록 시각)는 내 일정의 비행 카드에 표시됩니다. 늦을 것 같으면 <b>지연(DLA)</b>을 누르고 새 EOBT를 고릅니다: <b>비행당 DLA 1회</b>, <b>예정 EOBT 후 35분 이내</b>에 제출하며 새 EOBT는 <b>DLA 제출 시점부터 45분 이내</b>입니다. 같은 근무의 후속 비행도 같은 시간만큼 늦춰집니다. 지연 전파는 야간 휴식에서 멈추며 다음 근무의 시각은 유지됩니다. <b>유효 EOBT 후 45분 이내</b>에 추적 비행을 시작하지 않으면 비행이 취소되고 예약에 알림이 표시됩니다. EOBT가 지나면 카드에 마감 시각이 빨간색으로 표시됩니다.</p></section>\n<section id=\"m-livre\"><h3>자유 비행(프리랜서)</h3>\n<p>프리랜서에게는 <b>스케줄</b> 메뉴가 <b>자유 비행</b>이 됩니다. 스케줄 생성은 없고, 직접 비행을 구성합니다.</p>\n<ol><li>프리랜서 기단에서 <b>항공기</b>를 고릅니다(목록에 “내 항공기” 또는 등록자와 현재 위치가 표시됩니다).</li>\n<li><b>첫 구간의 출발지</b>는 항공기가 있을 곳입니다. 한 번도 비행하지 않았다면 출발지를 직접 고릅니다.</li>\n<li><b>목적지</b>와 <b>출발 시각</b>(지금부터 최소 30분 후)을 입력합니다. 앱이 거리, 블록 타임, 도착을 계산하고 항공기 항속 거리를 확인합니다.</li>\n<li>여정을 이어가려면 <b>＋ 구간 추가</b>를 누릅니다: 다음 구간은 이전 구간이 착륙한 곳에서 출발하며, 출발은 도착 1시간 후로 제안됩니다(도착과 다음 출발 사이 최소 45분). ✕로 구간을 삭제합니다. 최대 24구간입니다.</li>\n<li>편명은 순서대로 제안되며 수정할 수 있습니다. <b>자유 비행 예약</b>(또는 <b>자유 비행 N편 예약</b>)을 누릅니다.</li></ol>\n<p>예약 후에는 스케줄과 똑같이 진행됩니다: 일정, 브리핑룸, 추적 비행, 착륙 후 보고.</p></section>\n\n<section id=\"m-reservar\"><h3>비행 일정</h3>\n<p><b>일정</b> 탭은 <b>내 일정</b>으로 시작합니다: 내 비행마다 항공기 사진, 항공사 색상의 등록 번호, 편명과 경로, 날짜와 시각(현지 및 UTC), 항공사를 담은 카드가 있습니다.</p>\n<div class=\"scroll\"><table><thead><tr><th>카드 표시</th><th>의미</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">✓ 일지에 미해결 항목 없음</span></td><td>안내로 한 번 깜빡입니다. 서명할 것 없음: <b>추적 비행</b>과 <b>비행 보고</b>를 바로 쓸 수 있습니다</td></tr>\n<tr><td><span class=\"chip warn\">⚠ 기술 일지 확인</span></td><td>계속 깜빡입니다: 항공기에 미해결 항목이 있습니다. 눌러서 항목을 읽고 서명합니다(<b>비행 전</b> 참고)</td></tr>\n<tr><td><span class=\"chip ok\">✓ 기술 일지 확인됨</span></td><td>서명을 마쳤습니다. 비행할 수 있습니다</td></tr></tbody></table></div>\n<ul><li><b>SimBrief</b>와 <b>SkyVector</b>: 오른쪽의 각 사이트 아이콘 버튼으로 해당 비행의 계획을 엽니다. SimBrief는 항공기 식별 정보와 EOBT도, SkyVector는 경로와 순항 추정치도 받습니다.</li><li><b>METAR와 TAF:</b> 공항 코드에 마우스를 올립니다(휴대폰에서는 누르기). <b>해독</b>을 누르면 쉬운 말로 읽을 수 있습니다(바람, 시정, 구름, 기온, 기압, TAF의 각 기간). <b>원문</b>은 원래 텍스트를 다시 보여 줍니다. 앱이 선택을 기억합니다.</li></ul>\n<p>스케줄 예약은 승인할 때 만들어집니다. 비행 카드로 기술 일지를 확인하고, 비행을 추적하고 보고합니다. 관리 및 이벤트 작업은 계정에서 쓸 수 있는 옵션에 따라 다릅니다.</p></section>\n\n<section id=\"m-antes\"><h3>비행 전</h3>\n<p>비행 전에 비행 카드의 기술 일지 버튼을 확인하세요:</p>\n<ul><li><b>미해결 항목 없음</b>(초록): 서명할 필요 없습니다. <b>추적 비행</b> 또는 <b>비행 보고</b>를 누르기만 하면 됩니다.</li><li><b>미해결 항목 있음</b>(노란색 깜빡임): <b>기술 일지 확인</b>을 누르고 미해결 항목과 최근 보고를 읽은 뒤 확인란에 체크하고 <b>기술 일지 서명</b>을 누릅니다. 버튼이 초록으로 바뀌고 <b>기술 일지 확인됨</b>이 표시됩니다. 이 서명이 없으면 추적과 보고가 받아들여지지 않습니다.</li><li>서명한 뒤 다른 조종사가 그 등록 번호에 결함을 보고하면 노란 버튼이 다시 나타나고 다시 서명해야 합니다.</li></ul>\n<p>결함은 시뮬레이터 사이에 옮겨지지 않으므로, 이월 항목마다 <b>다음 승무원을 위한 절차</b>가 있으며 비행 중 그대로 따릅니다. 예: <i>APU 시동 불가</i> → 지상에서 GPU와 외부 공기 요청.</p></section>\n\n<section id=\"m-rastreio\"><h3>추적 비행</h3>\n<p><b>검증된 추적</b>이 비행을 기록하고 비행 시간, 등급, 급여, 랭킹에 반영하는 기본 방법입니다. 앱이 시뮬레이터 텔레메트리를 읽고 서버가 항적을 확인합니다. 검증된 추적이 없으면 가능할 때 검토를 요청하세요. 관리자가 결정하며, 승인 전에는 비행 완료나 보상이 없습니다.</p>\n<ol><li><b>내 일정</b>의 비행 카드에서 <b>✈ 추적 비행</b>을 누릅니다(예약 시각 1시간 전부터 가능, 미해결 항목이 있으면 먼저 기술 일지에 서명).</li>\n<li>항공기가 출발 게이트에 정지한 상태에서 <b>시뮬레이터 연결</b>을 누릅니다.<ul>\n<li><b>MSFS 2020/2024:</b> <a href=\"https://fsuipc.com\" target=\"_blank\" rel=\"noopener\">FSUIPC7</a>(무료 버전이면 충분)과 <a href=\"http://fsuipcwebsockets.paulhenty.com/\" target=\"_blank\" rel=\"noopener\">FSUIPC WebSocket Server</a>를 설치하고 시뮬레이터와 함께 둘 다 열어 둡니다.</li>\n\n<li><b>X-Plane 12</b>(12.1.4 이상): 설치할 것이 없습니다.</li>\n<li><b>X-Plane 11:</b> XPUIPC 플러그인 + FSUIPC WebSocket Server.</li>\n<li>시뮬레이터와 같은 컴퓨터에서 Chrome 또는 Edge를 사용합니다. 브라우저가 로컬 네트워크 접근을 요청하면 허용합니다.</li></ul></li>\n<li>평소처럼 비행하고 탭을 열어 둡니다. <b>실시간 비행</b> 화면에 단계, 고도, 속도, 수직 속도, 목적지까지의 거리가 표시되며, 그동안 다른 화면을 사용할 수 있습니다.</li>\n<li>착륙 후 주기하고 항공기를 정지합니다. <b>비행 종료</b>를 누르면 서버가 항적을 확인하고 결과를 보여 줍니다. 이어서 보고(결함과 비고)를 작성합니다. 블록 타임과 도착 공항은 추적에서 가져옵니다.</li></ol>\n<p>다음의 경우 서버는 비행을 거부합니다: 출발 공항의 지상에서 시작하지 않음 · 공항에 정지한 상태로 끝나지 않음 · 시간 가속이나 슬루 사용 · 항공기 위치가 점프함(순간 이동 또는 지도에서 이동) · 공중에서 추적이 10분 넘게 끊김 · 항적이 실시간으로 서버에 도착하지 않음 · 공중 비행 시간이 5분 미만. 일시 정지는 괜찮습니다. 정지 시간은 빠집니다. 회항은 인정되며, 항공기는 착륙한 곳에 남습니다.</p></section>\n\n<section id=\"m-reporte\"><h3>착륙 후: 비행 보고</h3>\n<ol><li><b>비행 보고</b>를 누릅니다.</li><li><b>시뮬레이터</b>를 고르고(내 시뮬레이터만 표시되며, 다른 것은 <b>기타 시뮬레이터…</b>) <b>블록 타임</b>을 입력합니다(h:mm, 예: <code>1:45</code>).</li><li>결함마다 <b>결함 추가</b>를 누릅니다. 아무 일도 없었다면 추가하지 않습니다.</li><li><b>보고 제출 및 예약 종료</b>를 누릅니다.</li></ol>\n<p>결함 입력란에는 <b>항공사 승무원이 가장 많이 보고하는 결함</b>이 표시됩니다. 입력을 시작하면 목록이 좁혀집니다. 여러 언어를 이해하고 악센트를 무시하며 <code>brake</code>, <code>door</code>, <code>APU</code>, <code>ata 32</code>, <code>ECAM</code> 같은 용어를 압니다. 카탈로그에 없으면 <b>목록에 없음: 직접 설명</b>을 고릅니다.</p>\n<p>조종사는 조치나 기간을 고르지 않습니다. 카탈로그에서 고른 결함에 따라 정해집니다. 카탈로그 밖의 결함에는 입력한 ATA 장에서 가장 일반적인 기본값을 사용합니다.</p><div class=\"scroll\"><table><thead><tr><th>결과</th><th>항공기에 미치는 영향</th></tr></thead><tbody>\n<tr><td><span class=\"chip ok\">승무원이 해결</span></td><td>없음. 이력에만 남습니다</td></tr>\n<tr><td><span class=\"chip warn\">이월(MEL)</span></td><td>기한까지 제한 비행(Cat B 3일, Cat C 10일, Cat D 120일). 이후 수리 시간 동안 지상 대기</td></tr>\n<tr><td><span class=\"chip bad\">항공기 지상 대기</span></td><td>보고 시점부터 평균 수리 시간 동안 이용 불가</td></tr></tbody></table></div></section>\n\n<section id=\"m-frota\"><h3>기단</h3>\n<p><b>기단</b> 탭은 등록 번호별 상태를 보여 줍니다. 상단의 <b>합계는 필터를 따릅니다</b>: 선택한 항공기 수, 지금 이용 가능, 지금 비행 중, 24시간 내 예약, 제한 또는 지상 대기.</p>\n<ul><li><b>한 줄 필터:</b> 지역, 항공사, 기종, 상태, <b>정렬</b>(최근 비행, 가장 많이 비행, 이용 가능 우선, 등록 번호)과 등록 번호·기종·공항(예: <code>SBGR</code>) 검색, <b>즐겨찾기</b> 버튼.</li>\n<li><b>기종별 그룹:</b> 각 그룹에 항공기 수와 이용 가능 수가 표시됩니다.</li>\n<li><b>항공기당 한 줄:</b> 등록 번호, 기종, <b>위치</b>, <b>최근 비행</b>(예: “SBGR → SBSV · 2 d 전”) 또는 다음 일정, <b>이력</b>(VFR에서의 비행 횟수와 시간), 상태. 이용 가능한 항공기는 초록 점만 표시되고, 색 배지는 예외를 나타냅니다.</li>\n<li><b>좁은 창</b>(화면 절반): 잘리는 내용이 없도록 줄이 두 줄로 바뀝니다. 휴대폰에서는 기단이 카드로 표시됩니다.</li>\n<li><b>더 많은 항공기:</b> 목록 끝의 <b>더 보기</b>를 누릅니다. <b>등록:</b> <b>항공기 추가</b>.</li></ul>\n<div class=\"scroll\"><table><thead><tr><th>상태</th><th>의미</th><th>비행 가능?</th></tr></thead><tbody>\n<tr><td><span class=\"fv-ok\">이용 가능</span></td><td>미해결 항목이 없고 24시간 내 사용 예정 없음</td><td>예</td></tr>\n<tr><td><span class=\"pill fv-fly\">비행 중</span></td><td>지금 조종사가 사용 중. 줄에 도착 시각 표시</td><td>도착 후, 목적지에서</td></tr>\n<tr><td><span class=\"pill fv-res\">예약됨</span></td><td>24시간 내 예약 있음(시각은 배지에 표시)</td><td>예약 시간 외</td></tr>\n<tr><td><span class=\"pill warn\">제한</span></td><td>이월 항목(MEL). 절차에 따라 비행</td><td>예, 제한을 재현하여</td></tr>\n<tr><td><span class=\"pill bad\">AOG</span></td><td>정비로 지상 대기. 줄에 복귀 시각 표시</td><td>해제 후에만</td></tr>\n<tr><td><span class=\"pill fv-new\">기록 없음</span></td><td>VFR에서 비행한 적 없음. 첫 비행이 출발지를 정합니다</td><td>예</td></tr></tbody></table></div>\n<p>줄을 누르면 <b>기술 일지</b>가 열립니다: 사진, 요약(위치, 이용 가능 시점, 다음 예약, 최근 조종사), 미해결 항목과 절차, 예정 정비, 시뮬레이터용 도색, 기체 시간, 사이클, 모든 비행 페이지. 프리랜서는 프리랜서 기단만, 항공사 조종사는 항공사 기단만 봅니다.</p></section>\n\n<section id=\"m-manut\"><h3>자동 정비</h3>\n<ul><li>수리 시간이 끝나면 항공기는 자동으로 <b>이용 가능</b>으로 돌아옵니다.</li><li>시간은 보고 시점부터 실제 시간으로 흐르며, 겹치는 지상 대기는 합산됩니다.</li><li>기한이 지난 MEL 항목은 그 항목의 수리 시간 동안 항공기를 지상 대기시킵니다.</li><li>새 지상 대기 기간 안의 예약은 취소되며 앱 상단에 알림이 표시됩니다. 이후 예약은 유지됩니다. 영향을 받은 조종사에게는 같은 시간에 비어 있는 <b>같은 기종 또는 계열</b>(예: A320 계열, 737 NG/MAX, E-Jets)의 항공기가 제안되며, 한 번 누르면 같은 경로·시각·기간이 채워진 예약이 열립니다.</li></ul></section>\n\n<section id=\"m-oper\"><h3>실감 나는 운항</h3>\n<p><b>앱 내 항공기 위치.</b> 비행 이력과 시스템 예약은 ADS-B 관측과 별개입니다. 비행 알림과 기술 일지를 확인하세요. ADS-B 데이터가 항공기 위치를 바꾸거나 페리 비행을 요구하지 않습니다.</p>\n\n<p><b>회항.</b> 실제 도착은 수행한 비행과 추적/보고 데이터를 반영해야 합니다. 영향을 받은 예약의 알림을 확인하고, 시뮬레이션 회항을 ADS-B 관측과 혼동하지 마세요.</p>\n<p><b>정기 점검.</b> 비행 120시간 또는 100사이클마다 A 체크(지상 8시간), 1,200시간마다 C 체크(48시간)를 받습니다. 점검은 한도에 도달한 비행을 종료할 때 자동으로 생성되며, 그 기간의 예약은 다른 항공기 제안과 함께 취소됩니다. 남은 양은 기술 일지에 표시됩니다.</p>\n<p><b>SimBrief.</b> <b>프로필</b>(이름 옆)에 SimBrief 사용자 이름이나 Pilot ID를 입력합니다. 그러면 예약의 \"SimBrief에서 가져오기\"가 최신 계획의 항공기, 경로, 시각, 기간, 편명을 불러옵니다. 보고에서는 추적이 검증되면 블록 타임이 자동으로 채워집니다.</p>\n\n\n\n<p><b>이벤트.</b> 이벤트 탭에는 관리자가 게시한 단체 비행이 나열됩니다. \"이 이벤트용 항공기 예약\"을 누르면 출발 공항에 있을 항공기가 먼저 표시됩니다.</p>\n<p><b>알림.</b> 상단의 종은 예약이 다가올 때, 예약한 항공기에 새 보고가 있을 때, 정비로 예약이 취소되었을 때, 종료해야 할 비행이 있을 때, 그리고 이벤트와 배지를 알려 줍니다. \"이 기기의 알림\"에서 앱을 열어 두었거나 백그라운드에 있을 때 표시되는 시스템 알림을 켤 수 있습니다.</p>\n<p><b>경력.</b> 비행 일지에는 등급(비행 시간에 따라 훈련생부터 마스터 기장까지)과 배지가 표시됩니다. 등급은 명예일 뿐이며, 모든 조종사가 모든 항공기를 비행할 수 있습니다.</p></section>\n\n<section id=\"m-mapa\"><h3>지도와 비행 상세</h3>\n<p>지도는 <b>진행 중인 내 비행</b>을 우선합니다. 없으면 프로필에 사용자 이름/Pilot ID가 있을 때 최신 SimBrief 디스패치를 사용합니다. 승인된 스케줄은 바뀌지 않습니다. 다른 디스패치가 진행 중인 비행을 대체하지 않습니다. 상세 내비로그가 없으면 출발지-목적지 직선은 참고용이며 검증된 항법 경로가 아닙니다.</p>\n<p>사이드바에는 <b>추적 비행만</b> 표시되며, 공항 통계·공항 탐색·RPL 출발편은 없습니다. 오른쪽 위 레이어 컨트롤에서 기본 지도, 교통, 관제사, 오버레이를 고릅니다. 브라질 DECEA 차트에는 종류/시트와 불투명도 조절이 있습니다. 공식판을 확인하세요.</p>\n<p><b>항공기에 마우스를 올리고 클릭</b>(휴대폰에서는 누르기)하면 상세가 열립니다. 항공사를 식별할 수 있으면 머리글에 호출부호와 항공사 아이콘이 강조되고, 등록 번호 색상은 식별된 항공사를 따릅니다. 고도, 대지 속도(GS), 기수 방향(HDG), 위치, 출처 등 이용 가능한 정보가 읽기 쉽게 묶여 있습니다. 긴 팝업은 스크롤되며, 없는 데이터를 지어내지 않습니다.</p>\n<p><b>추적 중인 FlyVFR</b> 데이터는 시뮬레이터에서, <b>IVAO/VATSIM</b>은 각 네트워크에서, <b>ADS-B</b>는 실제 항공기 관측에서 옵니다. 예약 시각 기반 추정치는 텔레메트리가 아닌 추정치로 표시됩니다. ADS-B는 참고용이며 항공기 이용 가능 여부, 선택, 스케줄을 바꾸지 않습니다.</p></section>\n<section id=\"m-brief\"><h3>브리핑룸, ADC와 NOTAM</h3>\n<p>스케줄의 예약된 비행을 골라 METAR/TAF, NOTAM, 경로 기상을 봅니다. 필요하면 <b>교체 공항</b>과 그 <b>ETA</b>를 입력합니다. 교체 공항 전용 ETA가 없으면 목적지 ETA를 사용하고 그 사실을 표시합니다. 교체 공항과 ETA는 조종사/비행별로 기기에 저장되며 예약은 바뀌지 않습니다.</p>\n<p>ADC에서는 선택한 비행의 <b>출발지, 목적지, 교체 공항</b>만 평가합니다. 출발지는 EOBT, 목적지와 교체 공항은 각각의 ETA를 사용합니다. 한 공항이 여러 역할을 하면 해당 시각들을 모두 고려합니다. 만료·미래·취소·대체된 NOTAM은 유효한 것으로 강조되지 않으며, 해석할 수 없는 시간대는 확인이 필요합니다.</p>\n<p><b>ADC 레이어는 비행 시각에 유효한 것으로 확인된 NOTAM과 최신 데이터가 있을 때만 사용할 수 있습니다.</b> 그렇지 않으면 차트가 화면과 레이어에서 빠집니다. 이는 공항에 제한이 없다는 뜻이 아닙니다. 별도의 “차트 보기” 버튼은 없습니다. 공항 선택기와 지도 레이어를 사용하세요.</p>\n<ul><li><b>활주로 전면 폐쇄:</b> 명시적 문구, 양쪽 활주로 번호 쌍, 검증된 형상이 모두 있을 때만 강조됩니다.</li><li><b>본문 속 좌표:</b> ADC 이미지 밖이라도 점으로 표시됩니다. 명시적이고 유효하며 모호하지 않은 직선 경계는 점선 영역으로 나타날 수 있으며, 장애물 목록은 자동으로 연결되지 않습니다.</li><li><b>검증된 참조:</b> 유도로나 장비 표시는 차트상의 참조이며 정확한 위치가 아닐 수 있습니다. 정지선 등을 쓸 수 없다고 유도로가 폐쇄된 것은 아닙니다.</li><li><b>일반 알림:</b> 정확한 위치가 없는 유효 알림은 명확히 표시된 공항 참조 표시에 모이며, 영향 범위를 나타내지 않습니다.</li><li><b>Q 줄:</b> 중심과 반경은 참고 정보로, 활주로·유도로·장비의 정확한 위치도, 추정된 제한 범위도 아닙니다.</li></ul>\n<p>위치가 맞춰진 ADC는 검증된 공식 차트에 달려 있습니다. 차트가 없으면 그 사실을 표시하고, 위치를 지어내지 않은 채 알림을 계속 보여 줍니다. 차트 목록은 이 버전의 정적 참고 자료이며 자동으로 업데이트되지 않습니다. 항상 공식 원본을 확인하세요. <b>시뮬레이션 전용입니다.</b></p><p><b>브리핑룸 하위 메뉴:</b> 비행, 항공기, 추적 비행, 지도, 기상, NOTAM, 온라인 네트워크, 차트, 비행 계획, 브리핑 체크리스트. 각 항목은 브리핑 사이드바에 고유한 아이콘이 있습니다.</p>\n<ul><li><b>항공기:</b> 등록 번호와 기종, <b>시뮬레이터용 도색</b>(flightsim.to 또는 x-plane.org 다운로드 링크, 프로필의 시뮬레이터로 필터링), 기술 일지.</li>\n<li><b>추적 비행:</b> “시뮬레이터 연결 방법”이 같은 페이지의 비행 정보 아래에 열립니다.</li>\n<li><b>차트:</b> “이 비행 사전 선택”에서도 각 차트가 종류별 색상(ADC 파랑, SID 초록, STAR 보라, IAC 자홍…)을 유지하며 “기타 이용 가능한 차트”와 같습니다. 원하는 차트를 체크하고 <b>PDF 하나로 다운로드</b>를 사용하세요.</li></ul></section>\n<section id=\"m-redes\"><h3>IVAO와 VATSIM</h3>\n<ol><li><b>프로필</b>을 열고 원하면 <b>VATSIM CID</b>, <b>IVAO VID</b>, 선호 네트워크를 입력한 뒤 저장합니다.</li><li>브리핑의 <b>온라인 네트워크</b> 패널에 출발지·목적지·교체 공항의 해당 호출부호, 주파수, 이용 가능한 ATIS가 표시됩니다. 관제소를 펼쳐 내용을 읽거나 네트워크로 필터링하거나 새로 고칠 수 있습니다.</li><li>지도 레이어에는 네트워크별 관제사와 <b>일치하는 신고 ID</b>가 표시됩니다. 같은 지점의 관제소는 묶이며 클릭하면 읽을 수 있습니다. ID가 일치하면 관측된 호출부호가 강조됩니다.</li></ol>\n<p>선호 설정은 초기 선택을 정하며, 지도 레이어는 따로 바꿀 수 있습니다. 출처의 UTC 시각은 <b>현재 상태</b>를 나타내며 미래의 관제 가능 여부가 아닙니다. 없거나 오래된 출처는 확인되지 않은 것으로 보며, ID가 일치하지 않는다고 접속 종료가 증명되지는 않습니다. 호출부호나 표시 위치로 확장된 접근/관제소 범위나 섹터 경계를 추정하지 않습니다.</p>\n<p><b>ID는 본인이 신고한 것이며 검증된 신원이 아닙니다.</b> 이 입력란으로 네트워크에 로그인되지는 않습니다. 시뮬레이터의 네트워크 클라이언트를 사용하세요. 네트워크 감지는 보고를 검증하거나 시간을 부여하거나 앱이 요구하는 추적을 대신하지 않습니다.</p></section>\n\n<section id=\"m-diario\"><h3>비행 일지, 급여와 카탈로그</h3>\n<p><b>비행 일지 → 내 일지</b>는 비행 시간을 보여 줍니다: 합계, 최근 30일, 올해, 기종·항공사·시뮬레이터별 시간, 가장 많이 비행한 등록 번호(항공사 색상, 옆에 기종), 비행 목록이 있으며 스프레드시트용 <b>CSV 내보내기</b>가 있습니다. 시간은 각 보고의 블록 타임에서 옵니다. <b>급여</b>는 가상의 급여 명세서로, 등급과 항공기 분류에 따른 비행 시간당 금액에 체류 일당이 더해집니다. 금액은 미국 달러로 정해지며 선택한 통화로 <b>각 비행 날짜의 환율</b>로 환산됩니다(환율 열). <b>조종사 랭킹</b>은 그룹을 비교하며(전체 기간, 올해, 30일) 항공사 조종사와 프리랜서 두 개의 탭이 있습니다. 조종사를 누르면 그 일지를 볼 수 있습니다. <b>전체 기록</b>에는 보고된 모든 비행이 항공기별 일련 페이지(TL 0001…), 경로, 조종사, 시뮬레이터, 블록 타임, 결함과 함께 나열됩니다. <b>결함 카탈로그</b>에는 ATA 장별 표준 결함 123개가 기본 조치, 평균 수리 시간, MEL 기한, 절차와 함께 담겨 있습니다.</p></section>\n\n<section id=\"m-apoie\"><h3>프로젝트 후원</h3>\n<p>앱은 무료입니다. <b>후원</b> 탭에서 Pix QR 코드, Pix 복사·붙여넣기 코드 또는 안내된 다른 방법(카드, PayPal 등)으로 원하는 금액을 기부할 수 있습니다.</p></section>\n\n<section id=\"m-faq\"><h3>자주 묻는 질문</h3>\n<div class=\"scroll\"><table><thead><tr><th>상황</th><th>해결 방법</th></tr></thead><tbody>\n<tr><td>로그인할 수 없어요</td><td>이메일과 비밀번호를 확인하세요. 잊었다면 로그인 화면에서 <b>비밀번호를 잊으셨나요?</b>를 누르면 새 비밀번호를 만드는 링크가 이메일로 옵니다</td></tr>\n<tr><td>예약이 거부됐어요</td><td>빨간 메시지를 읽으세요: 시간 겹침, 정비, 범위를 벗어난 기간 또는 해당 등록 번호의 주간 한도입니다</td></tr>\n<tr><td>원하는 기간이 없어요</td><td>비행 시간 + 45분부터 비행 시간 + 2시간까지만 표시됩니다. 출발과 도착을 확인하세요</td></tr>\n<tr><td>비행 보고 버튼이 없어요</td><td>항공기에 미해결 항목이 있습니다. 노란 <b>기술 일지 확인</b> 버튼을 누르고 서명하세요</td></tr>\n<tr><td>스케줄을 취소하고 싶어요</td><td>승인한 스케줄은 취소할 수 없습니다. 비행하지 않은 편은 🔒 날짜에 자동으로 해제됩니다</td></tr>\n<tr><td>예약이 사라졌어요</td><td>정비로 취소되었을 수 있습니다. 상단 알림을 확인하세요</td></tr>\n<tr><td>METAR가 안 보여요</td><td>작은 공항은 METAR나 TAF를 발행하지 않을 수 있습니다. aviationweather.gov 링크를 사용하세요</td></tr>\n<tr><td>새 기능이 보이지 않아요</td><td>PC에서는 <b>Ctrl+Shift+R</b>을 누르고, 휴대폰에서는 앱을 닫았다가 다시 여세요</td></tr>\n<tr><td>오프라인이에요</td><td>앱은 마지막 데이터로 읽기 전용으로 열립니다. 예약과 보고에는 연결이 필요합니다</td></tr><tr><td>항공사 조종사에서 프리랜서로(또는 반대로) 바꾸고 싶어요</td><td>스케줄/자유 비행의 <b>프로필 변경</b>을 사용하세요: 30일에 한 번, 예약된 비행이 없을 때만</td></tr>\n<tr><td>프리랜서인데 기단이 비어 있어요</td><td><b>항공기 추가</b>로 직접 비행하는 항공기를(실제 등록 번호로) 등록하거나, 다른 프리랜서가 등록한 항공기를 비행하세요</td></tr></tbody></table></div></section>\n"};
for(const k of ["pt","en"])if(MANUAL[k])MANUAL[k].body=MANUAL[k].body.replace(/(manual-updated">)[^<]*/,(m,a)=>a+(k==="pt"?"Atualizado em 30/10/2026.":"Updated 30 October 2026."));
})();
